/**
 * Public configuration surface and its resolution rules.
 *
 * @remarks
 * Every option is optional and every option has a safe default, so
 * `initTelemetry({ appName: 'x' })` is a complete configuration. Resolution
 * follows one precedence rule everywhere:
 *
 * **explicit option > environment adapter (`fromEnv`) > built-in default**
 *
 * Two defensive rules apply while resolving:
 *
 * - A non-positive, `NaN` or `Infinity` numeric is **ignored**, falling back to
 *   the default. `maxRecords: 0` cannot mean "store nothing"; it means "you made a
 *   mistake", and silently disabling retention would be the surprising outcome.
 * - An unrecognised log-level string is **ignored**, keeping the previous level.
 *   A typo must never be able to turn on verbose persistence.
 *
 * @packageDocumentation
 */

import type { ErrorRecord } from '../errors/types.js';
import {
  LOG_FLUSH_BATCH_SIZE,
  LOG_FLUSH_INTERVAL_MS,
  type LogLevelSetting,
} from '../logger/logger.constants.js';
import type { ExternalLogSource, LogRecord } from '../logger/logger.types.js';
import { DEFAULT_OPEN_TIMEOUT_MS } from '../storage/idbCore.js';
import type { TelemetryRepository } from '../storage/storage.types.js';
import type { RemoteTransport } from '../sync/sync.types.js';
import { DEFAULT_ENV_PREFIXES, fromEnv } from './env.js';
import { reportInternalFailure } from './internal.js';
import type { Maybe } from './types.js';

/** Default database name prefix. Produces `rm-logvault-errors` and `rm-logvault-logs`. */
export const DEFAULT_DB_PREFIX = 'rm-logvault';

/** Default shortcut key (with Ctrl+Shift+Alt held). */
export const DEFAULT_SHORTCUT_KEY = 'd';

/** Default diagnostics report filename prefix. */
export const DEFAULT_FILENAME_PREFIX = 'diagnostics-report';

/** Error-capture configuration. */
export interface ErrorsOptions {
  /** Capture errors at all. Default `true`. */
  readonly enabled?: Maybe<boolean>;
  /** Hard cap on retained error rows. Default `500`. */
  readonly maxRecords?: Maybe<number>;
  /** Delete errors older than this. Default `7` days. */
  readonly retentionDays?: Maybe<number>;
  /** UTF-8 byte budget per record before progressive reduction. Default `16384`. */
  readonly maxPayloadBytes?: Maybe<number>;
  /** Fixed-window rate limit. Excess is dropped and summarised. Default `120`. */
  readonly maxEventsPerMinute?: Maybe<number>;
  /** Query parameter names whose values survive URL redaction. */
  readonly allowedQueryParams?: Maybe<readonly string[]>;
  /**
   * Call `preventDefault()` on `unhandledrejection`. Default `false`.
   *
   * @remarks
   * Left `false` because the library must never change host application behaviour.
   */
  readonly preventDefaultUnhandledRejection?: Maybe<boolean>;
  /** Attach a capture-phase listener for failed `<script>`/`<link>`/`<img>` loads. Default `false`. */
  readonly captureResources?: Maybe<boolean>;
  /** Listen for `securitypolicyviolation` events. Default `false`. */
  readonly captureCsp?: Maybe<boolean>;
  /** Treat dynamic-import failures as `source: 'chunk'` with `fatal` severity. Default `true`. */
  readonly captureChunkErrors?: Maybe<boolean>;
  /**
   * Last chance to inspect, modify or drop a record before storage.
   *
   * @returns the record to store, or `null` to drop it
   */
  readonly beforeCapture?: Maybe<(record: ErrorRecord) => ErrorRecord | null>;
}

/** Log-capture configuration. */
export interface LogsOptions {
  /** Persist logs at all. Default `true`. */
  readonly enabled?: Maybe<boolean>;
  /**
   * Minimum level that is persisted. Default `'warn'`.
   *
   * @remarks
   * Independent of the console level: `setLevel('off')` silences the console while
   * persistence continues.
   */
  readonly level?: Maybe<LogLevelSetting>;
  /**
   * Console verbosity to apply at initialisation.
   *
   * @remarks
   * **No default, and that is deliberate.** When this is omitted the logger keeps
   * whatever level it already has (`'warn'` until someone calls
   * `logger.setLevel(...)`), so initialising telemetry never changes console
   * output on its own. Set it to apply a build-time level — `'off'` in production,
   * `'debug'` in development — without a second call.
   */
  readonly consoleLevel?: Maybe<LogLevelSetting>;
  /** Hard cap on retained log rows. Default `2000`. */
  readonly maxRecords?: Maybe<number>;
  /** Delete logs older than this. Default `3` days. */
  readonly retentionDays?: Maybe<number>;
  /** UTF-8 byte budget per record before progressive reduction. Default `4096`. */
  readonly maxPayloadBytes?: Maybe<number>;
  /** Fixed-window rate limit. Excess is dropped and summarised. Default `600`. */
  readonly maxLogsPerMinute?: Maybe<number>;
  /**
   * How long a buffered log may sit in memory before it is written. Default `1000`
   * milliseconds.
   *
   * @remarks
   * An upper bound, not a poll interval: a write happens as soon as **either** this
   * elapses **or** {@link LogsOptions.writeBatchSize} entries have accumulated,
   * whichever comes first. Lower it if a hard crash loses too much of a burst;
   * raise it to spend fewer IndexedDB transactions on a chatty page.
   */
  readonly writeFlushMs?: Maybe<number>;
  /**
   * Number of buffered entries that triggers an immediate write. Default `50`.
   *
   * @remarks
   * This is the batch size as well as the trigger: one IndexedDB transaction
   * carries up to this many records. Raising it writes more per transaction at the
   * cost of holding more records in memory during a burst.
   */
  readonly writeBatchSize?: Maybe<number>;
  /** Wrap `console.warn`/`console.error` so existing calls are captured. Default `false`. */
  readonly captureConsole?: Maybe<boolean>;
  /**
   * Last chance to inspect, modify or drop a log record before storage.
   *
   * @returns the record to store, or `null` to drop it
   */
  readonly beforeStore?: Maybe<(record: LogRecord) => LogRecord | null>;
}

/** Redaction extensions. */
export interface RedactionOptions {
  /** Extra sensitive key names or patterns. Strings match the normalised key exactly. */
  readonly extraSensitiveKeys?: Maybe<readonly (string | RegExp)[]>;
  /** Extra free-text patterns to redact, applied after the built-in rules. */
  readonly extraPatterns?: Maybe<readonly RegExp[]>;
  /** Query parameter names whose values survive redaction, replacing the default list. */
  readonly allowedQueryParams?: Maybe<readonly string[]>;
}

/** REST upload configuration. */
export interface RestOptions {
  /** Enable uploads. Default `true` when a valid URL is supplied, otherwise `false`. */
  readonly enabled?: Maybe<boolean>;
  /** Endpoint for error batches. */
  readonly errorsUrl?: Maybe<string>;
  /** Endpoint for log batches. */
  readonly logsUrl?: Maybe<string>;
  /** Delay between successful flushes. Default `30000` ms. */
  readonly intervalMs?: Maybe<number>;
  /** Records per request. Default `50`. */
  readonly batchSize?: Maybe<number>;
  /** `fetch` credentials mode. Default `'same-origin'`. Never implicitly `'include'`. */
  readonly credentials?: Maybe<RequestCredentials>;
  /** Headers provider, awaited per request. A throwing provider is a retryable failure. */
  readonly getHeaders?: Maybe<() => Record<string, string> | Promise<Record<string, string>>>;
  /** Custom transport. Supplying one also activates sync. */
  readonly transport?: Maybe<RemoteTransport>;
  /** Reject plain `http:` endpoints except on localhost. Default `false`. */
  readonly requireHttps?: Maybe<boolean>;
  /** Called once per batch that fails terminally, so the app can re-auth and retry. */
  readonly onTerminalFailure?: Maybe<(status: number, records: readonly { id: string }[]) => void>;
}

/** Hidden diagnostics-export shortcut configuration. */
export interface ShortcutOptions {
  /** Physical key. A single letter maps to `Key<X>`. Default `'d'`. */
  readonly key?: Maybe<string>;
  /** Require Ctrl. Default `true`. */
  readonly ctrl?: Maybe<boolean>;
  /** Require Shift. Default `true`. */
  readonly shift?: Maybe<boolean>;
  /** Require Alt. Default `true`. */
  readonly alt?: Maybe<boolean>;
  /** Require Meta/Cmd. Default `false`. */
  readonly meta?: Maybe<boolean>;
  /** Event target for the listener. Defaults to `document`. */
  readonly target?: Maybe<EventTarget>;
  /** Gate that must return `true` for the shortcut to fire. */
  readonly allow?: Maybe<() => boolean>;
  /** Downloaded filename prefix. Default `'diagnostics-report'`. */
  readonly filenamePrefix?: Maybe<string>;
  /** Called with the export outcome. */
  readonly onExported?: Maybe<(ok: boolean) => void>;
}

/**
 * The single bootstrap configuration object.
 *
 * @example
 * ```ts
 * import { initTelemetry } from '@codewithrajat/rm-logvault';
 *
 * // Zero config
 * initTelemetry({ appName: 'checkout' });
 *
 * // Everything on
 * initTelemetry({
 *   appName: 'checkout',
 *   appVersion: '2.4.1',
 *   environment: 'production',
 *   errors: { maxRecords: 1000, captureCsp: true, captureResources: true },
 *   logs: { level: 'info', captureConsole: true },
 *   redaction: { allowedQueryParams: ['page', 'locale'] },
 *   rest: { errorsUrl: '/telemetry/errors', logsUrl: '/telemetry/logs' },
 *   shortcut: { key: 'd', allow: () => isInternalUser() },
 * });
 * ```
 */
/**
 * Where captured records are kept.
 *
 * @remarks
 * `'local'` is the default and means the library never touches the network.
 * `'remote'` adds an upload step on top of local persistence — records are always
 * written to IndexedDB first, so an unreachable endpoint costs nothing.
 */
export type StorageMode = 'local' | 'remote';

export interface TelemetryOptions {
  /** Application name, stamped onto every record. */
  readonly appName?: Maybe<string>;
  /** Application version. */
  readonly appVersion?: Maybe<string>;
  /** Build identifier (commit SHA, CI run id). */
  readonly buildId?: Maybe<string>;
  /** Deployment environment, e.g. `production`. */
  readonly environment?: Maybe<string>;

  // -------------------------------------------------------------------------
  // Flat aliases
  //
  // Every option below is a shorthand for a nested one, for the common case
  // where the nested object would hold a single field. They exist because
  // `initTelemetry({ url: '/telemetry', level: 'info' })` is the whole
  // configuration most applications need, and making a reader learn
  // `rest.errorsUrl` and `logs.level` to get there is a tax on the first five
  // minutes of using the library.
  //
  // Precedence is unchanged and runs **inside out**: a nested value beats its
  // flat alias, which beats the environment, which beats the built-in default.
  // So `{ url: '/a', rest: { errorsUrl: '/b' } }` uploads errors to `/b` and
  // logs to `/a`. Nothing here changes the meaning of an existing option.
  // -------------------------------------------------------------------------

  /**
   * Shorthand for `rest.errorsUrl` **and** `rest.logsUrl`.
   *
   * @remarks
   * The single-endpoint case: one collector that accepts both kinds. Set one or
   * both of {@link TelemetryOptions.errorUrl} / {@link TelemetryOptions.logUrl} to
   * split them; those win over this.
   */
  readonly url?: Maybe<string>;
  /** Shorthand for `rest.errorsUrl`. */
  readonly errorUrl?: Maybe<string>;
  /** Shorthand for `rest.logsUrl`. */
  readonly logUrl?: Maybe<string>;
  /** Shorthand for `rest.getHeaders`. */
  readonly headers?: Maybe<() => Record<string, string> | Promise<Record<string, string>>>;
  /** Shorthand for `logs.level` — the minimum level that is **persisted**. */
  readonly level?: Maybe<LogLevelSetting>;
  /** Shorthand for `logs.consoleLevel` — the console verbosity applied at init. */
  readonly consoleLevel?: Maybe<LogLevelSetting>;
  /** Shorthand for `logs.captureConsole`. */
  readonly captureConsole?: Maybe<boolean>;
  /** Shorthand for `errors.maxRecords`. */
  readonly maxErrors?: Maybe<number>;
  /** Shorthand for `logs.maxRecords`. */
  readonly maxLogs?: Maybe<number>;
  /** Shorthand for `errors.retentionDays`. */
  readonly errorRetentionDays?: Maybe<number>;
  /** Shorthand for `logs.retentionDays`. */
  readonly logRetentionDays?: Maybe<number>;

  /**
   * The simple front door.
   *
   * @remarks
   * `initTelemetry` accepts an already-flat object through the aliases above, so
   * this is a convenience rather than the only way in: it renames the handful of
   * fields whose flat name differs, and nothing else, then delegates. Prefer
   * {@link setupTelemetry} in a new integration — it reads as one line and the
   * editor offers exactly the options that matter.
   */
  readonly app?: Maybe<string>;
  /** Shorthand for `appVersion`. Used by {@link setupTelemetry}. */
  readonly version?: Maybe<string>;
  /** Shorthand for `buildId`. Used by {@link setupTelemetry}. */
  readonly build?: Maybe<string>;

  /** Master switch. `false` makes every capture call a no-op. Default `true`. */
  readonly enabled?: Maybe<boolean>;
  /**
   * Where records go.
   *
   * - `'local'` **(default)** — IndexedDB only. The library makes **no network
   *   requests at all**, so it works with no backend, in an air-gapped app, in a
   *   locked-down CSP, and with zero configuration.
   * - `'remote'` — write to IndexedDB first (always, so nothing is lost), then
   *   upload to the configured REST endpoints with retry and backoff.
   *
   * @remarks
   * You usually do not need to set this. It **infers** from whether uploads are
   * enabled: `'remote'` when `rest.enabled` is true — which itself defaults to true
   * when a `rest.errorsUrl`, `rest.logsUrl` or custom `rest.transport` is supplied —
   * and `'local'` otherwise. So "no endpoint means no upload" is the behaviour you
   * get by default, and endpoints that are configured but switched off with
   * `rest.enabled: false` correctly report `'local'`.
   *
   * Set it explicitly to be certain:
   *
   * - `mode: 'local'` — force uploads off even if a URL is configured (for
   *   example in tests, or while an endpoint is being stood up).
   * - `mode: 'remote'` — assert that records must be uploaded. If no endpoint is
   *   configured at all, the library stays local and reports
   *   `mode-remote-without-endpoint` through `onInternalError`, rather than
   *   silently discarding records.
   */
  readonly mode?: Maybe<StorageMode>;
  /** Database name prefix. Default `'rm-logvault'`. */
  readonly dbPrefix?: Maybe<string>;
  /**
   * How long to wait for an IndexedDB `open()` before declaring storage
   * unavailable. Default `5000` milliseconds.
   *
   * @remarks
   * A slow open is normal on a cold profile, and an open can hang forever when
   * another tab is holding an upgrade open. This is the upper bound that turns
   * either case into console-only operation instead of a page that waits. Raise it
   * on a slow device where storage is being given up too eagerly; lower it in tests
   * that need a fast failure.
   */
  readonly openTimeoutMs?: Maybe<number>;
  /**
   * Opt in to reading build-time environment variables.
   *
   * @remarks
   * `true` uses {@link DEFAULT_ENV_PREFIXES}; a string or array pins specific
   * prefixes. Values from the environment are applied **under** explicit options,
   * never over them. Default `false`, so the core never inspects `import.meta.env`
   * unless asked.
   */
  readonly env?: Maybe<boolean | string | readonly string[]>;
  readonly errors?: Maybe<ErrorsOptions>;
  readonly logs?: Maybe<LogsOptions>;
  readonly redaction?: Maybe<RedactionOptions>;
  readonly rest?: Maybe<RestOptions>;
  /** `false` disables the shortcut entirely. */
  readonly shortcut?: Maybe<false | ShortcutOptions>;
  /**
   * Consent gate, evaluated before every capture, persist and upload.
   *
   * @returns `true` to allow telemetry; `false` drops silently without storing.
   */
  readonly consent?: Maybe<() => boolean>;
  /** Observe the library's own internal failures without them surfacing to users. */
  readonly onInternalError?: Maybe<(stage: string, error: unknown) => void>;
  /** Swap IndexedDB for a custom backend. See `@codewithrajat/rm-logvault/testing`. */
  readonly repository?: Maybe<TelemetryRepository>;
  /** Attach to an existing application logger that exposes `addSink`. */
  readonly logSource?: Maybe<ExternalLogSource>;
}

/** Fully-resolved error options: every member present. */
export interface ResolvedErrorsOptions {
  readonly enabled: boolean;
  readonly maxRecords: number;
  readonly retentionDays: number;
  readonly maxPayloadBytes: number;
  readonly maxEventsPerMinute: number;
  readonly allowedQueryParams: readonly string[];
  readonly preventDefaultUnhandledRejection: boolean;
  readonly captureResources: boolean;
  readonly captureCsp: boolean;
  readonly captureChunkErrors: boolean;
  readonly beforeCapture: ((record: ErrorRecord) => ErrorRecord | null) | undefined;
}

/** Fully-resolved log options: every member present. */
export interface ResolvedLogsOptions {
  readonly enabled: boolean;
  readonly level: LogLevelSetting;
  /** `undefined` means "leave the console level as it is". */
  readonly consoleLevel: LogLevelSetting | undefined;
  readonly maxRecords: number;
  readonly retentionDays: number;
  readonly maxPayloadBytes: number;
  readonly maxLogsPerMinute: number;
  readonly writeFlushMs: number;
  readonly writeBatchSize: number;
  readonly captureConsole: boolean;
  readonly beforeStore: ((record: LogRecord) => LogRecord | null) | undefined;
}

/** Fully-resolved redaction options. */
export interface ResolvedRedactionOptions {
  readonly extraSensitiveKeys: readonly (string | RegExp)[];
  readonly extraPatterns: readonly RegExp[];
  readonly allowedQueryParams: readonly string[] | undefined;
}

/** Fully-resolved REST options. */
export interface ResolvedRestOptions {
  readonly enabled: boolean;
  readonly errorsUrl: string | undefined;
  readonly logsUrl: string | undefined;
  readonly intervalMs: number;
  readonly batchSize: number;
  readonly credentials: RequestCredentials;
  readonly getHeaders: (() => Record<string, string> | Promise<Record<string, string>>) | undefined;
  readonly transport: RemoteTransport | undefined;
  readonly requireHttps: boolean;
  readonly onTerminalFailure:
    | ((status: number, records: readonly { id: string }[]) => void)
    | undefined;
}

/** Fully-resolved shortcut options. */
export interface ResolvedShortcutOptions {
  readonly key: string;
  readonly ctrl: boolean;
  readonly shift: boolean;
  readonly alt: boolean;
  readonly meta: boolean;
  readonly target: EventTarget | undefined;
  readonly allow: (() => boolean) | undefined;
  readonly filenamePrefix: string;
  readonly onExported: ((ok: boolean) => void) | undefined;
}

/** Fully-resolved configuration, frozen after `initTelemetry` returns. */
export interface ResolvedTelemetryOptions {
  readonly appName: string | undefined;
  readonly appVersion: string | undefined;
  readonly buildId: string | undefined;
  readonly environment: string | undefined;
  readonly enabled: boolean;
  readonly mode: StorageMode;
  readonly dbPrefix: string;
  readonly openTimeoutMs: number;
  readonly errors: ResolvedErrorsOptions;
  readonly logs: ResolvedLogsOptions;
  readonly redaction: ResolvedRedactionOptions;
  readonly rest: ResolvedRestOptions;
  readonly shortcut: false | ResolvedShortcutOptions;
  readonly consent: (() => boolean) | undefined;
  readonly onInternalError: ((stage: string, error: unknown) => void) | undefined;
  readonly repository: TelemetryRepository | undefined;
  readonly logSource: ExternalLogSource | undefined;
}

/** Built-in defaults, exported so documentation and tests share one source of truth. */
export const DEFAULT_OPTIONS = {
  enabled: true,
  dbPrefix: DEFAULT_DB_PREFIX,
  /** Shared with the storage layer, so the wrapper's own fallback cannot drift. */
  openTimeoutMs: DEFAULT_OPEN_TIMEOUT_MS,
  errors: {
    enabled: true,
    maxRecords: 500,
    retentionDays: 7,
    maxPayloadBytes: 16_384,
    maxEventsPerMinute: 120,
    preventDefaultUnhandledRejection: false,
    captureResources: false,
    captureCsp: false,
    captureChunkErrors: true,
  },
  logs: {
    enabled: true,
    level: 'warn' as LogLevelSetting,
    /** No default: omitting it leaves the logger's own level untouched. */
    consoleLevel: undefined,
    maxRecords: 2_000,
    retentionDays: 3,
    maxPayloadBytes: 4_096,
    maxLogsPerMinute: 600,
    /** Shared with the tracker, so its batching limits cannot drift from these. */
    writeFlushMs: LOG_FLUSH_INTERVAL_MS,
    writeBatchSize: LOG_FLUSH_BATCH_SIZE,
    captureConsole: false,
  },
  rest: {
    intervalMs: 30_000,
    batchSize: 50,
    credentials: 'same-origin' as RequestCredentials,
    requireHttps: false,
  },
} as const;

/** Recognised log-level strings. Anything else is ignored. */
const VALID_LOG_LEVELS: ReadonlySet<string> = new Set([
  'trace',
  'debug',
  'info',
  'warn',
  'error',
  'off',
  'none',
  'silent',
]);

/** Normalise a level string, mapping the disable synonyms onto `'off'`. */
function normalizeLevel(input: unknown): LogLevelSetting | undefined {
  if (typeof input !== 'string') return undefined;
  const lower = input.trim().toLowerCase();
  if (!VALID_LOG_LEVELS.has(lower)) return undefined;
  if (lower === 'none' || lower === 'silent' || lower === 'off') return 'off';
  return lower as LogLevelSetting;
}

/**
 * Accept a numeric option only when it is a usable positive finite number.
 *
 * @param input - the candidate value
 * @param fallback - the default to use when the input is unusable
 * @param options - `allowZero` permits `0`, and `integer` floors the result
 */
export function positiveNumber(
  input: unknown,
  fallback: number,
  options: { allowZero?: boolean; integer?: boolean } = {},
): number {
  if (typeof input !== 'number' || !Number.isFinite(input)) return fallback;
  const minimum = options.allowZero === true ? 0 : 1;
  if (input < minimum) return fallback;
  return options.integer === true ? Math.floor(input) : input;
}

/** Accept a string option only when it is non-empty after trimming. */
function nonEmptyString(input: unknown, fallback: string | undefined): string | undefined {
  if (typeof input !== 'string') return fallback;
  const trimmed = input.trim();
  return trimmed.length > 0 ? trimmed : fallback;
}

/** Keep only well-formed `RegExp` entries from an untrusted array. */
function regexList(input: unknown): readonly RegExp[] {
  if (!Array.isArray(input)) return [];
  return input.filter((entry): entry is RegExp => entry instanceof RegExp);
}

/** Keep only string-or-RegExp entries from an untrusted array. */
function keyList(input: unknown): readonly (string | RegExp)[] {
  if (!Array.isArray(input)) return [];
  return input.filter(
    (entry): entry is string | RegExp => typeof entry === 'string' || entry instanceof RegExp,
  );
}

/** Keep only non-empty strings from an untrusted array. */
function stringList(input: unknown): readonly string[] {
  if (!Array.isArray(input)) return [];
  return input.filter((entry): entry is string => typeof entry === 'string' && entry.length > 0);
}

/** Resolve the environment layer requested by `options.env`. */
function resolveEnvLayer(options: TelemetryOptions): ReturnType<typeof fromEnv> | undefined {
  const env = options.env;
  if (env === true) return fromEnv(DEFAULT_ENV_PREFIXES);
  if (typeof env === 'string' && env.length > 0) return fromEnv(env);
  if (Array.isArray(env) && env.length > 0) return fromEnv(env);
  return undefined;
}

/**
 * Resolve user options into a frozen, fully-populated configuration.
 *
 * @param options - the caller's (partial) configuration
 * @returns a {@link ResolvedTelemetryOptions} with no `undefined` gaps
 *
 * @example
 * ```ts
 * import { resolveOptions, DEFAULT_OPTIONS } from '@codewithrajat/rm-logvault';
 *
 * resolveOptions({ errors: { maxRecords: -5 } }).errors.maxRecords;
 * // 500 — a non-positive value falls back to the default
 * ```
 */
export function resolveOptions(options: TelemetryOptions = {}): ResolvedTelemetryOptions {
  try {
    return resolveOptionsUnsafe(options);
  } catch (error) {
    // Reading even the caller's own properties can throw — a hostile getter, a
    // Proxy whose `get` trap raises. I-1 applies to this export like every other,
    // so the fallback is the documented all-defaults configuration rather than a
    // propagated exception.
    reportInternalFailure('config-resolve', error);
    return DEFAULT_RESOLVED;
  }
}

/** The body of {@link resolveOptions}, which may throw on a hostile options object. */
function resolveOptionsUnsafe(options: TelemetryOptions): ResolvedTelemetryOptions {
  const env = resolveEnvLayer(options);

  const pickBool = (explicit: unknown, fromEnvValue: unknown, fallback: boolean): boolean => {
    if (typeof explicit === 'boolean') return explicit;
    if (typeof fromEnvValue === 'boolean') return fromEnvValue;
    return fallback;
  };

  /**
   * Walk a precedence chain, converting each candidate and taking the first that
   * converts to something usable.
   *
   * @param candidates - in precedence order, highest first
   * @param convert - returns `undefined` for a value that is not usable
   * @param fallback - used when no candidate converts
   *
   * @remarks
   * This is what makes the documented "an invalid value is ignored" rule apply
   * **across** a precedence chain rather than only within one level. The obvious
   * `a ?? b` form is wrong here: a present-but-invalid `a` is not `null`, so it
   * wins the `??` and the valid `b` below it is never consulted. That silently
   * discards a caller's flat alias whenever they also passed a bad nested value —
   * for example `{ level: 'error', logs: { level: 'verbose' } }`, which should
   * resolve to `'error'` and must not fall back to the default.
   */
  const pick = <T>(
    candidates: readonly unknown[],
    convert: (input: unknown) => T | undefined,
    fallback: T,
  ): T => {
    for (const candidate of candidates) {
      const converted = convert(candidate);
      if (converted !== undefined) return converted;
    }
    return fallback;
  };

  /** Convert a candidate string, trimming and rejecting an empty result. */
  const asString = (input: unknown): string | undefined => nonEmptyString(input, undefined);

  /** Convert a candidate boolean. */
  const asBool = (input: unknown): boolean | undefined =>
    typeof input === 'boolean' ? input : undefined;

  /** Build a `positiveNumber` converter for `pick`. */
  const asPositive =
    (options2: { allowZero?: boolean; integer?: boolean } = {}) =>
    (input: unknown): number | undefined => {
      if (typeof input !== 'number' || !Number.isFinite(input)) return undefined;
      const minimum = options2.allowZero === true ? 0 : 1;
      if (input < minimum) return undefined;
      return options2.integer === true ? Math.floor(input) : input;
    };

  const errorsIn = options.errors ?? {};
  const logsIn = options.logs ?? {};
  const redactionIn = options.redaction ?? {};
  const restIn = options.rest ?? {};

  // Flat aliases, already collapsed. The explicit long name wins over the short
  // one, so `{ appName: 'a', app: 'b' }` is 'a' — surprising neither silently.
  const appName = pick(
    [options.appName, options.app, env?.appName],
    asString,
    undefined as string | undefined,
  );
  const appVersion = pick(
    [options.appVersion, options.version, env?.appVersion],
    asString,
    undefined as string | undefined,
  );
  const buildId = pick(
    [options.buildId, options.build, env?.buildId],
    asString,
    undefined as string | undefined,
  );
  const environment = pick(
    [options.environment, env?.environment],
    asString,
    undefined as string | undefined,
  );
  const dbPrefix = pick([options.dbPrefix, env?.dbPrefix], asString, DEFAULT_OPTIONS.dbPrefix);
  const openTimeoutMs = pick(
    [options.openTimeoutMs, env?.openTimeoutMs],
    asPositive({ integer: true }),
    DEFAULT_OPTIONS.openTimeoutMs,
  );

  // ---- errors -------------------------------------------------------------
  const errorAllowedQueryParams =
    errorsIn.allowedQueryParams !== undefined
      ? stringList(errorsIn.allowedQueryParams)
      : redactionIn.allowedQueryParams !== undefined
        ? stringList(redactionIn.allowedQueryParams)
        : undefined;

  const resolvedErrors: ResolvedErrorsOptions = {
    enabled: pickBool(errorsIn.enabled, env?.errorsEnabled, DEFAULT_OPTIONS.errors.enabled),
    maxRecords: pick(
      [errorsIn.maxRecords, options.maxErrors, env?.errorsMaxRecords],
      asPositive({ integer: true }),
      DEFAULT_OPTIONS.errors.maxRecords,
    ),
    retentionDays: pick(
      [errorsIn.retentionDays, options.errorRetentionDays, env?.errorsRetentionDays],
      asPositive({ allowZero: true }),
      DEFAULT_OPTIONS.errors.retentionDays,
    ),
    maxPayloadBytes: positiveNumber(
      errorsIn.maxPayloadBytes ?? env?.errorsMaxPayloadBytes,
      DEFAULT_OPTIONS.errors.maxPayloadBytes,
      { integer: true },
    ),
    maxEventsPerMinute: positiveNumber(
      errorsIn.maxEventsPerMinute ?? env?.errorsMaxEventsPerMinute,
      DEFAULT_OPTIONS.errors.maxEventsPerMinute,
      { allowZero: true, integer: true },
    ),
    allowedQueryParams: errorAllowedQueryParams ?? [],
    preventDefaultUnhandledRejection:
      errorsIn.preventDefaultUnhandledRejection ??
      DEFAULT_OPTIONS.errors.preventDefaultUnhandledRejection,
    captureResources: errorsIn.captureResources ?? DEFAULT_OPTIONS.errors.captureResources,
    captureCsp: errorsIn.captureCsp ?? DEFAULT_OPTIONS.errors.captureCsp,
    captureChunkErrors: errorsIn.captureChunkErrors ?? DEFAULT_OPTIONS.errors.captureChunkErrors,
    beforeCapture:
      typeof errorsIn.beforeCapture === 'function' ? errorsIn.beforeCapture : undefined,
  };

  // ---- logs ---------------------------------------------------------------
  // Console level: the explicit option, then `logs.consoleLevel`, then `LOG_LEVEL`.
  // There is no default, so omitting all three leaves whatever level the logger
  // already has. `undefined` here means exactly that, which is why the chain is
  // walked by hand rather than through `pick` (whose fallback must be a value).
  const resolvedConsoleLevel: LogLevelSetting | undefined =
    normalizeLevel(logsIn.consoleLevel) ??
    normalizeLevel(options.consoleLevel) ??
    normalizeLevel(env?.consoleLevel);

  // Persist level, in precedence order: `logs.level`, then the flat `level`, then
  // `LOG_PERSIST_LEVEL`, then the legacy `TELEMETRY_LOG_LEVEL` (which has always
  // meant the persist level and must not start changing console output), then
  // `LOG_LEVEL` — the documented inheritance for an empty persist level — and
  // finally the built-in default.
  //
  // Each candidate is normalised as it is considered, so an unrecognised level
  // falls through to the next rather than stopping the chain.
  const resolvedLevel: LogLevelSetting = pick(
    [logsIn.level, options.level, env?.persistLevel, env?.logLevel, env?.consoleLevel],
    normalizeLevel,
    DEFAULT_OPTIONS.logs.level,
  );

  const resolvedLogs: ResolvedLogsOptions = {
    enabled: pickBool(logsIn.enabled, env?.logsEnabled, DEFAULT_OPTIONS.logs.enabled),
    level: resolvedLevel,
    consoleLevel: resolvedConsoleLevel,
    maxRecords: pick(
      [logsIn.maxRecords, options.maxLogs, env?.logsMaxRecords],
      asPositive({ integer: true }),
      DEFAULT_OPTIONS.logs.maxRecords,
    ),
    retentionDays: pick(
      [logsIn.retentionDays, options.logRetentionDays, env?.logsRetentionDays],
      asPositive({ allowZero: true }),
      DEFAULT_OPTIONS.logs.retentionDays,
    ),
    maxPayloadBytes: positiveNumber(
      logsIn.maxPayloadBytes ?? env?.logsMaxPayloadBytes,
      DEFAULT_OPTIONS.logs.maxPayloadBytes,
      {
        integer: true,
      },
    ),
    maxLogsPerMinute: positiveNumber(
      logsIn.maxLogsPerMinute ?? env?.logsMaxLogsPerMinute,
      DEFAULT_OPTIONS.logs.maxLogsPerMinute,
      {
        allowZero: true,
        integer: true,
      },
    ),
    writeFlushMs: positiveNumber(
      logsIn.writeFlushMs ?? env?.logsWriteFlushMs,
      DEFAULT_OPTIONS.logs.writeFlushMs,
      { integer: true },
    ),
    writeBatchSize: positiveNumber(
      logsIn.writeBatchSize ?? env?.logsWriteBatchSize,
      DEFAULT_OPTIONS.logs.writeBatchSize,
      { integer: true },
    ),
    captureConsole: pick(
      [logsIn.captureConsole, options.captureConsole],
      asBool,
      DEFAULT_OPTIONS.logs.captureConsole,
    ),
    beforeStore: typeof logsIn.beforeStore === 'function' ? logsIn.beforeStore : undefined,
  };

  // ---- redaction ----------------------------------------------------------
  const resolvedRedaction: ResolvedRedactionOptions = {
    extraSensitiveKeys: keyList(redactionIn.extraSensitiveKeys),
    extraPatterns: regexList(redactionIn.extraPatterns),
    allowedQueryParams:
      redactionIn.allowedQueryParams !== undefined
        ? stringList(redactionIn.allowedQueryParams)
        : errorsIn.allowedQueryParams !== undefined
          ? stringList(errorsIn.allowedQueryParams)
          : undefined,
  };

  // ---- rest ---------------------------------------------------------------
  // Endpoint precedence, innermost first: `rest.errorsUrl` / `rest.logsUrl`, then
  // the flat `errorUrl` / `logUrl`, then the shared flat `url`, then the
  // environment. A single `url` is the one-collector case and feeds both kinds.
  // Walked with `pick`, so an empty-string or whitespace nested endpoint falls
  // through to the flat alias instead of silently disabling both.
  const errorsUrl = pick(
    [restIn.errorsUrl, options.errorUrl, options.url, env?.errorsUrl],
    asString,
    undefined as string | undefined,
  );
  const logsUrl = pick(
    [restIn.logsUrl, options.logUrl, options.url, env?.logsUrl],
    asString,
    undefined as string | undefined,
  );
  const transport = restIn.transport;
  const restEnabledByDefault =
    transport !== undefined || errorsUrl !== undefined || logsUrl !== undefined;

  const resolvedRestEnabled = pickBool(restIn.enabled, env?.restEnabled, restEnabledByDefault);

  // An explicit `mode` always wins. Otherwise it follows whether uploads are
  // actually enabled — not merely whether a URL is present, so a deployment that
  // configures endpoints and then switches them off with `rest.enabled: false`
  // reports the truth: `'local'`. Upload behaviour itself is unchanged either way,
  // because the sync manager requires mode, `rest.enabled` *and* an endpoint.
  const explicitMode: StorageMode | undefined =
    options.mode === 'local' || options.mode === 'remote' ? options.mode : undefined;
  const mode: StorageMode = explicitMode ?? (resolvedRestEnabled ? 'remote' : 'local');

  const resolvedRest: ResolvedRestOptions = {
    enabled: resolvedRestEnabled,
    errorsUrl,
    logsUrl,
    intervalMs: positiveNumber(
      restIn.intervalMs ?? env?.restIntervalMs,
      DEFAULT_OPTIONS.rest.intervalMs,
      {
        integer: true,
      },
    ),
    batchSize: positiveNumber(
      restIn.batchSize ?? env?.restBatchSize,
      DEFAULT_OPTIONS.rest.batchSize,
      { integer: true },
    ),
    credentials:
      restIn.credentials === 'omit' ||
      restIn.credentials === 'same-origin' ||
      restIn.credentials === 'include'
        ? restIn.credentials
        : DEFAULT_OPTIONS.rest.credentials,
    getHeaders:
      typeof restIn.getHeaders === 'function'
        ? restIn.getHeaders
        : typeof options.headers === 'function'
          ? options.headers
          : undefined,
    transport,
    requireHttps: restIn.requireHttps ?? DEFAULT_OPTIONS.rest.requireHttps,
    onTerminalFailure:
      typeof restIn.onTerminalFailure === 'function' ? restIn.onTerminalFailure : undefined,
  };

  // ---- shortcut -----------------------------------------------------------
  let shortcut: false | ResolvedShortcutOptions = false;
  if (options.shortcut !== false) {
    const shortcutIn = options.shortcut ?? {};
    shortcut = {
      key: nonEmptyString(shortcutIn.key, DEFAULT_SHORTCUT_KEY) ?? DEFAULT_SHORTCUT_KEY,
      ctrl: shortcutIn.ctrl ?? true,
      shift: shortcutIn.shift ?? true,
      alt: shortcutIn.alt ?? true,
      meta: shortcutIn.meta ?? false,
      target: shortcutIn.target,
      allow: typeof shortcutIn.allow === 'function' ? shortcutIn.allow : undefined,
      filenamePrefix:
        nonEmptyString(shortcutIn.filenamePrefix, DEFAULT_FILENAME_PREFIX) ??
        DEFAULT_FILENAME_PREFIX,
      onExported: typeof shortcutIn.onExported === 'function' ? shortcutIn.onExported : undefined,
    };
  }

  return Object.freeze({
    appName,
    appVersion,
    buildId,
    environment,
    enabled:
      typeof options.enabled === 'boolean'
        ? options.enabled
        : (env?.enabled ?? DEFAULT_OPTIONS.enabled),
    mode,
    dbPrefix,
    openTimeoutMs,
    errors: Object.freeze(resolvedErrors),
    logs: Object.freeze(resolvedLogs),
    redaction: Object.freeze(resolvedRedaction),
    rest: Object.freeze(resolvedRest),
    shortcut: shortcut === false ? false : Object.freeze(shortcut),
    consent: typeof options.consent === 'function' ? options.consent : undefined,
    onInternalError:
      typeof options.onInternalError === 'function' ? options.onInternalError : undefined,
    repository: options.repository,
    logSource: options.logSource,
  });
}

/**
 * The all-defaults configuration, used as the fail-closed fallback when a hostile
 * options object makes resolution impossible.
 *
 * @remarks
 * Frozen and shared, so returning it cannot be mutated by a caller. It is
 * equivalent to `resolveOptions({})`, which is a complete and safe configuration:
 * local-only, no endpoint, every limit at its default.
 */
export const DEFAULT_RESOLVED: ResolvedTelemetryOptions = Object.freeze({
  appName: undefined,
  appVersion: undefined,
  buildId: undefined,
  environment: undefined,
  enabled: DEFAULT_OPTIONS.enabled,
  mode: 'local' as StorageMode,
  dbPrefix: DEFAULT_OPTIONS.dbPrefix,
  openTimeoutMs: DEFAULT_OPTIONS.openTimeoutMs,
  errors: Object.freeze({
    enabled: DEFAULT_OPTIONS.errors.enabled,
    maxRecords: DEFAULT_OPTIONS.errors.maxRecords,
    retentionDays: DEFAULT_OPTIONS.errors.retentionDays,
    maxPayloadBytes: DEFAULT_OPTIONS.errors.maxPayloadBytes,
    maxEventsPerMinute: DEFAULT_OPTIONS.errors.maxEventsPerMinute,
    allowedQueryParams: [],
    preventDefaultUnhandledRejection: DEFAULT_OPTIONS.errors.preventDefaultUnhandledRejection,
    captureResources: DEFAULT_OPTIONS.errors.captureResources,
    captureCsp: DEFAULT_OPTIONS.errors.captureCsp,
    captureChunkErrors: DEFAULT_OPTIONS.errors.captureChunkErrors,
    beforeCapture: undefined,
  }),
  logs: Object.freeze({
    enabled: DEFAULT_OPTIONS.logs.enabled,
    level: DEFAULT_OPTIONS.logs.level,
    consoleLevel: undefined,
    maxRecords: DEFAULT_OPTIONS.logs.maxRecords,
    retentionDays: DEFAULT_OPTIONS.logs.retentionDays,
    maxPayloadBytes: DEFAULT_OPTIONS.logs.maxPayloadBytes,
    maxLogsPerMinute: DEFAULT_OPTIONS.logs.maxLogsPerMinute,
    writeFlushMs: DEFAULT_OPTIONS.logs.writeFlushMs,
    writeBatchSize: DEFAULT_OPTIONS.logs.writeBatchSize,
    captureConsole: DEFAULT_OPTIONS.logs.captureConsole,
    beforeStore: undefined,
  }),
  redaction: Object.freeze({
    extraSensitiveKeys: [],
    extraPatterns: [],
    allowedQueryParams: undefined,
  }),
  rest: Object.freeze({
    enabled: false,
    errorsUrl: undefined,
    logsUrl: undefined,
    intervalMs: DEFAULT_OPTIONS.rest.intervalMs,
    batchSize: DEFAULT_OPTIONS.rest.batchSize,
    credentials: DEFAULT_OPTIONS.rest.credentials,
    getHeaders: undefined,
    transport: undefined,
    requireHttps: DEFAULT_OPTIONS.rest.requireHttps,
    onTerminalFailure: undefined,
  }),
  shortcut: Object.freeze({
    key: DEFAULT_SHORTCUT_KEY,
    ctrl: true,
    shift: true,
    alt: true,
    meta: false,
    target: undefined,
    allow: undefined,
    filenamePrefix: DEFAULT_FILENAME_PREFIX,
    onExported: undefined,
  }),
  consent: undefined,
  onInternalError: undefined,
  repository: undefined,
  logSource: undefined,
});

/**
 * Names of the two IndexedDB databases derived from `dbPrefix`.
 *
 * @remarks
 * Never throws. A prefix that cannot be interpolated — a `Symbol`, or an object
 * with a hostile `Symbol.toPrimitive` — falls back to the default prefix rather
 * than raising `TypeError` out of an exported function.
 */
export function databaseNames(dbPrefix: string): {
  readonly errors: string;
  readonly logs: string;
} {
  let prefix = DEFAULT_DB_PREFIX;
  try {
    const candidate = `${dbPrefix}`;
    if (candidate.length > 0) prefix = candidate;
  } catch (error) {
    reportInternalFailure('database-names', error);
  }
  return { errors: `${prefix}-errors`, logs: `${prefix}-logs` };
}
