/**
 * IndexedDB persistence for log records.
 *
 * @remarks
 * Logs are appended, never aggregated — each call is its own event, and merging
 * them would destroy the ordering that makes a log trail useful. The repository is
 * otherwise a mirror of {@link createErrorRepository}: atomic
 * {@link LogRepository.claimPending}, stale-lease requeue, retention cleanup and
 * quota recovery.
 *
 * Batches are written one `readwrite` transaction per call, so a 50-entry batch
 * costs one transaction rather than fifty.
 *
 * @packageDocumentation
 */

import type { Maybe, Timestamp, UploadStatus } from '../core/types.js';
import type { LogRecord } from '../logger/logger.types.js';
import type { DbConnection, IdbCoreOptions } from './idbCore.js';
import { createDbConnection, promisifyRequest } from './idbCore.js';
import { cleanupStore, deleteByIds, halvedPolicy, updateStatuses } from './repositoryUtils.js';
import {
  DEFAULT_PENDING_LIMIT,
  LOG_CLEANUP_EVERY_WRITES,
  LOGS_DB_VERSION,
  LOGS_INDEX_STATUS_TIMESTAMP,
  LOGS_INDEX_TIMESTAMP,
  LOGS_STORE,
} from './storage.constants.js';
import type {
  CleanupPolicy,
  LogRepository,
  StorageFailureReason,
  StorageResult,
} from './storage.types.js';
import { isLogRecord } from './validate.js';

/** Options for {@link createLogRepository}. */
export interface LogRepositoryOptions {
  /** Physical database name, e.g. `rm-logvault-logs`. */
  readonly dbName: string;
  /** Explicit `IDBFactory`. Defaults to `globalThis.indexedDB`. */
  readonly indexedDB?: Maybe<IDBFactory>;
  /** Called once per distinct failure class. */
  readonly onFailure?: Maybe<(reason: StorageFailureReason, error: unknown) => void>;
  /** Retention policy. When omitted, automatic cleanup is disabled. */
  readonly cleanupPolicy?: Maybe<CleanupPolicy>;
  /** How often to run automatic retention. Default {@link LOG_CLEANUP_EVERY_WRITES}. */
  readonly cleanupEveryWrites?: Maybe<number>;
  /** Open timeout passed through to the connection. */
  readonly openTimeoutMs?: Maybe<number>;
}

/** Create the object store and indexes. Idempotent: safe to re-run. */
function upgradeLogs(db: IDBDatabase, _oldVersion: number, transaction: IDBTransaction): void {
  if (!db.objectStoreNames.contains(LOGS_STORE)) {
    const store = db.createObjectStore(LOGS_STORE, { keyPath: 'id' });
    store.createIndex(LOGS_INDEX_STATUS_TIMESTAMP, ['uploadStatus', 'timestamp'], {
      unique: false,
    });
    store.createIndex(LOGS_INDEX_TIMESTAMP, 'timestamp', { unique: false });
    return;
  }

  const store = transaction.objectStore(LOGS_STORE);
  if (!store.indexNames.contains(LOGS_INDEX_STATUS_TIMESTAMP)) {
    store.createIndex(LOGS_INDEX_STATUS_TIMESTAMP, ['uploadStatus', 'timestamp'], {
      unique: false,
    });
  }
  if (!store.indexNames.contains(LOGS_INDEX_TIMESTAMP)) {
    store.createIndex(LOGS_INDEX_TIMESTAMP, 'timestamp', { unique: false });
  }
}

/** Structural type of the global `IDBKeyRange` constructor. */
type KeyRangeFactory = {
  only(value: IDBValidKey): IDBKeyRange;
  bound(
    lower: IDBValidKey,
    upper: IDBValidKey,
    lowerOpen?: boolean,
    upperOpen?: boolean,
  ): IDBKeyRange;
};

/** Resolve the global `IDBKeyRange` constructor, or `undefined`. */
function keyRangeFactory(): KeyRangeFactory | undefined {
  try {
    const ctor: unknown = Reflect.get(globalThis, 'IDBKeyRange');
    return typeof ctor === 'function' ? (ctor as unknown as KeyRangeFactory) : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Key range selecting every row with a given upload status.
 *
 * @remarks
 * The logs index is **compound** (`['uploadStatus', 'timestamp']`), so
 * `IDBKeyRange.only('pending')` matches nothing: IndexedDB orders a bare string
 * *before* any array, and a compound index key is always an array. The correct
 * range brackets the status with an empty array on the upper side, because every
 * array sorts after every string and every number.
 */
function statusKeyRange(status: UploadStatus): IDBKeyRange | undefined {
  const factory = keyRangeFactory();
  if (factory === undefined) return undefined;
  try {
    return factory.bound([status], [status, []], false, true);
  } catch {
    return undefined;
  }
}

/**
 * Create a log repository backed by IndexedDB.
 *
 * @param options - see {@link LogRepositoryOptions}
 * @returns a {@link LogRepository}. Construction never opens the database.
 *
 * @example
 * ```ts
 * import { createLogRepository } from '@codewithrajat/rm-logvault';
 *
 * const repository = createLogRepository({ dbName: 'rm-logvault-logs' });
 * await repository.initialize();
 * await repository.saveBatch(records);
 * const batch = await repository.claimPending(50, Date.now());
 * ```
 */
export function createLogRepository(options: LogRepositoryOptions): LogRepository {
  const connectionOptions: IdbCoreOptions = {
    dbName: options.dbName,
    version: LOGS_DB_VERSION,
    storeName: LOGS_STORE,
    upgrade: upgradeLogs,
    ...(options.indexedDB !== undefined ? { indexedDB: options.indexedDB } : {}),
    ...(options.onFailure !== undefined ? { onFailure: options.onFailure } : {}),
    ...(options.openTimeoutMs !== undefined ? { openTimeoutMs: options.openTimeoutMs } : {}),
  };
  const connection: DbConnection = createDbConnection(connectionOptions);

  const cleanupEvery = Math.max(1, options.cleanupEveryWrites ?? LOG_CLEANUP_EVERY_WRITES);
  let writesSinceCleanup = 0;
  let cleanupDisabled = false;

  const policy = (): CleanupPolicy | undefined => options.cleanupPolicy;

  const runCleanup = async (override?: CleanupPolicy): Promise<StorageResult<number>> => {
    const active = override ?? policy();
    if (active === undefined) return { ok: true, value: 0 };
    const now = Date.now();
    return connection.transaction('readwrite', (store) =>
      cleanupStore<LogRecord>(store, active, (record) => record.timestamp, now, isLogRecord),
    );
  };

  const saveBatch = async (records: readonly LogRecord[]): Promise<StorageResult<void>> => {
    if (records.length === 0) return { ok: true, value: undefined };

    const attempt = async (): Promise<StorageResult<void>> =>
      connection.transaction('readwrite', async (store) => {
        for (const record of records) {
          await promisifyRequest(store.put(record));
        }
      });

    let result = await attempt();

    if (!result.ok && result.reason === 'quota') {
      const active = policy();
      if (active !== undefined) {
        await runCleanup(halvedPolicy(active));
        result = await attempt();
      }
    }

    if (result.ok) {
      writesSinceCleanup += records.length;
      if (!cleanupDisabled && writesSinceCleanup >= cleanupEvery) {
        writesSinceCleanup = 0;
        const cleaned = await runCleanup();
        if (!cleaned.ok) cleanupDisabled = true;
      }
    }

    return result;
  };

  /**
   * Read every row, newest first, deleting anything malformed.
   *
   * @remarks
   * Two transactions, deliberately: a `readonly` pass collects the valid rows and
   * the primary keys of the malformed ones, then a `readwrite` pass (only when
   * something was malformed) deletes them. Deleting inside the read transaction
   * would throw `ReadOnlyError` and fail the whole read.
   */
  const readAllValidated = async (): Promise<StorageResult<LogRecord[]>> => {
    const first = await connection.transaction('readonly', async (store) => {
      const raw = await promisifyRequest<unknown[]>(store.getAll());
      const valid: LogRecord[] = [];
      const malformed: string[] = [];
      for (const entry of raw) {
        if (isLogRecord(entry)) valid.push(entry);
        else if (entry !== null && typeof entry === 'object') {
          const id = (entry as { id?: unknown }).id;
          if (typeof id === 'string') malformed.push(id);
        }
      }
      return { valid, malformed };
    });

    if (!first.ok) return first;

    if (first.value.malformed.length > 0) {
      await connection.transaction('readwrite', (store) =>
        deleteByIds(store, first.value.malformed),
      );
    }

    // Newest first for the diagnostics report; `seq` breaks same-millisecond ties.
    return {
      ok: true,
      value: first.value.valid.sort((a, b) => b.timestamp - a.timestamp || b.seq - a.seq),
    };
  };

  /** Read rows in one upload state, oldest first so server order matches reality. */
  const readByStatus = async (
    status: UploadStatus,
    limit: number,
  ): Promise<StorageResult<LogRecord[]>> =>
    connection.transaction('readonly', async (store) => {
      const index = store.index(LOGS_INDEX_STATUS_TIMESTAMP);
      const range = statusKeyRange(status);
      const collected: LogRecord[] = [];

      await new Promise<void>((resolve, reject) => {
        const request = range === undefined ? index.openCursor() : index.openCursor(range);
        request.onerror = (): void => {
          reject(request.error ?? new Error('cursor failed'));
        };
        request.onsuccess = (): void => {
          const cursor = request.result;
          if (cursor === null) {
            resolve();
            return;
          }
          const value = cursor.value as unknown;
          if (isLogRecord(value) && value.uploadStatus === status) collected.push(value);
          cursor.continue();
        };
      });

      const sorted = collected.sort((a, b) => a.timestamp - b.timestamp || a.seq - b.seq);
      return limit > 0 ? sorted.slice(0, limit) : sorted;
    });

  const claimPending = async (limit: number, now: Timestamp): Promise<StorageResult<LogRecord[]>> =>
    connection.transaction('readwrite', async (store) => {
      const index = store.index(LOGS_INDEX_STATUS_TIMESTAMP);
      const range = statusKeyRange('pending');
      const claimed: LogRecord[] = [];

      await new Promise<void>((resolve, reject) => {
        const request = range === undefined ? index.openCursor() : index.openCursor(range);
        request.onerror = (): void => {
          reject(request.error ?? new Error('cursor failed'));
        };
        request.onsuccess = (): void => {
          const cursor = request.result;
          if (cursor === null || claimed.length >= limit) {
            resolve();
            return;
          }
          const value = cursor.value as unknown;
          if (isLogRecord(value) && value.uploadStatus === 'pending') {
            const updated: LogRecord = {
              ...value,
              uploadStatus: 'uploading',
              uploadAttempts: value.uploadAttempts + 1,
              claimedAt: now,
            };
            cursor.update(updated);
            claimed.push(updated);
          }
          cursor.continue();
        };
      });

      return claimed;
    });

  const requeueStale = async (
    olderThanMs: number,
    now: Timestamp,
  ): Promise<StorageResult<number>> =>
    connection.transaction('readwrite', async (store) => {
      const index = store.index(LOGS_INDEX_STATUS_TIMESTAMP);
      const range = statusKeyRange('uploading');
      let requeued = 0;

      await new Promise<void>((resolve, reject) => {
        const request = range === undefined ? index.openCursor() : index.openCursor(range);
        request.onerror = (): void => {
          reject(request.error ?? new Error('cursor failed'));
        };
        request.onsuccess = (): void => {
          const cursor = request.result;
          if (cursor === null) {
            resolve();
            return;
          }
          const value = cursor.value as unknown;
          if (isLogRecord(value) && value.uploadStatus === 'uploading') {
            const claimedAt = value.claimedAt;
            if (claimedAt === undefined || now - claimedAt > olderThanMs) {
              const updated: LogRecord = { ...value, uploadStatus: 'pending' };
              delete (updated as { claimedAt?: Maybe<Timestamp> }).claimedAt;
              cursor.update(updated);
              requeued += 1;
            }
          }
          cursor.continue();
        };
      });

      return requeued;
    });

  return {
    initialize: async (): Promise<StorageResult<void>> => {
      const opened = await connection.ensureOpen();
      if (!opened.ok) return { ok: false, reason: opened.reason };
      const cleaned = await runCleanup();
      if (!cleaned.ok) {
        options.onFailure?.(cleaned.reason, new Error('initial cleanup failed'));
      }
      return { ok: true, value: undefined };
    },

    saveBatch,

    get: async (id: string): Promise<StorageResult<Maybe<LogRecord>>> =>
      connection.transaction('readonly', async (store) => {
        const raw = await promisifyRequest<unknown>(store.get(id));
        return isLogRecord(raw) ? raw : undefined;
      }),

    getAll: readAllValidated,

    getPending: (limit = DEFAULT_PENDING_LIMIT) => readByStatus('pending', limit),

    claimPending,

    requeueStale,

    getFailed: () => readByStatus('failed', 0),

    delete: async (ids: readonly string[]): Promise<StorageResult<number>> =>
      connection.transaction('readwrite', (store) => deleteByIds(store, ids)),

    updateUploadStatus: async (
      ids: readonly string[],
      status: UploadStatus,
    ): Promise<StorageResult<number>> =>
      connection.transaction('readwrite', (store) =>
        updateStatuses(store, ids, status, Date.now()),
      ),

    count: async (): Promise<StorageResult<number>> =>
      connection.transaction('readonly', (store) => promisifyRequest<number>(store.count())),

    pendingCount: async (): Promise<StorageResult<number>> =>
      connection.transaction('readonly', async (store) => {
        let total = 0;
        await new Promise<void>((resolve, reject) => {
          const request = store.openCursor();
          request.onerror = (): void => {
            reject(request.error ?? new Error('cursor failed'));
          };
          request.onsuccess = (): void => {
            const cursor = request.result;
            if (cursor === null) {
              resolve();
              return;
            }
            const value = cursor.value as unknown;
            if (
              isLogRecord(value) &&
              (value.uploadStatus === 'pending' || value.uploadStatus === 'uploading')
            ) {
              total += 1;
            }
            cursor.continue();
          };
        });
        return total;
      }),

    cleanup: (activePolicy: CleanupPolicy): Promise<StorageResult<number>> =>
      runCleanup(activePolicy),

    clear: async (): Promise<StorageResult<number>> =>
      connection.transaction('readwrite', async (store) => {
        const before = await promisifyRequest<number>(store.count());
        await promisifyRequest(store.clear());
        return before;
      }),

    close: (): void => {
      connection.close();
    },
  };
}
