/**
 * Diagnostics export: flush, read everything, build one file, download it.
 *
 * @remarks
 * The export is the last line of support, so it is deliberately forgiving:
 *
 * - It **never throws**; it returns `false`.
 * - It reads **all** records regardless of upload status, so a record stuck in
 *   `failed` or still `pending` is still in the report.
 * - It **flushes first**, so a log written a millisecond ago is included.
 * - It marshals large sets in 500-record slices with a yield between slices, so a
 *   50 000-row vault does not freeze the tab.
 * - It **defers `revokeObjectURL`**, because revoking synchronously after
 *   `click()` cancels the download in some Safari versions.
 *
 * @packageDocumentation
 */

import { DEFAULT_FILENAME_PREFIX } from '../core/config.js';
import {
  getDocument,
  getNavigator,
  getWindow,
  isBrowser,
  isOnline,
  now,
  safeGet,
} from '../core/env.js';
import { reportInternalFailure } from '../core/internal.js';
import { getState } from '../core/state.js';
import { MAX_URL_LENGTH, MAX_USER_AGENT_LENGTH } from '../errors/constants.js';
import { byteLength } from '../errors/payload.js';
import { getDefaultSanitizer } from '../errors/sanitize.js';
import type { ErrorRecord } from '../errors/types.js';
import type { LogRecord } from '../logger/logger.types.js';
import { sanitizeErrorRecord, sanitizeLogRecord } from './redactRecords.js';
import type { ReportMeta } from './reportTemplate.js';
import { escapeJsonText, renderDiagnosticsReport } from './reportTemplate.js';

/** Records marshalled per slice before yielding to the event loop. */
export const EXPORT_SLICE_SIZE = 500;

/**
 * Output format of the export.
 *
 * @remarks
 * - `'html'` — the self-contained report, with the JSON payload embedded.
 * - `'json'` — one document: `{ schemaVersion, generatedAt, app, page, errors, logs }`.
 * - `'jsonl'` — one JSON object per line, `{"kind":"error",…}` or `{"kind":"log",…}`.
 *   Made for `grep`, `jq` and a log pipeline.
 * - `'csv'` — a single wide table, one row per record, openable in a spreadsheet.
 */
export type DiagnosticsFormat = 'html' | 'json' | 'jsonl' | 'csv';

/** Options for {@link exportDiagnosticsReport}. */
export interface DiagnosticsExportOptions {
  /** Output format. Default `'html'`. */
  readonly format?: DiagnosticsFormat | undefined;
  /**
   * Copy the report to the clipboard instead of downloading it.
   *
   * @remarks
   * Feature-detected; when the Clipboard API is unavailable the call returns
   * `false` rather than falling back to a download the user did not ask for.
   */
  readonly copyToClipboard?: boolean | undefined;
  /**
   * Indent the JSON output for readability.
   *
   * @remarks
   * Applies to `'json'` only. It is deliberately ignored by `'jsonl'`, where an
   * indented object would break the one-record-per-line contract.
   */
  readonly pretty?: boolean | undefined;
  /**
   * Re-run the sanitizer over every record before export. Default `false`.
   *
   * @remarks
   * Redaction already happened before storage. Enable this when the redaction
   * configuration changed after the records were written, or when exporting for a
   * third party and you want a documented second pass.
   */
  readonly redactAgain?: boolean | undefined;
  /** Filename prefix. Defaults to the shortcut's `filenamePrefix`, then `'diagnostics-report'`. */
  readonly filenamePrefix?: string | undefined;
  /**
   * Called as records are marshalled, so a UI can show progress.
   *
   * @param processed - records marshalled so far
   * @param total - total records, errors plus logs
   *
   * @remarks
   * Invoked once per {@link EXPORT_SLICE_SIZE} records and once at the end. A
   * throwing callback is contained.
   */
  readonly onProgress?: ((processed: number, total: number) => void) | undefined;
  /** Called with the outcome. */
  readonly onExported?: ((ok: boolean) => void) | undefined;
}

/** What {@link exportDiagnosticsReport} produced. */
export interface DiagnosticsExportResult {
  /** `true` when a download or clipboard write was initiated. */
  readonly ok: boolean;
  /** The format actually used. */
  readonly format: DiagnosticsFormat;
  /** Size of the produced payload in UTF-8 bytes. */
  readonly bytes: number;
}

/** Guards against overlapping exports (double shortcut presses, double clicks). */
let inFlight = false;

/** Whether an export is currently running. */
export function isExportInFlight(): boolean {
  return inFlight;
}

/** Yield to the event loop so a long export does not block rendering. */
function yieldToEventLoop(): Promise<void> {
  return new Promise<void>((resolve) => {
    setTimeout(resolve, 0);
  });
}

/** Map over an array in yielding slices. */
async function mapInSlices<T>(items: readonly T[], project: (item: T) => T): Promise<T[]> {
  const out: T[] = [];
  for (let index = 0; index < items.length; index += EXPORT_SLICE_SIZE) {
    const slice = items.slice(index, index + EXPORT_SLICE_SIZE);
    for (const item of slice) out.push(project(item));
    if (index + EXPORT_SLICE_SIZE < items.length) await yieldToEventLoop();
  }
  return out;
}

/** Serialise an array as JSON in yielding slices. */
async function stringifyInSlices(
  items: readonly unknown[],
  onSlice?: (processed: number) => void,
): Promise<string> {
  if (items.length === 0) return '[]';
  const parts: string[] = [];
  for (let index = 0; index < items.length; index += EXPORT_SLICE_SIZE) {
    const slice = items.slice(index, index + EXPORT_SLICE_SIZE);
    const encoded: string[] = [];
    for (const item of slice) {
      let json: string | undefined;
      try {
        json = JSON.stringify(item);
      } catch {
        json = undefined;
      }
      encoded.push(json ?? 'null');
    }
    parts.push(encoded.join(','));
    if (index + EXPORT_SLICE_SIZE < items.length) {
      onSlice?.(Math.min(index + EXPORT_SLICE_SIZE, items.length));
      await yieldToEventLoop();
    }
  }
  return `[${parts.join(',')}]`;
}

/** Serialise one record as a single JSON line, or `null` when it cannot be encoded. */
function toJsonLine(value: unknown): string {
  try {
    return JSON.stringify(value) ?? 'null';
  } catch {
    return 'null';
  }
}

/**
 * Re-read a JSON array built by `stringifyInSlices`.
 *
 * @param json - the array document
 * @returns the parsed array, or `[]` when it cannot be read
 *
 * @remarks
 * Round-tripping through `JSON.parse` is what produces a correctly **indented**
 * `'json'` document: the payload has to be a real value tree for
 * `JSON.stringify(payload, null, 2)` to work, and `JSON.stringify` does not indent a
 * string that already contains JSON. Parsing a document this module just built is
 * safe, and the failure branch covers a record that could not be encoded.
 */
function parseArray(json: string): unknown[] {
  try {
    const parsed: unknown = JSON.parse(json);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

/**
 * Render a value for a CSV cell.
 *
 * @param value - the value to render
 * @returns a string; objects are JSON-encoded so the cell stays useful
 */
function csvValue(value: unknown): string {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  try {
    return JSON.stringify(value) ?? '';
  } catch {
    return '[unserializable]';
  }
}

/**
 * Escape one CSV cell.
 *
 * @param value - the raw cell text
 * @returns a cell safe to place in a comma-separated row
 *
 * @remarks
 * Two things happen here, and the first is the one that matters:
 *
 * 1. **Formula injection is neutralised.** A cell beginning with `=`, `+`, `-`, `@`,
 *    tab or carriage return is executed as a formula by Excel, Sheets and LibreOffice
 *    on open. Since a cell can contain an error message, an error message can be
 *    `=HYPERLINK(...)`. Prefixing with an apostrophe makes the application treat the
 *    cell as text.
 * 2. **RFC 4180 quoting** for a value containing a comma, a quote, a newline or a
 *    carriage return, with embedded quotes doubled.
 */
function escapeCsv(value: string): string {
  const guarded = /^[=+\-@\t\r]/.test(value) ? `'${value}` : value;
  if (/[",\r\n]/.test(guarded)) return `"${guarded.replace(/"/g, '""')}"`;
  return guarded;
}

/** Render a column list and rows as a CSV document. */
function toCsv(columns: readonly string[], rows: readonly (readonly string[])[]): string {
  const lines = [columns.map(escapeCsv).join(',')];
  for (const row of rows) lines.push(row.map(escapeCsv).join(','));
  // A trailing CRLF is what RFC 4180 asks for and what Excel expects.
  return `${lines.join('\r\n')}\r\n`;
}

/**
 * Columns of the `'csv'` export, in order.
 *
 * @remarks
 * One table holds both kinds, distinguished by the leading `kind` column, rather
 * than emitting two files. A CSV export exists to be sorted and pivoted in a
 * spreadsheet, and two tables in one file cannot be. Errors and logs therefore
 * share these columns and leave the ones that do not apply empty.
 */
export const DIAGNOSTICS_CSV_COLUMNS: readonly string[] = [
  'kind',
  'id',
  'timestamp',
  'severity',
  'source',
  'category',
  'name',
  'message',
  'occurrenceCount',
  'fingerprint',
  'route',
  'method',
  'url',
  'status',
];

/** Read one allow-listed `api` field off an error record. */
function apiField(record: ErrorRecord, key: 'method' | 'url' | 'status'): string {
  const api = record.api;
  if (api === undefined || api === null) return '';
  const value = api[key];
  return value === undefined || value === null ? '' : csvValue(value);
}

/** Build one flat table row per error, aligned with `DIAGNOSTICS_CSV_COLUMNS`. */
function errorCsvRow(record: ErrorRecord): readonly string[] {
  return [
    'error',
    record.id,
    new Date(record.timestamp).toISOString(),
    record.severity,
    record.source,
    record.category,
    record.name,
    record.message,
    String(record.occurrenceCount),
    record.fingerprint,
    record.page?.route ?? '',
    apiField(record, 'method'),
    apiField(record, 'url'),
    apiField(record, 'status'),
  ];
}

/** Build one flat table row per log, aligned with `DIAGNOSTICS_CSV_COLUMNS`. */
function logCsvRow(record: LogRecord): readonly string[] {
  return [
    'log',
    record.id,
    new Date(record.timestamp).toISOString(),
    record.level,
    '',
    '',
    '',
    record.message,
    '',
    '',
    record.route ?? '',
    '',
    '',
    '',
  ];
}

/** Build the metadata block from current state. */
function buildMeta(errors: readonly ErrorRecord[], logs: readonly LogRecord[]): ReportMeta {
  const state = getState();
  const options = state.options;
  const sanitizer = getDefaultSanitizer();

  let url = 'unknown';
  try {
    const href = safeGet(safeGet(getWindow(), 'location'), 'href');
    if (typeof href === 'string') {
      const sanitized = sanitizer.url(href);
      if (sanitized !== undefined) url = sanitized;
    }
  } catch {
    // keep 'unknown'
  }

  let userAgent = '';
  try {
    const raw = safeGet(getNavigator(), 'userAgent');
    if (typeof raw === 'string') userAgent = sanitizer.text(raw, MAX_USER_AGENT_LENGTH);
  } catch {
    // keep empty
  }

  return {
    generatedAt: new Date(now()).toISOString(),
    appName: options?.appName ?? '',
    appVersion: options?.appVersion ?? '',
    buildId: options?.buildId ?? '',
    environment: options?.environment ?? '',
    url: sanitizer.text(url, MAX_URL_LENGTH),
    userAgent,
    online: isOnline(),
    errorCount: errors.length,
    logCount: logs.length,
  };
}

/** Resolve the filename prefix from options, then the shortcut config. */
function resolvePrefix(explicit: string | undefined): string {
  if (typeof explicit === 'string' && explicit.trim().length > 0) return explicit.trim();
  const shortcut = getState().options?.shortcut;
  if (shortcut !== undefined && shortcut !== false && shortcut.filenamePrefix.length > 0) {
    return shortcut.filenamePrefix;
  }
  return DEFAULT_FILENAME_PREFIX;
}

/** Build the download filename from a prefix and extension. */
export function diagnosticsFilename(prefix: string, extension: string): string {
  // Colons and dots are illegal in Windows filenames; the ISO stamp contains both.
  const stamp = new Date(now()).toISOString().replace(/[:.]/g, '-');
  // Interpolating a `Symbol` or an object with a hostile `Symbol.toPrimitive`
  // throws `TypeError`, and this is an exported function, so the coercion is
  // guarded and falls back to the documented default.
  let safePrefix = DEFAULT_FILENAME_PREFIX;
  let safeExtension = 'html';
  try {
    const rendered = `${prefix}`;
    if (rendered.length > 0) safePrefix = rendered;
  } catch (error) {
    reportInternalFailure('diagnostics-filename-prefix', error);
  }
  try {
    const rendered = `${extension}`;
    if (rendered.length > 0) safeExtension = rendered;
  } catch (error) {
    reportInternalFailure('diagnostics-filename-extension', error);
  }
  return `${safePrefix}-${stamp}.${safeExtension}`;
}

/** Trigger a browser download for the given text content. */
function downloadText(content: string, filename: string, mimeType: string): boolean {
  try {
    const doc = getDocument();
    const win = getWindow();
    if (doc === undefined || win === undefined) return false;

    const BlobCtor: unknown = safeGet(win, 'Blob') ?? safeGet(globalThis, 'Blob');
    if (typeof BlobCtor !== 'function') return false;

    const urlObject: unknown = safeGet(win, 'URL') ?? safeGet(globalThis, 'URL');
    const createObjectURL = safeGet(urlObject, 'createObjectURL');
    if (typeof createObjectURL !== 'function') return false;
    const revokeObjectURL = safeGet(urlObject, 'revokeObjectURL');

    const blob = Reflect.construct(BlobCtor as new (...args: unknown[]) => object, [
      [content],
      { type: mimeType },
    ]);
    const objectUrl: unknown = Reflect.apply(createObjectURL, urlObject, [blob]);
    if (typeof objectUrl !== 'string') return false;

    const anchor = doc.createElement('a');
    anchor.href = objectUrl;
    anchor.download = filename;
    anchor.rel = 'noopener';
    anchor.setAttribute('style', 'display:none');
    const host = doc.body ?? doc.documentElement;
    host.appendChild(anchor);
    anchor.click();

    // Revoking synchronously can cancel the download before the browser has read
    // the blob, so defer it well past the click.
    setTimeout(() => {
      try {
        host.removeChild(anchor);
      } catch {
        // Already detached.
      }
      try {
        if (typeof revokeObjectURL === 'function') {
          Reflect.apply(revokeObjectURL, urlObject, [objectUrl]);
        }
      } catch {
        // ignore
      }
    }, 1_000);

    return true;
  } catch (error) {
    reportInternalFailure('diagnostics-download', error);
    return false;
  }
}

/** Write text to the clipboard, feature-detected. */
async function copyText(content: string): Promise<boolean> {
  try {
    const navigatorObject = getNavigator();
    if (navigatorObject === undefined) return false;
    const clipboard = safeGet(navigatorObject, 'clipboard');
    const writeText = safeGet(clipboard, 'writeText');
    if (typeof writeText !== 'function') return false;
    await Reflect.apply(writeText, clipboard, [content]);
    return true;
  } catch (error) {
    reportInternalFailure('diagnostics-clipboard', error);
    return false;
  }
}

/** The export body, separated so the in-flight guard wraps it uniformly. */
async function runExport(options: DiagnosticsExportOptions): Promise<DiagnosticsExportResult> {
  const format: DiagnosticsFormat = resolveFormat(options.format);

  if (!isBrowser()) return { ok: false, format, bytes: 0 };

  const state = getState();
  const repository = state.repository;
  if (repository === null) return { ok: false, format, bytes: 0 };

  // Flush first so records written moments ago are included.
  try {
    await state.flush?.();
  } catch (error) {
    reportInternalFailure('diagnostics-flush', error);
  }

  const errorsResult = await repository.errors.getAll();
  const logsResult = await repository.logs.getAll();

  if (!errorsResult.ok) reportInternalFailure('diagnostics-read-errors', errorsResult.reason);
  if (!logsResult.ok) reportInternalFailure('diagnostics-read-logs', logsResult.reason);

  let errors: ErrorRecord[] = errorsResult.ok ? errorsResult.value : [];
  let logs: LogRecord[] = logsResult.ok ? logsResult.value : [];

  if (options.redactAgain === true) {
    errors = await mapInSlices(errors, sanitizeErrorRecord);
    logs = await mapInSlices(logs, sanitizeLogRecord);
  }

  const total = errors.length + logs.length;
  // Progress is reported against the whole payload, so the count never goes
  // backwards when the second kind starts.
  const progress = (processed: number): void => {
    if (typeof options.onProgress !== 'function') return;
    try {
      options.onProgress(Math.min(processed, total), total);
    } catch (error) {
      reportInternalFailure('diagnostics-progress', error);
    }
  };
  // Which slice boundaries have already been reported, so jsonl and the JSON
  // builders cannot double-count when several of them run for one export.
  let reportedUpTo = 0;
  const reportSlice = (upTo: number): void => {
    if (upTo > reportedUpTo) {
      reportedUpTo = upTo;
      progress(upTo);
    }
  };

  const meta = buildMeta(errors, logs);
  const appBlock = {
    appName: meta.appName,
    appVersion: meta.appVersion,
    buildId: meta.buildId,
    environment: meta.environment,
  };
  const pageBlock = { url: meta.url, userAgent: meta.userAgent, online: meta.online };
  const pretty = options.pretty === true;

  const buildJson = async (): Promise<string> => {
    const errorsJson = await stringifyInSlices(errors, (count) => {
      reportSlice(count);
    });
    const logsJson = await stringifyInSlices(logs, (count) => {
      reportSlice(errors.length + count);
    });
    const payload = {
      schemaVersion: 1 as const,
      generatedAt: meta.generatedAt,
      app: appBlock,
      page: pageBlock,
      errors: parseArray(errorsJson),
      logs: parseArray(logsJson),
    };
    try {
      return pretty ? JSON.stringify(payload, null, 2) : JSON.stringify(payload);
    } catch (error) {
      reportInternalFailure('diagnostics-json', error);
      return '{"schemaVersion":1,"errors":[],"logs":[]}';
    }
  };

  const buildJsonLines = async (): Promise<string> => {
    const lines: string[] = [];
    for (let index = 0; index < errors.length; index += EXPORT_SLICE_SIZE) {
      for (const record of errors.slice(index, index + EXPORT_SLICE_SIZE)) {
        lines.push(toJsonLine({ kind: 'error', ...record }));
      }
      if (index + EXPORT_SLICE_SIZE < errors.length) {
        reportSlice(Math.min(index + EXPORT_SLICE_SIZE, errors.length));
        await yieldToEventLoop();
      }
    }
    reportSlice(errors.length);
    for (let index = 0; index < logs.length; index += EXPORT_SLICE_SIZE) {
      for (const record of logs.slice(index, index + EXPORT_SLICE_SIZE)) {
        lines.push(toJsonLine({ kind: 'log', ...record }));
      }
      if (index + EXPORT_SLICE_SIZE < logs.length) {
        reportSlice(errors.length + Math.min(index + EXPORT_SLICE_SIZE, logs.length));
        await yieldToEventLoop();
      }
    }
    reportSlice(total);
    return lines.join('\n');
  };

  // Shared by `'json'` and `'html'`, which embed the same payload.
  const buildHtml = async (): Promise<string> => {
    const errorsJson = await stringifyInSlices(errors, (count) => {
      reportSlice(count);
    });
    const logsJson = await stringifyInSlices(logs, (count) => {
      reportSlice(errors.length + count);
    });
    const payloadJson = `{"schemaVersion":1,"generatedAt":${JSON.stringify(
      meta.generatedAt,
    )},"app":${JSON.stringify(appBlock)},"page":${JSON.stringify(pageBlock)},"errors":${errorsJson},"logs":${logsJson}}`;
    return renderDiagnosticsReport(meta, errors, logs, escapeJsonText(payloadJson));
  };

  let content: string;
  switch (format) {
    case 'json':
      content = await buildJson();
      break;
    case 'jsonl':
      content = await buildJsonLines();
      break;
    case 'csv':
      content = toCsv(DIAGNOSTICS_CSV_COLUMNS, [
        ...errors.map(errorCsvRow),
        ...logs.map(logCsvRow),
      ]);
      reportSlice(total);
      break;
    default:
      content = await buildHtml();
      break;
  }

  // An empty record set never trips a slice boundary, so the terminal report is
  // issued here too. `reportSlice` makes it a no-op when it is already exact.
  reportSlice(total);

  const bytes = byteLength(content);

  if (options.copyToClipboard === true) {
    const ok = await copyText(content);
    notifyExported(options.onExported, ok);
    return { ok, format, bytes };
  }

  const downloaded = downloadText(
    content,
    diagnosticsFilename(resolvePrefix(options.filenamePrefix), FORMAT_EXTENSIONS[format]),
    FORMAT_MIME_TYPES[format],
  );
  notifyExported(options.onExported, downloaded);
  return { ok: downloaded, format, bytes };
}

/** Accept only a known format, falling back to the report. */
function resolveFormat(requested: DiagnosticsFormat | undefined): DiagnosticsFormat {
  switch (requested) {
    case 'json':
    case 'jsonl':
    case 'csv':
    case 'html':
      return requested;
    default:
      return 'html';
  }
}

/** File extension per format. */
const FORMAT_EXTENSIONS: Readonly<Record<DiagnosticsFormat, string>> = {
  html: 'html',
  json: 'json',
  jsonl: 'jsonl',
  csv: 'csv',
};

/** MIME type per format. */
const FORMAT_MIME_TYPES: Readonly<Record<DiagnosticsFormat, string>> = {
  html: 'text/html;charset=utf-8',
  json: 'application/json;charset=utf-8',
  jsonl: 'application/x-ndjson;charset=utf-8',
  csv: 'text/csv;charset=utf-8',
};

/**
 * Invoke the caller's outcome callback, containing a throw.
 *
 * @param callback - the callback, if any
 * @param ok - the outcome
 *
 * @remarks
 * A throwing `onExported` must not abort the export and must not be invoked a
 * second time from the outer catch with a contradictory result.
 */
function notifyExported(callback: ((ok: boolean) => void) | undefined, ok: boolean): void {
  if (typeof callback !== 'function') return;
  try {
    callback(ok);
  } catch (error) {
    reportInternalFailure('diagnostics-on-exported', error);
  }
}

/**
 * Build and download a complete diagnostics report.
 *
 * @param options - see {@link DiagnosticsExportOptions}
 * @returns a {@link DiagnosticsExportResult}. `ok` is `true` when a download or
 * clipboard write was initiated. **Never throws.**
 *
 * @remarks
 * Concurrent calls are rejected with `ok: false`: a second shortcut press while the
 * first export is still marshalling records is a double-click, not a request for two
 * files.
 *
 * @example
 * ```ts
 * import { exportDiagnosticsReport } from '@codewithrajat/rm-logvault';
 *
 * // Default: self-contained HTML download
 * await exportDiagnosticsReport();
 *
 * // Machine-readable, re-redacted, straight to the clipboard
 * await exportDiagnosticsReport({ format: 'json', redactAgain: true, copyToClipboard: true });
 *
 * // One JSON object per line, for a log pipeline
 * const { bytes } = await exportDiagnosticsReport({ format: 'jsonl', pretty: false });
 * ```
 */
export async function exportDiagnosticsReport(
  options: DiagnosticsExportOptions = {},
): Promise<DiagnosticsExportResult> {
  try {
    // Reading `options.format` is inside the guard on purpose: an exported function
    // documented "never throws" must not be defeated by a hostile getter on the
    // object it was handed.
    const format = resolveFormat(options.format);
    if (inFlight) return { ok: false, format, bytes: 0 };
    inFlight = true;
    try {
      return await runExport(options);
    } catch (error) {
      reportInternalFailure('diagnostics-export', error);
      notifyExported(options.onExported, false);
      return { ok: false, format, bytes: 0 };
    } finally {
      inFlight = false;
    }
  } catch (error) {
    reportInternalFailure('diagnostics-export-options', error);
    return { ok: false, format: 'html', bytes: 0 };
  }
}
