/**
 * The context builders the library ships, ready to register.
 *
 * @remarks
 * These cover the three shapes a client-side error most often has before anyone
 * writes product-specific logic: an HTTP failure with a response, a request that
 * ran out of time, and a `TypeError` thrown by application code.
 *
 * **Nothing here registers itself.** Importing this module has no effect until
 * {@link installBuiltinContextBuilders} is called, so upgrading the library can
 * never silently change how an existing application classifies its errors.
 *
 * @example
 * ```ts
 * import { installBuiltinContextBuilders, registerErrorContextBuilder } from '@codewithrajat/rm-logvault';
 *
 * // Opt in to all three, in the documented order.
 * const off = installBuiltinContextBuilders();
 *
 * // …or pick one, and add your own domain knowledge ahead of it.
 * registerErrorContextBuilder(httpErrorContextBuilder);
 * registerErrorContextBuilder({
 *   name: 'alarms',
 *   canHandle: (error) => (error as { code?: string })?.code === 'ALARM_NOT_FOUND',
 *   build: () => ({ tags: { domain: 'alarms' } }),
 * });
 *
 * off(); // removes only the ones it installed
 * ```
 *
 * @packageDocumentation
 */

import { reportInternalFailure } from '../core/internal.js';
import { buildApiErrorContext } from './apiContext.js';
import type { ErrorContextBuilder } from './contextBuilders.js';
import { registerErrorContextBuilder } from './contextBuilders.js';
import type { ErrorContext } from './types.js';

/** Read a property from an unknown value without triggering a hostile getter. */
function safeGet(target: unknown, key: string): unknown {
  if (target === null || (typeof target !== 'object' && typeof target !== 'function')) {
    return undefined;
  }
  try {
    return (target as Record<string, unknown>)[key];
  } catch {
    return undefined;
  }
}

/**
 * Detect a `fetch`/`axios`-shaped rejection.
 *
 * @param error - the thrown value
 * @returns `true` when it carries a response-like object with a numeric status
 *
 * @remarks
 * Structural, not nominal: the library has no axios dependency (I-7) and must not
 * gain one, so this checks the *shape* both axios and a hand-rolled client produce.
 * Requiring a numeric `status` is what keeps it from firing on unrelated objects.
 */
function looksLikeHttpError(error: unknown): boolean {
  if (error === null || typeof error !== 'object') return false;
  const response = safeGet(error, 'response');
  if (response === null || typeof response !== 'object') return false;
  const status = safeGet(response, 'status');
  return typeof status === 'number' && Number.isFinite(status) && status > 0;
}

/**
 * Read a numeric `status` off an error that has no `response` object.
 *
 * @param error - the thrown value
 * @returns the status, or `undefined`
 */
function readDirectStatus(error: unknown): number | undefined {
  const status = safeGet(error, 'status');
  if (typeof status === 'number' && Number.isFinite(status) && status > 0) return status;
  const statusCode = safeGet(error, 'statusCode');
  if (typeof statusCode === 'number' && Number.isFinite(statusCode) && statusCode > 0) {
    return statusCode;
  }
  return undefined;
}

/**
 * Classify an HTTP failure that carries a response.
 *
 * @remarks
 * Delegates to {@link buildApiErrorContext}, which reads only an allow-list of
 * fields — method, url, status, statusText, code, timeout, duration and one
 * correlation header. Request and response **bodies are never read** (I-2).
 *
 * Its `canHandle` requires a response-like object with a numeric `status`, so a
 * plain `TypeError` or a bare `Error` is left for the builders registered after
 * it.
 */
export const httpErrorContextBuilder: ErrorContextBuilder = {
  name: 'http',
  canHandle: (error: unknown): boolean =>
    looksLikeHttpError(error) || readDirectStatus(error) !== undefined,
  build: (error: unknown): ErrorContext | null => {
    try {
      const classification = buildApiErrorContext(error);
      const context: ErrorContext = {
        category: classification.category,
        severity: classification.severity,
        api: classification.api,
      };
      const tags: Record<string, string> = {};
      // `ApiErrorContext.kind` is a required member of the closed `ApiErrorKind`
      // union, so it is always a usable tag value.
      tags.kind = classification.api.kind;
      if (classification.api.method !== undefined) tags.method = classification.api.method;
      if (classification.api.status !== undefined) tags.status = String(classification.api.status);
      return { ...context, tags };
    } catch (failure) {
      reportInternalFailure('context-builder-http', failure);
      return null;
    }
  },
};

/** Message shapes that indicate a request timed out. */
const TIMEOUT_PATTERN = /\b(?:timeout|timed out|ETIMEDOUT|ECONNABORTED)\b/i;

/**
 * Classify a request timeout.
 *
 * @remarks
 * Matched on the message because that is the only signal a timeout carries across
 * `fetch`, axios and `XMLHttpRequest`. Registered **before** the HTTP builder in
 * {@link installBuiltinContextBuilders}, because a timed-out axios request has both
 * a message and sometimes a response, and `timeout` is the more specific
 * classification.
 */
export const timeoutErrorContextBuilder: ErrorContextBuilder = {
  name: 'timeout',
  canHandle: (error: unknown): boolean => {
    // A thrown string is a real pattern that `normalizeError` supports, so a
    // `throw 'request timed out'` must classify as a timeout too.
    if (typeof error === 'string') return TIMEOUT_PATTERN.test(error);
    if (error === null || typeof error !== 'object') return false;
    const code = safeGet(error, 'code');
    if (code === 'ETIMEDOUT' || code === 'ECONNABORTED') return true;
    const message = safeGet(error, 'message');
    return typeof message === 'string' && TIMEOUT_PATTERN.test(message);
  },
  build: (): ErrorContext => ({
    category: 'timeout',
    severity: 'warning',
    tags: { kind: 'timeout' },
  }),
};

/**
 * Classify a `TypeError`.
 *
 * @remarks
 * A `TypeError` in a browser is almost always one of four things: reading a
 * property of `undefined`, calling something that is not a function, a failed
 * `fetch` (`Failed to fetch`), or a bad assignment to a read-only target. Tagging
 * them together separates "our rendering code has a null bug" from "the network
 * is down", which otherwise land in the same bucket.
 */
export const typeErrorContextBuilder: ErrorContextBuilder = {
  name: 'type-error',
  canHandle: (error: unknown): boolean => {
    if (error === null || typeof error !== 'object') return false;
    if (safeGet(error, 'name') === 'TypeError') return true;
    // Cross-realm TypeErrors do not satisfy `instanceof`, so the constructor name
    // is the reliable signal.
    const ctor = safeGet(error, 'constructor');
    return safeGet(ctor, 'name') === 'TypeError';
  },
  build: (): ErrorContext => ({
    category: 'runtime',
    severity: 'error',
    tags: { kind: 'type-error' },
  }),
};

/**
 * Register every shipped builder, in the order they should resolve.
 *
 * @returns one unregister function that removes exactly the three builders it
 * added; safe to call twice
 *
 * @remarks
 * Order matters and is deliberate:
 *
 * 1. `timeout` — most specific. A timed-out request can also look like an HTTP
 *    failure, and "timeout" is the more useful label.
 * 2. `http` — a response-bearing failure.
 * 3. `type-error` — the general case, last so it cannot shadow either.
 *
 * Register your own domain builders **before** calling this to give them
 * precedence; the registry resolves in registration order.
 *
 * @example
 * ```ts
 * import { installBuiltinContextBuilders } from '@codewithrajat/rm-logvault';
 *
 * const off = installBuiltinContextBuilders();
 * // …later
 * off();
 * ```
 */
export function installBuiltinContextBuilders(): () => void {
  try {
    const removers = [
      registerErrorContextBuilder(timeoutErrorContextBuilder),
      registerErrorContextBuilder(httpErrorContextBuilder),
      registerErrorContextBuilder(typeErrorContextBuilder),
    ];
    let removed = false;
    return (): void => {
      if (removed) return;
      removed = true;
      for (const remove of removers) {
        try {
          remove();
        } catch (failure) {
          reportInternalFailure('context-builder-uninstall', failure);
        }
      }
    };
  } catch (failure) {
    reportInternalFailure('context-builder-install', failure);
    return (): void => undefined;
  }
}
