/**
 * Global browser error handlers.
 *
 * @remarks
 * Installing a `window.onerror` handler is one of the most invasive things a
 * library can do, so this module follows a strict contract:
 *
 * - **Never overwrite.** A pre-existing `window.onerror` is chained: it is called
 *   and *its* return value is returned, so the application's decision about
 *   suppressing the default console message still stands.
 * - **Never detach someone else's work.** On cleanup we restore the previous
 *   handler *only* if `window.onerror` is still ours. If application code chained
 *   on top of us, we stay installed but **inert**: we keep forwarding to the
 *   original handler and capture nothing.
 * - **One registration.** Multiple installs (duplicate bundles, HMR, two
 *   frontends) merge into a single set of listeners with a single cleanup, so an
 *   error is never captured twice by the same mechanism.
 * - **Never the cause of an error.** Every callback is wrapped, and every
 *   `addEventListener` call is guarded.
 *
 * @packageDocumentation
 */

import { getEventTarget, getWindow, getWorkerScope, safeGet } from '../core/env.js';
import { CHUNK_ERROR_PATTERN, MAX_MESSAGE_LENGTH } from '../errors/constants.js';
import { sanitizeText } from '../errors/sanitize.js';
import type { ErrorContext, ErrorSeverity } from '../errors/types.js';

/** Resource tags whose failed load is an error rather than a warning. */
const CRITICAL_RESOURCE_TAGS: ReadonlySet<string> = new Set(['script', 'link', 'style']);

/** Options accepted by {@link installGlobalErrorHandlers}. */
export interface GlobalHandlerOptions {
  /** Call `preventDefault()` on `unhandledrejection`. Default `false`. */
  readonly preventDefaultUnhandledRejection?: boolean | undefined;
  /** Attach a capture-phase listener for failed resource loads. Default `false`. */
  readonly captureResources?: boolean | undefined;
  /** Listen for `securitypolicyviolation`. Default `false`. */
  readonly captureCsp?: boolean | undefined;
  /** Classify dynamic-import failures as `source: 'chunk'`. Default `true`. */
  readonly captureChunkErrors?: boolean | undefined;
  /**
   * Sink for every captured error.
   *
   * @remarks
   * Called synchronously from the DOM listener. Implementations must not throw;
   * they are wrapped regardless.
   */
  readonly onError: (error: unknown, ctx: ErrorContext) => void;
}

/** One merged registration. */
interface Registration {
  readonly options: GlobalHandlerOptions;
}

/** Active registrations. Several installs share one set of DOM listeners. */
const registrations = new Set<Registration>();

/** Whether dispatch is live. Set to `false` when we have been superseded. */
let active = false;

/** Whether the DOM listeners are currently attached. */
let attached = false;

/** The pre-existing `window.onerror` (or worker `onerror`) we chained. */
let chainedOnerror: unknown = null;

/** The target the listeners are attached to. */
let listenerTarget: EventTarget | undefined;

/** Whether resource-error capture is currently wanted by anyone. */
function wantsResources(): boolean {
  for (const registration of registrations) {
    if (registration.options.captureResources === true) return true;
  }
  return false;
}

/** Whether CSP capture is currently wanted by anyone. */
function wantsCsp(): boolean {
  for (const registration of registrations) {
    if (registration.options.captureCsp === true) return true;
  }
  return false;
}

/** Whether any registration asked to suppress the default rejection handling. */
function wantsPreventDefault(): boolean {
  for (const registration of registrations) {
    if (registration.options.preventDefaultUnhandledRejection === true) return true;
  }
  return false;
}

/** Whether chunk classification is enabled for at least one registration. */
function wantsChunkCapture(): boolean {
  for (const registration of registrations) {
    if (registration.options.captureChunkErrors !== false) return true;
  }
  return false;
}

/** Dispatch a captured error to every registration, swallowing all failures. */
function dispatch(error: unknown, ctx: ErrorContext): void {
  dispatchWhere(() => true, error, ctx);
}

/**
 * Dispatch to the registrations matching `predicate`.
 *
 * @remarks
 * A listener can outlive the registration that asked for it (the `error` listener
 * stays attached while any registration still wants resource capture). Filtering at
 * dispatch time is what stops a registration that opted *out* from receiving those
 * events.
 */
function dispatchWhere(
  predicate: (options: GlobalHandlerOptions) => boolean,
  error: unknown,
  ctx: ErrorContext,
): void {
  if (!active) return;
  // Snapshot so a handler that unsubscribes mid-dispatch is safe.
  for (const registration of [...registrations]) {
    if (!predicate(registration.options)) continue;
    try {
      registration.options.onError(error, ctx);
    } catch {
      // A consumer callback must never break the DOM listener.
    }
  }
}

/** Whether a message describes a chunk / dynamic-import failure. */
function isChunkMessage(message: string): boolean {
  return CHUNK_ERROR_PATTERN.test(message);
}

/**
 * Classify the `(message, source, line, col, error)` form reported by `onerror`
 * or an `ErrorEvent`.
 *
 * @param origin - which listener reported it. A rejection reason arrives through
 * the same `(message, …, error)` shape as `onerror`, so the origin has to be
 * passed explicitly or every rejection would be mislabelled `source: 'window'`.
 */
function captureWindowError(
  message: unknown,
  source: unknown,
  line: unknown,
  column: unknown,
  error: unknown,
  origin: 'window' | 'unhandledrejection' = 'window',
): void {
  try {
    const text = typeof message === 'string' ? message : 'Script error.';
    const sourceFile = typeof source === 'string' && source.length > 0 ? source : undefined;
    const lineNumber = typeof line === 'number' ? line : undefined;
    const columnNumber = typeof column === 'number' ? column : undefined;

    const location =
      sourceFile === undefined
        ? undefined
        : {
            source: sanitizeText(sourceFile, MAX_MESSAGE_LENGTH),
            ...(lineNumber !== undefined ? { line: lineNumber } : {}),
            ...(columnNumber !== undefined ? { column: columnNumber } : {}),
          };

    /** The reported source, with chunk detection taking precedence. */
    const classify = (): ErrorContext['source'] => {
      if (wantsChunkCapture() && isChunkMessage(text)) return 'chunk';
      return origin;
    };

    if (error !== null && error !== undefined) {
      const chunk = wantsChunkCapture() && isChunkMessage(text);
      dispatch(error, {
        source: classify(),
        ...(chunk ? { severity: 'fatal' as ErrorSeverity, category: 'chunk' as const } : {}),
        ...(location !== undefined ? { location } : {}),
      });
      return;
    }

    // A cross-origin script without CORS exposes only "Script error." and a null
    // error. Report the location and mark it, because the message alone is useless.
    const crossOrigin = text.trim() === 'Script error.';
    const chunk = wantsChunkCapture() && isChunkMessage(text);
    // A synthetic error-like object keeps the reported message without inventing a
    // stack that would point at this file.
    const synthetic = { name: chunk ? 'ChunkLoadError' : 'WindowError', message: text };

    dispatch(synthetic, {
      source: classify(),
      ...(chunk ? { severity: 'fatal' as ErrorSeverity, category: 'chunk' as const } : {}),
      ...(location !== undefined ? { location } : {}),
      ...(crossOrigin && origin === 'window' ? { tags: { crossOrigin: 'true' } } : {}),
      event: {
        type: 'error',
        crossOrigin: crossOrigin && origin === 'window' ? 'true' : undefined,
      },
    });
  } catch {
    // ignore
  }
}

/**
 * The stable `window.onerror` replacement.
 *
 * @remarks
 * A single function identity is reused for the lifetime of the module so the
 * "is it still ours?" check during cleanup is exact.
 */
function globalOnerror(
  this: unknown,
  message?: unknown,
  source?: unknown,
  lineno?: unknown,
  colno?: unknown,
  error?: unknown,
): unknown {
  try {
    // An `onerror()` invocation carrying neither an error object nor a message
    // string tells us nothing. Some engines (and DOM shims) fire `window.onerror`
    // with no arguments when a resource fails to load; reporting that as
    // "Script error." would fabricate a cross-origin error out of thin air.
    const hasError = error !== null && error !== undefined;
    const hasMessage = typeof message === 'string' && message.length > 0;
    if (active && (hasError || hasMessage)) {
      captureWindowError(message, source, lineno, colno, error);
    }
  } catch {
    // ignore
  }
  // Chain: call the handler that was installed before us and return ITS value, so
  // the application keeps whatever suppression behaviour it asked for.
  if (typeof chainedOnerror === 'function') {
    try {
      return Reflect.apply(
        chainedOnerror as (...params: unknown[]) => unknown,
        this ?? globalThis,
        [message, source, lineno, colno, error],
      );
    } catch {
      return undefined;
    }
  }
  return undefined;
}

/** `unhandledrejection` listener. */
function onUnhandledRejection(event: Event): void {
  try {
    if (!active) return;
    if (wantsPreventDefault()) {
      const prevent = safeGet(event, 'preventDefault');
      if (typeof prevent === 'function') {
        try {
          Reflect.apply(prevent, event, []);
        } catch {
          // ignore
        }
      }
    }
    const reason = safeGet(event, 'reason');
    captureWindowError(reason, undefined, undefined, undefined, reason, 'unhandledrejection');
  } catch {
    // ignore
  }
}

/** Capture-phase `error` listener for failed resource loads. */
function onResourceError(event: Event): void {
  try {
    if (!active) return;

    const target = safeGet(event, 'target');
    if (target === null || target === undefined) return;
    // Runtime errors are ErrorEvents and are handled by `window.onerror`; handling
    // them here too would capture every uncaught error twice.
    if (safeGet(target, 'message') !== undefined) return;

    const tagName = safeGet(target, 'tagName');
    if (typeof tagName !== 'string' || tagName.length === 0) return;

    const tag = tagName.toLowerCase();
    const src = safeGet(target, 'src') ?? safeGet(target, 'href') ?? safeGet(target, 'currentSrc');
    const resourceUrl = typeof src === 'string' ? src : undefined;

    const severity: ErrorSeverity = CRITICAL_RESOURCE_TAGS.has(tag) ? 'error' : 'warning';
    const chunk =
      wantsChunkCapture() &&
      tag === 'script' &&
      resourceUrl !== undefined &&
      isChunkMessage(resourceUrl);

    dispatchWhere(
      (options) => options.captureResources === true,
      {
        name: 'ResourceLoadError',
        message: `Failed to load <${tag}>: ${resourceUrl ?? 'unknown'}`,
      },
      {
        source: chunk ? 'chunk' : 'resource',
        category: 'resource',
        severity,
        event: {
          type: 'error',
          targetTag: tag,
          ...(resourceUrl !== undefined ? { resourceUrl } : {}),
        },
      },
    );
  } catch {
    // ignore
  }
}

/** `vite:preloadError` listener (Vite's dynamic-import failure signal). */
function onPreloadError(event: Event): void {
  try {
    if (!active) return;
    const payload = safeGet(event, 'payload');
    const error = payload ?? { name: 'ChunkLoadError', message: 'Failed to preload module' };
    dispatch(error, {
      source: 'chunk',
      severity: 'fatal',
      category: 'chunk',
      tags: { bundler: 'vite' },
    });
  } catch {
    // ignore
  }
}

/** `securitypolicyviolation` listener. */
function onSecurityPolicyViolation(event: Event): void {
  try {
    if (!active) return;

    const effective = safeGet(event, 'effectiveDirective');
    const violated = safeGet(event, 'violatedDirective');
    const directive =
      typeof effective === 'string' && effective.length > 0
        ? effective
        : typeof violated === 'string' && violated.length > 0
          ? violated
          : undefined;

    const blockedURI = safeGet(event, 'blockedURI');
    const blocked =
      typeof blockedURI === 'string' && blockedURI.length > 0 ? blockedURI : undefined;

    const sourceFile = safeGet(event, 'sourceFile');
    const lineNumber = safeGet(event, 'lineNumber');
    const columnNumber = safeGet(event, 'columnNumber');

    // A blocked URI containing "/" is a URL worth reporting; a bare token such as
    // `eval` or `inline` is worth reporting as a tag instead.
    const isUrl = blocked?.includes('/') === true;
    const location =
      typeof sourceFile === 'string' && sourceFile.length > 0
        ? {
            source: sanitizeText(sourceFile, MAX_MESSAGE_LENGTH),
            ...(typeof lineNumber === 'number' ? { line: lineNumber } : {}),
            ...(typeof columnNumber === 'number' ? { column: columnNumber } : {}),
          }
        : undefined;

    dispatchWhere(
      (options) => options.captureCsp === true,
      {
        name: 'SecurityPolicyViolation',
        message: `Content-Security-Policy violation: ${directive ?? 'unknown directive'}`,
      },
      {
        source: 'csp',
        category: 'security',
        severity: 'warning',
        ...(location !== undefined ? { location } : {}),
        ...(isUrl || blocked !== undefined
          ? { tags: isUrl ? {} : { blocked: sanitizeText(blocked, 200) } }
          : {}),
        event: {
          type: 'securitypolicyviolation',
          ...(directive !== undefined ? { directive } : {}),
          ...(isUrl && blocked !== undefined
            ? { resourceUrl: sanitizeText(blocked, MAX_MESSAGE_LENGTH) }
            : {}),
          ...(isUrl && blocked !== undefined
            ? { blockedURI: sanitizeText(blocked, MAX_MESSAGE_LENGTH) }
            : {}),
        },
      },
    );
  } catch {
    // ignore
  }
}

/** Attach every listener the current registrations require. Idempotent. */
function attach(): void {
  if (attached) return;
  const target = getEventTarget();
  if (target === undefined) {
    // SSR or an unrecognised host: stay a no-op rather than throwing.
    return;
  }
  listenerTarget = target;

  try {
    // Chain `onerror` rather than replacing it.
    const win = getWindow();
    const scope = win ?? getWorkerScope();
    if (scope !== undefined) {
      const existing = safeGet(scope, 'onerror');
      chainedOnerror = existing ?? null;
      Reflect.set(scope, 'onerror', globalOnerror);
    }

    target.addEventListener('unhandledrejection', onUnhandledRejection);
    target.addEventListener('vite:preloadError', onPreloadError);

    if (wantsResources()) {
      // Resource load failures do not bubble, so capture phase is mandatory.
      target.addEventListener('error', onResourceError, true);
    }
    if (wantsCsp()) {
      target.addEventListener('securitypolicyviolation', onSecurityPolicyViolation);
    }

    attached = true;
    active = true;
  } catch {
    // A hostile or read-only event target must not break initialization.
  }
}

/** Remove every listener and restore `onerror` when it is still ours. */
function detach(): void {
  if (!attached) {
    active = false;
    return;
  }

  const target = listenerTarget;
  try {
    target?.removeEventListener('unhandledrejection', onUnhandledRejection);
    target?.removeEventListener('vite:preloadError', onPreloadError);
    target?.removeEventListener('error', onResourceError, true);
    target?.removeEventListener('securitypolicyviolation', onSecurityPolicyViolation);
  } catch {
    // ignore
  }

  try {
    const win = getWindow();
    const scope = win ?? getWorkerScope();
    if (scope !== undefined) {
      if (safeGet(scope, 'onerror') === globalOnerror) {
        // Still ours: restore exactly what was there before.
        Reflect.set(scope, 'onerror', chainedOnerror);
        active = false;
      } else {
        // Someone chained on top of us. Stay installed but inert, so their chain
        // keeps working and we stop capturing.
        active = false;
      }
    } else {
      active = false;
    }
  } catch {
    active = false;
  }

  listenerTarget = undefined;
  attached = false;
}

/**
 * Install the global error handlers.
 *
 * @param options - see {@link GlobalHandlerOptions}
 * @returns a cleanup function. Idempotent, and safe to call when the handlers
 * were never attached (SSR, workers without `self`).
 *
 * @remarks
 * Multiple calls **merge**: registering twice, or from two copies of the library,
 * produces one set of DOM listeners that fans out to both callbacks, and one
 * cleanup that removes each independently.
 *
 * @example
 * ```ts
 * import { installGlobalErrorHandlers, captureError } from '@codewithrajat/rm-logvault';
 *
 * const cleanup = installGlobalErrorHandlers({
 *   onError: (error, ctx) => captureError(error, ctx),
 *   captureCsp: true,
 * });
 *
 * cleanup(); // removes exactly this registration
 * ```
 */
export function installGlobalErrorHandlers(options: GlobalHandlerOptions): () => void {
  const registration: Registration = { options };

  try {
    registrations.add(registration);
    if (!attached) attach();
    else if (wantsResources() || wantsCsp()) {
      // Flags can only widen; re-attaching keeps one listener set regardless.
      detach();
      attach();
    }
  } catch {
    // ignore
  }

  return (): void => {
    try {
      registrations.delete(registration);
      if (registrations.size === 0) detach();
    } catch {
      // ignore
    }
  };
}

/** Number of merged registrations. Used by tests and diagnostics. */
export function globalHandlerCount(): number {
  return registrations.size;
}

/** Whether listeners are currently attached. Used by tests and diagnostics. */
export function globalHandlersAttached(): boolean {
  return attached;
}
