/**
 * Opt-in capture of the host application's `console.warn` / `console.error` calls.
 *
 * @remarks
 * Wrapping `console` is invasive, so it is off by default and every copy is
 * defensive:
 *
 * - The **original method runs first**, with the original `this`, so application
 *   behaviour and DevTools formatting are unchanged.
 * - A recursion guard means a message emitted while we are already ingesting one
 *   is dropped instead of looping.
 * - Restore only happens if the property is still *our* wrapper; if application
 *   code replaced it afterwards, we leave theirs alone.
 *
 * @packageDocumentation
 */

import { safeGet } from '../core/env.js';
import type { LogLevel } from './logger.constants.js';

/** Options for {@link installConsoleCapture}. */
export interface ConsoleCaptureOptions {
  /** Levels to wrap. Defaults to `['warn', 'error']`. */
  readonly levels?: readonly LogLevel[] | undefined;
  /** Called after the original method has run. Must not throw. */
  readonly onCall: (level: LogLevel, args: readonly unknown[]) => void;
}

/** Resolve `globalThis.console` defensively. */
function resolveConsole(): Record<string, unknown> | undefined {
  try {
    const candidate: unknown = Reflect.get(globalThis, 'console');
    if (candidate === null || typeof candidate !== 'object') return undefined;
    return candidate as Record<string, unknown>;
  } catch {
    return undefined;
  }
}

/** Levels wrapped by default. */
const DEFAULT_LEVELS: readonly LogLevel[] = ['warn', 'error'];

/**
 * Wrap the configured console methods.
 *
 * @param options - see {@link ConsoleCaptureOptions}
 * @returns a restore function. Calling it twice is safe; calling it when the
 * application has since replaced the method leaves that replacement in place.
 *
 * @example
 * ```ts
 * import { installConsoleCapture, logger } from '@codewithrajat/rm-logvault';
 *
 * const restore = installConsoleCapture({
 *   levels: ['warn', 'error'],
 *   onCall: (level, args) => logger[level]('[console]', ...args),
 * });
 *
 * restore(); // puts the originals back
 * ```
 */
export function installConsoleCapture(options: ConsoleCaptureOptions): () => void {
  const levels = options.levels ?? DEFAULT_LEVELS;
  const restores: (() => void)[] = [];
  /** True while we are inside our own ingestion path. */
  let ingesting = false;
  let restored = false;

  for (const level of levels) {
    const consoleObject = resolveConsole();
    if (consoleObject === undefined) break;

    const original = safeGet(consoleObject, level);
    const fallback = safeGet(consoleObject, 'log');
    const target = typeof original === 'function' ? original : fallback;
    if (typeof target !== 'function') continue;

    const wrapper = function wrapper(this: unknown, ...args: unknown[]): void {
      // 1. Always run the original first, with the caller's `this`.
      try {
        Reflect.apply(target as (...params: unknown[]) => unknown, this ?? consoleObject, args);
      } catch {
        // ignore
      }

      // 2. Ingest, guarded against recursion.
      if (ingesting) return;
      ingesting = true;
      try {
        options.onCall(level, args);
      } catch {
        // ignore
      } finally {
        ingesting = false;
      }
    };

    try {
      // Preserve a stable identity for DevTools and for exact-restore checks.
      Object.defineProperty(wrapper, 'name', { value: level, configurable: true });
    } catch {
      // Cosmetic only.
    }

    let installed = false;
    try {
      Reflect.set(consoleObject, level, wrapper);
      installed = safeGet(consoleObject, level) === wrapper;
    } catch {
      installed = false;
    }
    if (!installed) continue;

    restores.push(() => {
      try {
        // Only undo our own wrapper; never clobber a later replacement.
        if (safeGet(consoleObject, level) !== wrapper) return;
        if (typeof original === 'function') Reflect.set(consoleObject, level, original);
        else Reflect.deleteProperty(consoleObject, level);
      } catch {
        // ignore
      }
    });
  }

  return (): void => {
    if (restored) return;
    restored = true;
    for (const restore of restores) restore();
  };
}
