/**
 * Second-pass redaction of persisted records.
 *
 * @remarks
 * Records are already sanitized before they reach storage. This pass exists
 * because the redaction rules are **configuration**, and configuration can change
 * between the moment a record was written and the moment a report is exported — a
 * new `extraSensitiveKeys` entry, a tightened query allow-list, or simply a
 * support engineer exporting with `redactAgain: true` to be certain.
 *
 * Running the sanitiser over a record a second time is idempotent: redacting an
 * already-redacted value yields the same placeholder.
 *
 * @packageDocumentation
 */

import {
  MAX_MESSAGE_LENGTH,
  MAX_STACK_LENGTH,
  MAX_TAG_KEY_LENGTH,
  MAX_TAG_VALUE_LENGTH,
} from '../errors/constants.js';
import { getDefaultSanitizer } from '../errors/sanitize.js';
import type { ErrorCause, ErrorRecord } from '../errors/types.js';
import type { LogRecord } from '../logger/logger.types.js';

/** An error record with its `readonly` modifiers stripped. */
type Mutable<T> = { -readonly [K in keyof T]: T[K] };

/** Redact every free-text field of an error record. */
function redactCauses(
  causes: readonly ErrorCause[] | undefined,
): readonly ErrorCause[] | undefined {
  if (causes === undefined) return undefined;
  const sanitizer = getDefaultSanitizer();
  return causes.map((cause) => {
    const mapped: { name: string; message: string; stack?: string } = {
      name: sanitizer.text(cause.name, MAX_MESSAGE_LENGTH),
      message: sanitizer.text(cause.message, MAX_MESSAGE_LENGTH),
    };
    if (cause.stack !== undefined) mapped.stack = sanitizer.stack(cause.stack, MAX_STACK_LENGTH);
    return mapped;
  });
}

/**
 * Re-run the sanitizer over an error record.
 *
 * @param record - the stored record
 * @returns a redacted copy. Never throws.
 *
 * @example
 * ```ts
 * import { sanitizeErrorRecord } from '@codewithrajat/rm-logvault';
 *
 * const safe = sanitizeErrorRecord(record);
 * ```
 */
export function sanitizeErrorRecord(record: ErrorRecord): ErrorRecord {
  try {
    const sanitizer = getDefaultSanitizer();
    const out: Mutable<ErrorRecord> = { ...record };

    out.name = sanitizer.text(record.name, MAX_MESSAGE_LENGTH);
    out.message = sanitizer.text(record.message, MAX_MESSAGE_LENGTH);
    if (record.stack !== undefined) out.stack = sanitizer.stack(record.stack, MAX_STACK_LENGTH);
    if (record.componentStack !== undefined) {
      out.componentStack = sanitizer.stack(record.componentStack, MAX_STACK_LENGTH);
    }
    if (record.causes !== undefined) out.causes = redactCauses(record.causes);

    // Values reached storage through `sanitizeValue`, but re-running is cheap and
    // catches anything a custom `beforeCapture` hook may have injected.
    const extra = sanitizer.value(record.extra);
    out.extra =
      extra !== null && typeof extra === 'object' && !Array.isArray(extra)
        ? (extra as Record<string, unknown>)
        : undefined;

    if (record.tags !== undefined) {
      const tags: Record<string, string> = Object.create(null) as Record<string, string>;
      for (const [key, value] of Object.entries(record.tags)) {
        tags[sanitizer.text(key, MAX_TAG_KEY_LENGTH)] = sanitizer.text(value, MAX_TAG_VALUE_LENGTH);
      }
      out.tags = Object.keys(tags).length > 0 ? tags : undefined;
    }

    if (record.page !== undefined) {
      const url = sanitizer.url(record.page.url);
      out.page = {
        ...record.page,
        url: url ?? 'unknown',
        route: sanitizer.text(record.page.route, 300),
      };
    }

    if (record.api !== undefined) {
      const api: Mutable<NonNullable<ErrorRecord['api']>> = { ...record.api };
      if (record.api.url !== undefined) {
        const url = sanitizer.url(record.api.url);
        api.url = url;
      }
      if (record.api.statusText !== undefined) {
        api.statusText = sanitizer.text(record.api.statusText, 200);
      }
      if (record.api.requestId !== undefined) {
        api.requestId = sanitizer.text(record.api.requestId, 200);
      }
      out.api = api;
    }

    if (record.event !== undefined) {
      const event: Mutable<NonNullable<ErrorRecord['event']>> = { ...record.event };
      if (record.event.resourceUrl !== undefined) {
        event.resourceUrl = sanitizer.url(record.event.resourceUrl);
      }
      if (record.event.blockedURI !== undefined) {
        event.blockedURI = sanitizer.text(record.event.blockedURI, MAX_MESSAGE_LENGTH);
      }
      out.event = event;
    }

    if (record.environment !== undefined) {
      const environment: Mutable<NonNullable<ErrorRecord['environment']>> = {
        ...record.environment,
      };
      if (record.environment.appName !== undefined) {
        environment.appName = sanitizer.text(record.environment.appName, 200);
      }
      if (record.environment.userAgent !== undefined) {
        environment.userAgent = sanitizer.text(record.environment.userAgent, 500);
      }
      out.environment = environment;
    }

    return out;
  } catch {
    return record;
  }
}

/**
 * Re-run the sanitizer over a log record.
 *
 * @param record - the stored record
 * @returns a redacted copy. Never throws.
 *
 * @example
 * ```ts
 * import { sanitizeLogRecord } from '@codewithrajat/rm-logvault';
 *
 * const safe = sanitizeLogRecord(record);
 * ```
 */
export function sanitizeLogRecord(record: LogRecord): LogRecord {
  try {
    const sanitizer = getDefaultSanitizer();
    const out: Mutable<LogRecord> = { ...record };

    out.message = sanitizer.text(record.message, MAX_MESSAGE_LENGTH);
    if (record.data !== undefined) {
      out.data = record.data.map((entry) => sanitizer.value(entry));
    }
    if (record.route !== undefined) {
      out.route = sanitizer.text(record.route, 300);
    }
    if (record.environment !== undefined) {
      const environment: Mutable<NonNullable<LogRecord['environment']>> = { ...record.environment };
      if (record.environment.appName !== undefined) {
        environment.appName = sanitizer.text(record.environment.appName, 200);
      }
      out.environment = environment;
    }

    return out;
  } catch {
    return record;
  }
}
