/**
 * IndexedDB persistence for error records.
 *
 * @remarks
 * Two behaviours distinguish this repository from a plain key/value store:
 *
 * - **Pending-only aggregation.** `save` looks up the
 *   `[fingerprint, 'pending']` index entry first and merges into it, so a bug that
 *   fires a thousand times occupies one row. Aggregation never touches a row that
 *   is already `uploading`, because that row is owned by an in-flight request.
 * - **Atomic claiming.** `claimPending` moves rows from `pending` to `uploading`
 *   inside a single `readwrite` transaction, which is what makes multiple tabs
 *   safe: two tabs cannot claim the same row.
 *
 * @packageDocumentation
 */

import type { Maybe, Timestamp, UploadStatus } from '../core/types.js';
import type { ErrorRecord } from '../errors/types.js';
import type { DbConnection, IdbCoreOptions } from './idbCore.js';
import { createDbConnection, promisifyRequest } from './idbCore.js';
import {
  cleanupStore,
  deleteByIds,
  halvedPolicy,
  sortNewestFirst,
  updateStatuses,
} from './repositoryUtils.js';
import {
  DEFAULT_PENDING_LIMIT,
  ERROR_CLEANUP_EVERY_WRITES,
  ERRORS_DB_VERSION,
  ERRORS_INDEX_FINGERPRINT_STATUS,
  ERRORS_INDEX_STATUS,
  ERRORS_STORE,
} from './storage.constants.js';
import type {
  CleanupPolicy,
  ErrorRepository,
  StorageFailureReason,
  StorageResult,
} from './storage.types.js';
import { isErrorRecord } from './validate.js';

/** Options for {@link createErrorRepository}. */
export interface ErrorRepositoryOptions {
  /** Physical database name, e.g. `rm-logvault-errors`. */
  readonly dbName: string;
  /** Explicit `IDBFactory`. Defaults to `globalThis.indexedDB`. */
  readonly indexedDB?: Maybe<IDBFactory>;
  /** Called once per distinct failure class. */
  readonly onFailure?: Maybe<(reason: StorageFailureReason, error: unknown) => void>;
  /** Retention policy. When omitted, automatic cleanup is disabled. */
  readonly cleanupPolicy?: Maybe<CleanupPolicy>;
  /** How often to run automatic retention. Default {@link ERROR_CLEANUP_EVERY_WRITES}. */
  readonly cleanupEveryWrites?: Maybe<number>;
  /** Open timeout passed through to the connection. */
  readonly openTimeoutMs?: Maybe<number>;
}

/** Create the object store and indexes. Idempotent: safe to re-run. */
function upgradeErrors(db: IDBDatabase, _oldVersion: number, transaction: IDBTransaction): void {
  if (!db.objectStoreNames.contains(ERRORS_STORE)) {
    const store = db.createObjectStore(ERRORS_STORE, { keyPath: 'id' });
    store.createIndex(ERRORS_INDEX_FINGERPRINT_STATUS, ['fingerprint', 'uploadStatus'], {
      unique: false,
    });
    store.createIndex(ERRORS_INDEX_STATUS, 'uploadStatus', { unique: false });
    return;
  }

  // Store exists (re-upgrade after a manual database deletion): add any missing index.
  const store = transaction.objectStore(ERRORS_STORE);
  if (!store.indexNames.contains(ERRORS_INDEX_FINGERPRINT_STATUS)) {
    store.createIndex(ERRORS_INDEX_FINGERPRINT_STATUS, ['fingerprint', 'uploadStatus'], {
      unique: false,
    });
  }
  if (!store.indexNames.contains(ERRORS_INDEX_STATUS)) {
    store.createIndex(ERRORS_INDEX_STATUS, 'uploadStatus', { unique: false });
  }
}

/** Structural type of the global `IDBKeyRange` constructor. */
type KeyRangeFactory = { only(value: IDBValidKey): IDBKeyRange };

/** Build an `IDBKeyRange.only` key range when the constructor is available. */
function onlyKeyRange(key: IDBValidKey): IDBKeyRange | undefined {
  try {
    const ctor: unknown = Reflect.get(globalThis, 'IDBKeyRange');
    if (typeof ctor === 'function') {
      return (ctor as unknown as KeyRangeFactory).only(key);
    }
  } catch {
    // Fall through: callers degrade to a full cursor scan.
  }
  return undefined;
}

/**
 * Create an error repository backed by IndexedDB.
 *
 * @param options - see {@link ErrorRepositoryOptions}
 * @returns an {@link ErrorRepository}. Construction never opens the database.
 *
 * @example
 * ```ts
 * import { createErrorRepository } from '@codewithrajat/rm-logvault';
 *
 * const repository = createErrorRepository({ dbName: 'rm-logvault-errors' });
 * await repository.initialize();
 * await repository.save(record);
 * const pending = await repository.claimPending(50, Date.now());
 * ```
 */
export function createErrorRepository(options: ErrorRepositoryOptions): ErrorRepository {
  const connectionOptions: IdbCoreOptions = {
    dbName: options.dbName,
    version: ERRORS_DB_VERSION,
    storeName: ERRORS_STORE,
    upgrade: upgradeErrors,
    ...(options.indexedDB !== undefined ? { indexedDB: options.indexedDB } : {}),
    ...(options.onFailure !== undefined ? { onFailure: options.onFailure } : {}),
    ...(options.openTimeoutMs !== undefined ? { openTimeoutMs: options.openTimeoutMs } : {}),
  };
  const connection: DbConnection = createDbConnection(connectionOptions);

  const cleanupEvery = Math.max(1, options.cleanupEveryWrites ?? ERROR_CLEANUP_EVERY_WRITES);
  let writesSinceCleanup = 0;
  /** Set once cleanup has failed, so we stop retrying it on every write. */
  let cleanupDisabled = false;

  const policy = (): CleanupPolicy | undefined => options.cleanupPolicy;

  /** Run retention inside its own transaction. */
  const runCleanup = async (override?: CleanupPolicy): Promise<StorageResult<number>> => {
    const active = override ?? policy();
    if (active === undefined) return { ok: true, value: 0 };
    const now = Date.now();
    return connection.transaction('readwrite', (store) =>
      cleanupStore<ErrorRecord>(store, active, (record) => record.lastSeen, now, isErrorRecord),
    );
  };

  const save = async (record: ErrorRecord): Promise<StorageResult<void>> => {
    const attempt = async (): Promise<StorageResult<void>> =>
      connection.transaction('readwrite', async (store) => {
        const index = store.index(ERRORS_INDEX_FINGERPRINT_STATUS);
        const range = onlyKeyRange([record.fingerprint, 'pending']);
        const existing = await findAggregateTarget(store, index, record.fingerprint, range);

        if (existing === undefined) {
          await promisifyRequest(store.put(record));
          return;
        }

        const merged: ErrorRecord = {
          ...existing,
          occurrenceCount: existing.occurrenceCount + record.occurrenceCount,
          firstSeen: Math.min(existing.firstSeen, record.firstSeen),
          lastSeen: Math.max(existing.lastSeen, record.lastSeen),
        };
        await promisifyRequest(store.put(merged));
      });

    let result = await attempt();

    if (!result.ok && result.reason === 'quota') {
      // Free half the cap and try the same write exactly once.
      const active = policy();
      if (active !== undefined) {
        await runCleanup(halvedPolicy(active));
        result = await attempt();
      }
    }

    if (result.ok) {
      writesSinceCleanup += 1;
      if (!cleanupDisabled && writesSinceCleanup >= cleanupEvery) {
        writesSinceCleanup = 0;
        const cleaned = await runCleanup();
        if (!cleaned.ok) cleanupDisabled = true;
      }
    }

    return result;
  };

  /**
   * Read every row, newest first, deleting anything malformed.
   *
   * @remarks
   * Two transactions, deliberately: a `readonly` pass collects the valid rows and
   * the primary keys of the malformed ones, then a `readwrite` pass (only when
   * something was malformed) deletes them. Deleting inside the read transaction
   * would throw `ReadOnlyError` and fail the whole read.
   */
  const readAllValidated = async (): Promise<StorageResult<ErrorRecord[]>> => {
    const first = await connection.transaction('readonly', async (store) => {
      const raw = await promisifyRequest<unknown[]>(store.getAll());
      const valid: ErrorRecord[] = [];
      const malformed: string[] = [];
      for (const entry of raw) {
        if (isErrorRecord(entry)) valid.push(entry);
        else if (entry !== null && typeof entry === 'object') {
          const id = (entry as { id?: unknown }).id;
          if (typeof id === 'string') malformed.push(id);
        }
      }
      return { valid, malformed };
    });

    if (!first.ok) return first;

    if (first.value.malformed.length > 0) {
      // A row that cannot be parsed is deleted rather than returned again.
      await connection.transaction('readwrite', (store) =>
        deleteByIds(store, first.value.malformed),
      );
    }

    return {
      ok: true,
      value: sortNewestFirst(first.value.valid, (record) => record.lastSeen),
    };
  };

  const readByStatus = async (
    status: UploadStatus,
    limit: number,
  ): Promise<StorageResult<ErrorRecord[]>> =>
    connection.transaction('readonly', async (store) => {
      const range = onlyKeyRange(status);
      const index = store.index(ERRORS_INDEX_STATUS);
      const collected: ErrorRecord[] = [];

      await new Promise<void>((resolve, reject) => {
        const request = range === undefined ? index.openCursor() : index.openCursor(range);
        request.onerror = (): void => {
          reject(request.error ?? new Error('cursor failed'));
        };
        request.onsuccess = (): void => {
          const cursor = request.result;
          if (cursor === null) {
            resolve();
            return;
          }
          const value = cursor.value as unknown;
          if (isErrorRecord(value) && value.uploadStatus === status) collected.push(value);
          cursor.continue();
        };
      });

      const sorted = sortNewestFirst(collected, (record) => record.lastSeen);
      return limit > 0 ? sorted.slice(0, limit) : sorted;
    });

  const claimPending = async (
    limit: number,
    now: Timestamp,
  ): Promise<StorageResult<ErrorRecord[]>> =>
    connection.transaction('readwrite', async (store) => {
      const index = store.index(ERRORS_INDEX_STATUS);
      const range = onlyKeyRange('pending');
      const claimed: ErrorRecord[] = [];

      await new Promise<void>((resolve, reject) => {
        const request = range === undefined ? index.openCursor() : index.openCursor(range);
        request.onerror = (): void => {
          reject(request.error ?? new Error('cursor failed'));
        };
        request.onsuccess = (): void => {
          const cursor = request.result;
          if (cursor === null || claimed.length >= limit) {
            resolve();
            return;
          }
          const value = cursor.value as unknown;
          if (isErrorRecord(value) && value.uploadStatus === 'pending') {
            const updated: ErrorRecord = {
              ...value,
              uploadStatus: 'uploading',
              uploadAttempts: value.uploadAttempts + 1,
              claimedAt: now,
            };
            cursor.update(updated);
            claimed.push(updated);
          }
          cursor.continue();
        };
      });

      return claimed;
    });

  const requeueStale = async (
    olderThanMs: number,
    now: Timestamp,
  ): Promise<StorageResult<number>> =>
    connection.transaction('readwrite', async (store) => {
      const index = store.index(ERRORS_INDEX_STATUS);
      const range = onlyKeyRange('uploading');
      let requeued = 0;

      await new Promise<void>((resolve, reject) => {
        const request = range === undefined ? index.openCursor() : index.openCursor(range);
        request.onerror = (): void => {
          reject(request.error ?? new Error('cursor failed'));
        };
        request.onsuccess = (): void => {
          const cursor = request.result;
          if (cursor === null) {
            resolve();
            return;
          }
          const value = cursor.value as unknown;
          if (isErrorRecord(value) && value.uploadStatus === 'uploading') {
            const claimedAt = value.claimedAt;
            const stale = claimedAt === undefined || now - claimedAt > olderThanMs;
            if (stale) {
              const updated: ErrorRecord = { ...value, uploadStatus: 'pending' };
              delete (updated as { claimedAt?: Maybe<Timestamp> }).claimedAt;
              cursor.update(updated);
              requeued += 1;
            }
          }
          cursor.continue();
        };
      });

      return requeued;
    });

  return {
    initialize: async (): Promise<StorageResult<void>> => {
      const opened = await connection.ensureOpen();
      if (!opened.ok) return { ok: false, reason: opened.reason };
      const cleaned = await runCleanup();
      if (!cleaned.ok) {
        // Retention failure must not make storage look unusable.
        options.onFailure?.(cleaned.reason, new Error('initial cleanup failed'));
      }
      return { ok: true, value: undefined };
    },

    save,

    get: async (id: string): Promise<StorageResult<Maybe<ErrorRecord>>> =>
      connection.transaction('readonly', async (store) => {
        const raw = await promisifyRequest<unknown>(store.get(id));
        return isErrorRecord(raw) ? raw : undefined;
      }),

    getAll: readAllValidated,

    getPending: (limit = DEFAULT_PENDING_LIMIT) => readByStatus('pending', limit),

    claimPending,

    requeueStale,

    getFailed: () => readByStatus('failed', 0),

    delete: async (ids: readonly string[]): Promise<StorageResult<number>> =>
      connection.transaction('readwrite', (store) => deleteByIds(store, ids)),

    updateUploadStatus: async (
      ids: readonly string[],
      status: UploadStatus,
    ): Promise<StorageResult<number>> =>
      connection.transaction('readwrite', (store) =>
        updateStatuses(store, ids, status, Date.now()),
      ),

    count: async (): Promise<StorageResult<number>> =>
      connection.transaction('readonly', (store) => promisifyRequest<number>(store.count())),

    pendingCount: async (): Promise<StorageResult<number>> =>
      connection.transaction('readonly', async (store) => {
        // A bounded cursor scan: `maxRecords` defaults to 500, and this is only
        // consulted on init, after a flush and on demand.
        let total = 0;
        await new Promise<void>((resolve, reject) => {
          const request = store.openCursor();
          request.onerror = (): void => {
            reject(request.error ?? new Error('cursor failed'));
          };
          request.onsuccess = (): void => {
            const cursor = request.result;
            if (cursor === null) {
              resolve();
              return;
            }
            const value = cursor.value as unknown;
            if (
              isErrorRecord(value) &&
              (value.uploadStatus === 'pending' || value.uploadStatus === 'uploading')
            ) {
              total += 1;
            }
            cursor.continue();
          };
        });
        return total;
      }),

    cleanup: (activePolicy: CleanupPolicy): Promise<StorageResult<number>> =>
      runCleanup(activePolicy),

    clear: async (): Promise<StorageResult<number>> =>
      connection.transaction('readwrite', async (store) => {
        const before = await promisifyRequest<number>(store.count());
        await promisifyRequest(store.clear());
        return before;
      }),

    close: (): void => {
      connection.close();
    },
  };
}

/**
 * Find the `pending` row this fingerprint should merge into.
 *
 * @param store - the object store (used for the key-range fallback scan)
 * @param index - the `by_fingerprint_status` index
 * @param fingerprint - the fingerprint to match
 * @param range - a prepared `IDBKeyRange.only([fingerprint, 'pending'])`, when supported
 * @returns the existing record and its primary key, or `undefined`
 */
async function findAggregateTarget(
  store: IDBObjectStore,
  index: IDBIndex,
  fingerprint: string,
  range: IDBKeyRange | undefined,
): Promise<ErrorRecord | undefined> {
  if (range !== undefined) {
    const found = await promisifyRequest<unknown>(index.get(range));
    return isErrorRecord(found) && found.uploadStatus === 'pending' ? found : undefined;
  }

  // No IDBKeyRange: fall back to a bounded cursor scan.
  return new Promise<ErrorRecord | undefined>((resolve, reject) => {
    const request = store.openCursor();
    request.onerror = (): void => {
      reject(request.error ?? new Error('cursor failed'));
    };
    request.onsuccess = (): void => {
      const cursor = request.result;
      if (cursor === null) {
        resolve(undefined);
        return;
      }
      const value = cursor.value as unknown;
      if (
        isErrorRecord(value) &&
        value.uploadStatus === 'pending' &&
        value.fingerprint === fingerprint
      ) {
        resolve(value);
        return;
      }
      cursor.continue();
    };
  });
}
