/**
 * UTF-8 payload budgeting and progressive reduction.
 *
 * @remarks
 * A single pathological error — a 5 MB message, a 40 000-frame stack, an `extra`
 * object containing a whole application store — must not be allowed to fill the
 * origin's storage quota or blow past a server's request limit. Each record is
 * therefore measured in UTF-8 bytes and, if oversized, reduced through a fixed
 * ladder of tiers until it fits. If even the minimal tier does not fit, the record
 * is **dropped** and reported, because storing a truncated-to-useless record is
 * worse than storing nothing.
 *
 * @packageDocumentation
 */

import type { LogRecord } from '../logger/logger.types.js';
import { MAX_CAUSE_DEPTH } from './constants.js';
import type { ErrorCause, ErrorRecord } from './types.js';

/** Marker tag added by the first reduction tier. */
export const TRUNCATED_TAG = 'truncated';

/** Causes trimmed to this many characters by the first reduction tier. */
export const TIER1_CAUSE_LENGTH = 300;
/** Stack trimmed to this many characters by the first reduction tier. */
export const TIER1_STACK_LENGTH = 2_000;
/** Component stack trimmed to this many characters by the first reduction tier. */
export const TIER1_COMPONENT_STACK_LENGTH = 1_000;
/** Stack trimmed to this many characters by the minimal tier. */
export const TIER2_STACK_LENGTH = 500;
/** Message trimmed to this many characters by the minimal tier. */
export const TIER2_MESSAGE_LENGTH = 300;
/** Log messages are shortened to this length before a log record is dropped. */
export const LOG_REDUCED_MESSAGE_LENGTH = 300;

/**
 * UTF-8 byte length of a value's JSON representation.
 *
 * @param value - any JSON-serialisable value
 * @returns the byte length, or `Infinity` when the value cannot be serialised
 *
 * @example
 * ```ts
 * import { byteLength } from '@codewithrajat/rm-logvault';
 *
 * byteLength({ a: 'é' }); // 10 — 'é' is two bytes in UTF-8, the rest is ASCII
 * ```
 */
export function byteLength(value: unknown): number {
  try {
    const json = JSON.stringify(value);
    if (json === undefined) return 0;
    if (typeof TextEncoder !== 'undefined') {
      return new TextEncoder().encode(json).length;
    }
    // Fallback: percent-encoding expands every multi-byte character.
    return encodeURIComponent(json).replace(/%[0-9A-F]{2}/gi, 'x').length;
  } catch {
    return Number.POSITIVE_INFINITY;
  }
}

/** Truncate a string to `max` characters, without a suffix. */
function cut(value: string, max: number): string {
  return value.length <= max ? value : value.slice(0, max);
}

/** Trim a cause chain to a character budget per link. */
function trimCauses(causes: readonly ErrorCause[], max: number): ErrorCause[] {
  return causes.slice(0, MAX_CAUSE_DEPTH).map((cause) => {
    const trimmed: { name: string; message: string; stack?: string } = {
      name: cause.name,
      message: cut(cause.message, max),
    };
    if (cause.stack !== undefined) trimmed.stack = cut(cause.stack, max);
    return trimmed;
  });
}

/** Add or update the `truncated` tag. */
function withTruncatedTag(record: ErrorRecord): ErrorRecord {
  const tags: Record<string, string> = { ...(record.tags ?? {}) };
  tags[TRUNCATED_TAG] = 'true';
  return { ...record, tags };
}

/** An error record with its `readonly` modifiers stripped, for in-place reduction. */
type MutableErrorRecord = { -readonly [K in keyof ErrorRecord]: ErrorRecord[K] };

/** An error record with the specified members removed. */
function without<K extends keyof ErrorRecord>(
  record: ErrorRecord,
  keys: readonly K[],
): ErrorRecord {
  const copy: Record<string, unknown> = { ...record };
  for (const key of keys) delete copy[key as string];
  return copy as unknown as ErrorRecord;
}

/**
 * Reduce an error record until it fits its byte budget.
 *
 * @param record - the candidate record
 * @param maxBytes - the UTF-8 budget
 * @returns a record that fits, or `null` when even the minimal tier is too large
 *
 * @remarks
 * The tiers are, in order:
 *
 * 1. Drop `extra` and tag the record `truncated: 'true'`.
 * 2. Trim `causes` to {@link TIER1_CAUSE_LENGTH} characters, `stack` to
 *    {@link TIER1_STACK_LENGTH} and `componentStack` to
 *    {@link TIER1_COMPONENT_STACK_LENGTH}.
 * 3. Minimal: `stack` to {@link TIER2_STACK_LENGTH} and `message` to
 *    {@link TIER2_MESSAGE_LENGTH}, with `causes` and `componentStack` removed.
 * 4. Give up and drop the record.
 *
 * @example
 * ```ts
 * import { reduceErrorPayload } from '@codewithrajat/rm-logvault';
 *
 * const fitted = reduceErrorPayload(record, 16_384);
 * if (fitted === null) reportInternalFailure('payload-limit', new Error('dropped'));
 * ```
 */
export function reduceErrorPayload(record: ErrorRecord, maxBytes: number): ErrorRecord | null {
  try {
    if (byteLength(record) <= maxBytes) return record;

    // Tier 1: drop `extra`, flag the record as truncated.
    let current = withTruncatedTag(without(record, ['extra']));
    if (byteLength(current) <= maxBytes) return current;

    // Tier 2: trim causes, stack and component stack.
    const tier2: MutableErrorRecord = { ...current };
    if (current.causes !== undefined) {
      tier2.causes = trimCauses(current.causes, TIER1_CAUSE_LENGTH);
    }
    if (current.stack !== undefined) {
      tier2.stack = cut(current.stack, TIER1_STACK_LENGTH);
    }
    if (current.componentStack !== undefined) {
      tier2.componentStack = cut(current.componentStack, TIER1_COMPONENT_STACK_LENGTH);
    }
    current = tier2;
    if (byteLength(current) <= maxBytes) return current;

    // Tier 3: minimal — keep enough to identify the failure, nothing more.
    const minimal: MutableErrorRecord = { ...current };
    if (current.stack !== undefined) {
      minimal.stack = cut(current.stack, TIER2_STACK_LENGTH);
    }
    minimal.message = cut(current.message, TIER2_MESSAGE_LENGTH);
    minimal.causes = undefined;
    minimal.componentStack = undefined;
    current = minimal;
    if (byteLength(current) <= maxBytes) return current;

    return null;
  } catch {
    // If measurement itself fails we cannot guarantee the budget, so drop.
    return null;
  }
}

/**
 * Reduce a log record until it fits its byte budget.
 *
 * @param record - the candidate record
 * @param maxBytes - the UTF-8 budget
 * @returns a record that fits, or `null` when even the bare record is too large
 *
 * @remarks
 * The tiers are: drop `data`, then shorten `message` to
 * {@link LOG_REDUCED_MESSAGE_LENGTH}, then drop the record.
 *
 * @example
 * ```ts
 * import { reduceLogPayload } from '@codewithrajat/rm-logvault';
 *
 * reduceLogPayload(record, 4_096) ?? reportDropped();
 * ```
 */
export function reduceLogPayload(record: LogRecord, maxBytes: number): LogRecord | null {
  try {
    if (byteLength(record) <= maxBytes) return record;

    // Tier 1: drop attached data.
    const tier1: { -readonly [K in keyof LogRecord]: LogRecord[K] } = { ...record };
    tier1.data = undefined;
    let current: LogRecord = tier1;
    if (byteLength(current) <= maxBytes) return current;

    // Tier 2: shorten the message.
    const tier2: { -readonly [K in keyof LogRecord]: LogRecord[K] } = { ...current };
    tier2.message = cut(current.message, LOG_REDUCED_MESSAGE_LENGTH);
    current = tier2;
    if (byteLength(current) <= maxBytes) return current;

    // Tier 3: give up rather than store something meaningless.
    return null;
  } catch {
    return null;
  }
}
