/**
 * Normalisation of arbitrarily-thrown values into a single shape.
 *
 * @remarks
 * `throw` accepts anything: `undefined`, a `Symbol`, a Proxy whose every getter
 * throws, an object with a circular `cause` graph, or an `AggregateError` with a
 * thousand members. `normalizeError` turns all of them into a {@link NormalizedError}
 * and **never throws** — the final fallback is a hard-coded literal.
 *
 * @packageDocumentation
 */

import { safeGet } from '../core/env.js';
import {
  CHUNK_ERROR_PATTERN,
  MAX_AGGREGATE_ERRORS,
  MAX_CAUSE_DEPTH,
  MAX_MESSAGE_LENGTH,
  MAX_STACK_LENGTH,
  REDACTED,
} from './constants.js';
import { getDefaultSanitizer, sanitizeStack, sanitizeValue } from './sanitize.js';
import type { ErrorCause, NormalizedError, ThrownType } from './types.js';

/** Maximum characters of a summarised non-Error value. */
const MAX_SUMMARY_LENGTH = 200;

/** Name given to a plain object that was thrown. */
export const NON_ERROR_OBJECT_NAME = 'NonErrorObject';

/** Message prefix used when something that is not an Error was thrown. */
export const NON_ERROR_MESSAGE_PREFIX = 'Non-Error value thrown';

/** The literal returned when even the fallback path fails. */
export const UNNORMALIZABLE: NormalizedError = {
  name: 'Error',
  message: 'Unnormalizable error value',
  thrownType: 'other',
  isChunkError: false,
  isCrossOrigin: false,
  category: 'runtime',
};

/** Truncate text to `max` characters. */
function cut(text: string, max: number): string {
  return text.length <= max ? text : text.slice(0, max);
}

/**
 * Error-like duck typing.
 *
 * @remarks
 * `instanceof Error` fails across realms (iframes, workers, `vm` contexts), so a
 * structural check is the reliable test: a string `message` plus either a `name`
 * or a `stack`.
 */
function isErrorLike(value: object): boolean {
  const message = safeGet(value, 'message');
  if (typeof message !== 'string') return false;
  const name = safeGet(value, 'name');
  const stack = safeGet(value, 'stack');
  return typeof name === 'string' || typeof stack === 'string';
}

/** Render a short, sanitised summary of any value. */
function summarize(value: unknown): string {
  try {
    if (typeof value === 'string') return cut(value, MAX_SUMMARY_LENGTH);
    const sanitized = sanitizeValue(value);
    const json = JSON.stringify(sanitized);
    return cut(json ?? String(sanitized), MAX_SUMMARY_LENGTH);
  } catch {
    return REDACTED;
  }
}

/** Read a string property, or `undefined` when absent/unreadable. */
function readString(target: unknown, key: string): string | undefined {
  const value = safeGet(target, key);
  return typeof value === 'string' ? value : undefined;
}

/**
 * Read the `AggregateError` constructor.
 *
 * @remarks
 * Accessed through `globalThis` rather than referenced directly so the library
 * keeps its ES2020 lib baseline (`AggregateError` is an ES2021 addition) while
 * still using it whenever the runtime provides it.
 */
function aggregateErrorCtor(): (new (...args: unknown[]) => object) | undefined {
  try {
    const ctor: unknown = Reflect.get(globalThis, 'AggregateError');
    return typeof ctor === 'function' ? (ctor as new (...args: unknown[]) => object) : undefined;
  } catch {
    return undefined;
  }
}

/** Whether the thrown value looks like an `AggregateError`. */
function isAggregate(value: object): boolean {
  const ctor = aggregateErrorCtor();
  if (ctor !== undefined) {
    try {
      if (value instanceof ctor) return true;
    } catch {
      // Fall through to the structural check.
    }
  }
  if (readString(value, 'name') !== 'AggregateError') return false;
  return Array.isArray(safeGet(value, 'errors'));
}

/** Whether the thrown value is a DOM `Event`/`ErrorEvent`. */
function isDomEvent(value: object): boolean {
  const type = safeGet(value, 'type');
  return (
    typeof type === 'string' &&
    typeof safeGet(value, 'preventDefault') === 'function' &&
    safeGet(value, 'target') !== undefined
  );
}

/** Extract a normalised message+name+stack from a real Error-like object. */
function fromErrorLike(value: object): { name: string; message: string; stack?: string } {
  const rawName = readString(value, 'name');
  let name = rawName !== undefined && rawName.length > 0 ? rawName : '';

  if (name.length === 0) {
    // Fall back to the constructor name, then to a literal. Named `ctor` rather
    // than `constructor` so it does not shadow the prototype property.
    const ctor = safeGet(value, 'constructor');
    const constructorName = readString(ctor, 'name');
    name = constructorName !== undefined && constructorName.length > 0 ? constructorName : 'Error';
  }

  const rawMessage = readString(value, 'message') ?? '';
  const stack = readString(value, 'stack');

  const result: { name: string; message: string; stack?: string } = {
    name: cut(name, MAX_MESSAGE_LENGTH),
    message: cut(rawMessage, MAX_MESSAGE_LENGTH),
  };
  if (stack !== undefined) result.stack = stack;
  return result;
}

/**
 * Walk a `cause` chain into a bounded array.
 *
 * @param root - the top-level thrown value
 * @returns up to {@link MAX_CAUSE_DEPTH} links, cycle-safe
 */
function readCauses(root: unknown): ErrorCause[] | undefined {
  const causes: ErrorCause[] = [];
  const seen = new Set<unknown>();
  // Seed with the root, so a `cause` chain that loops back to the original error
  // terminates before emitting a duplicate link for it.
  if (root !== null && typeof root === 'object') seen.add(root);
  let current = safeGet(root, 'cause');

  while (current !== undefined && current !== null && causes.length < MAX_CAUSE_DEPTH) {
    if (typeof current === 'object') {
      if (seen.has(current)) break;
      seen.add(current);
    } else if (seen.has(current)) {
      break;
    } else {
      seen.add(current);
    }

    causes.push(causeFrom(current));
    current = safeGet(current, 'cause');
  }

  return causes.length > 0 ? causes : undefined;
}

/** Render one link of a cause chain. */
function causeFrom(value: unknown): ErrorCause {
  if (value !== null && typeof value === 'object' && isErrorLike(value)) {
    const { name, message, stack } = fromErrorLike(value);
    const cause: ErrorCause = { name, message };
    if (stack !== undefined) {
      return { ...cause, stack: sanitizeStack(stack, MAX_STACK_LENGTH) };
    }
    return cause;
  }
  return {
    name: 'NonErrorCause',
    message: cut(`${NON_ERROR_MESSAGE_PREFIX}: ${summarize(value)}`, MAX_MESSAGE_LENGTH),
  };
}

/** Build the extra bag for a non-Error thrown value. */
function nonErrorExtra(value: unknown, thrownType: ThrownType): Record<string, unknown> {
  return { thrownValue: sanitizeValue(value), thrownType };
}

/** Assemble the final object, dropping undefined members. */
function build(partial: {
  name: string;
  message: string;
  thrownType: ThrownType;
  stack?: string | undefined;
  causes?: readonly ErrorCause[] | undefined;
  aggregatedCount?: number | undefined;
  extra?: Record<string, unknown> | undefined;
}): NormalizedError {
  const isChunk =
    partial.name === 'ChunkLoadError' ||
    CHUNK_ERROR_PATTERN.test(partial.message) ||
    CHUNK_ERROR_PATTERN.test(partial.name);
  const isCrossOrigin = partial.message.trim() === 'Script error.';

  const out: {
    name: string;
    message: string;
    thrownType: ThrownType;
    isChunkError: boolean;
    isCrossOrigin: boolean;
    stack?: string;
    causes?: readonly ErrorCause[];
    category?: NormalizedError['category'];
    aggregatedCount?: number;
    extra?: Record<string, unknown>;
  } = {
    name: partial.name,
    message: partial.message,
    thrownType: partial.thrownType,
    isChunkError: isChunk,
    isCrossOrigin: isCrossOrigin,
  };

  if (partial.stack !== undefined) out.stack = partial.stack;
  if (partial.causes !== undefined) out.causes = partial.causes;
  if (partial.aggregatedCount !== undefined) out.aggregatedCount = partial.aggregatedCount;
  if (partial.extra !== undefined) out.extra = partial.extra;
  if (isChunk) out.category = 'chunk';

  return out;
}

/**
 * Normalise any thrown value into a {@link NormalizedError}.
 *
 * @param input - the value that was thrown or reported
 * @returns a fully-populated, sanitised, bounded normalised error. Never throws.
 *
 * @remarks
 * Handling order:
 *
 * 1. DOM `Event`/`ErrorEvent` — unwraps `.error` when present, otherwise reports
 *    `"<type> event"`.
 * 2. `AggregateError` — keeps the first {@link MAX_AGGREGATE_ERRORS} sub-errors
 *    and records `aggregatedCount`.
 * 3. Error-like objects (`message` plus `name`/`stack`), including cross-realm and
 *    exotic `Error` subclasses.
 * 4. Non-Error values — primitives, `null`, `undefined`, functions, plain objects
 *    (`NonErrorObject`), and hostile objects whose getters throw.
 * 5. Hard-coded {@link UNNORMALIZABLE} fallback.
 *
 * @example
 * ```ts
 * import { normalizeError } from '@codewithrajat/rm-logvault';
 *
 * normalizeError('boom').thrownType;            // 'string'
 * normalizeError(null).name;                    // 'ThrownNull'
 * normalizeError({ a: 1 }).name;                // 'NonErrorObject'
 * normalizeError(new TypeError('bad')).name;    // 'TypeError'
 * ```
 */
export function normalizeError(input: unknown): NormalizedError {
  try {
    // ---- null / undefined -------------------------------------------------
    if (input === null) {
      return build({
        name: 'ThrownNull',
        message: `${NON_ERROR_MESSAGE_PREFIX}: null`,
        thrownType: 'null',
        extra: nonErrorExtra(input, 'null'),
      });
    }
    if (input === undefined) {
      return build({
        name: 'ThrownUndefined',
        message: `${NON_ERROR_MESSAGE_PREFIX}: undefined`,
        thrownType: 'undefined',
        extra: nonErrorExtra(input, 'undefined'),
      });
    }

    const type = typeof input;

    // ---- primitives and functions ----------------------------------------
    if (type === 'string') {
      const text = input as string;
      return build({
        name: 'ThrownString',
        message: cut(text, MAX_MESSAGE_LENGTH),
        thrownType: 'string',
        extra: nonErrorExtra(input, 'string'),
      });
    }
    if (type === 'number') {
      return build({
        name: 'ThrownNumber',
        message: `${NON_ERROR_MESSAGE_PREFIX}: ${String(input)}`,
        thrownType: 'number',
        extra: nonErrorExtra(input, 'number'),
      });
    }
    if (type === 'boolean') {
      return build({
        name: 'ThrownBoolean',
        message: `${NON_ERROR_MESSAGE_PREFIX}: ${String(input)}`,
        thrownType: 'boolean',
        extra: nonErrorExtra(input, 'boolean'),
      });
    }
    if (type === 'bigint') {
      let rendered: string;
      try {
        rendered = `${String(input)}n`;
      } catch {
        rendered = REDACTED;
      }
      return build({
        name: 'ThrownBigInt',
        message: `${NON_ERROR_MESSAGE_PREFIX}: ${rendered}`,
        thrownType: 'other',
        extra: nonErrorExtra(input, 'other'),
      });
    }
    if (type === 'symbol' || type === 'function') {
      let rendered: string;
      try {
        rendered = type === 'function' ? '[Function]' : String(input);
      } catch {
        rendered = REDACTED;
      }
      return build({
        name: type === 'function' ? 'ThrownFunction' : 'ThrownSymbol',
        message: `${NON_ERROR_MESSAGE_PREFIX}: ${cut(rendered, MAX_SUMMARY_LENGTH)}`,
        thrownType: 'other',
        extra: nonErrorExtra(input, 'other'),
      });
    }

    // ---- objects ---------------------------------------------------------
    const object = input as object;

    if (isDomEvent(object)) {
      const inner = safeGet(object, 'error');
      if (inner !== undefined && inner !== null) {
        return normalizeError(inner);
      }
      const eventType = readString(object, 'type') ?? 'unknown';
      return build({
        name: 'ErrorEvent',
        message: `${eventType} event`,
        thrownType: 'object',
        extra: { eventType },
      });
    }

    if (isAggregate(object)) {
      const raw = safeGet(object, 'errors');
      const list = Array.isArray(raw) ? raw : [];
      const subErrors: ErrorCause[] = [];
      const limit = Math.min(list.length, MAX_AGGREGATE_ERRORS);
      for (let index = 0; index < limit; index += 1) {
        subErrors.push(causeFrom(list[index]));
      }
      const own = fromErrorLike(object);
      const extra: Record<string, unknown> = {
        aggregatedCount: list.length,
        aggregatedErrors: subErrors.map((entry) => ({
          name: entry.name,
          message: entry.message,
        })),
      };
      return build({
        name: own.name === 'Error' ? 'AggregateError' : own.name,
        message: own.message,
        thrownType: 'error',
        stack: own.stack !== undefined ? sanitizeStack(own.stack, MAX_STACK_LENGTH) : undefined,
        causes: subErrors.length > 0 ? subErrors : undefined,
        aggregatedCount: list.length,
        extra,
      });
    }

    if (isErrorLike(object)) {
      const { name, message, stack } = fromErrorLike(object);
      const causes = readCauses(object);
      return build({
        name,
        message,
        thrownType: 'error',
        stack: stack !== undefined ? sanitizeStack(stack, MAX_STACK_LENGTH) : undefined,
        causes,
      });
    }

    // Plain or hostile object: never trust its getters or `toString`.
    return build({
      name: NON_ERROR_OBJECT_NAME,
      message: `${NON_ERROR_MESSAGE_PREFIX}: ${summarize(object)}`,
      thrownType: 'object',
      extra: nonErrorExtra(object, 'object'),
    });
  } catch {
    return UNNORMALIZABLE;
  }
}

/**
 * Redact an already-normalised error a second time, immediately before it is
 * written to storage or embedded in an exported report.
 *
 * @param normalized - the value produced by {@link normalizeError}
 * @returns a redacted copy. Never throws.
 */
export function sanitizeNormalized(normalized: NormalizedError): NormalizedError {
  const sanitizer = getDefaultSanitizer();
  try {
    const out: {
      name: string;
      message: string;
      thrownType: ThrownType;
      isChunkError: boolean;
      isCrossOrigin: boolean;
      stack?: string;
      causes?: readonly ErrorCause[];
      category?: NormalizedError['category'];
      aggregatedCount?: number;
      extra?: Record<string, unknown>;
    } = {
      name: sanitizer.text(normalized.name, MAX_MESSAGE_LENGTH),
      message: sanitizer.text(normalized.message, MAX_MESSAGE_LENGTH),
      thrownType: normalized.thrownType,
      isChunkError: normalized.isChunkError,
      isCrossOrigin: normalized.isCrossOrigin,
    };
    if (normalized.stack !== undefined) {
      out.stack = sanitizer.stack(normalized.stack, MAX_STACK_LENGTH);
    }
    if (normalized.causes !== undefined) {
      out.causes = normalized.causes.map((cause) => {
        const mapped: ErrorCause = {
          name: sanitizer.text(cause.name, MAX_MESSAGE_LENGTH),
          message: sanitizer.text(cause.message, MAX_MESSAGE_LENGTH),
        };
        return cause.stack !== undefined
          ? { ...mapped, stack: sanitizer.stack(cause.stack, MAX_STACK_LENGTH) }
          : mapped;
      });
    }
    if (normalized.category !== undefined) out.category = normalized.category;
    if (normalized.aggregatedCount !== undefined) {
      out.aggregatedCount = normalized.aggregatedCount;
    }
    if (normalized.extra !== undefined) {
      const sanitized = sanitizer.value(normalized.extra);
      out.extra =
        sanitized !== null && typeof sanitized === 'object' && !Array.isArray(sanitized)
          ? (sanitized as Record<string, unknown>)
          : { value: sanitized };
    }
    return out;
  } catch {
    return UNNORMALIZABLE;
  }
}
