/**
 * Page, route and environment context attached to every record.
 *
 * @remarks
 * Kept separate from `core/env.ts` so the environment accessors stay free of any
 * dependency on the sanitizer. The dependency direction here is
 * `page → env` and `page → sanitize`, and `sanitize → env`, which is acyclic.
 *
 * @packageDocumentation
 */

import { MAX_ROUTE_LENGTH, MAX_USER_AGENT_LENGTH } from '../errors/constants.js';
import { getDefaultSanitizer } from '../errors/sanitize.js';
import type { EnvironmentInfo, PageInfo } from '../errors/types.js';
import type { ResolvedTelemetryOptions } from './config.js';
import {
  getLocationHref,
  getPlatform,
  getUserAgent,
  getViewport,
  getVisibilityState,
  isOnline,
} from './env.js';
import { getState } from './state.js';

/**
 * Best-effort route for the current document.
 *
 * @returns the pathname (plus allow-listed query values), or `'unknown'` outside a
 * browser. Never throws.
 *
 * @remarks
 * The full URL is deliberately not used: a route is a grouping key, and query
 * strings frequently carry identifiers and tokens.
 *
 * @example
 * ```ts
 * import { currentRoute } from '@codewithrajat/rm-logvault';
 *
 * currentRoute(); // '/orders/103'
 * ```
 */
export function currentRoute(): string {
  try {
    const href = getLocationHref();
    if (href === undefined) return 'unknown';
    const sanitized = getDefaultSanitizer().url(href, MAX_ROUTE_LENGTH);
    if (sanitized === undefined) return 'unknown';
    // Drop the origin: routes should group across hosts (staging vs production).
    const withoutOrigin = sanitized.replace(/^https?:\/\/[^/]*/i, '');
    return withoutOrigin.length > 0 ? withoutOrigin : '/';
  } catch {
    return 'unknown';
  }
}

/**
 * Build the page block for a record.
 *
 * @returns the current URL, route and the page-load identifier
 *
 * @example
 * ```ts
 * import { currentPageInfo } from '@codewithrajat/rm-logvault';
 *
 * currentPageInfo(); // { url: '/checkout', route: '/checkout', pageLoadId: '…' }
 * ```
 */
export function currentPageInfo(): PageInfo {
  const state = getState();
  let url = 'unknown';
  try {
    const sanitized = getDefaultSanitizer().url(getLocationHref());
    if (sanitized !== undefined) url = sanitized;
  } catch {
    // keep 'unknown'
  }
  return { url, route: currentRoute(), pageLoadId: state.pageLoadId };
}

/**
 * Build the environment block for a record.
 *
 * @param options - resolved options supplying the application identity
 * @returns device and application metadata, all bounded and sanitized
 *
 * @example
 * ```ts
 * import { resolveOptions, currentEnvironment } from '@codewithrajat/rm-logvault';
 *
 * currentEnvironment(resolveOptions({ appName: 'checkout' })).appName; // 'checkout'
 * ```
 */
export function currentEnvironment(options: ResolvedTelemetryOptions): EnvironmentInfo {
  const sanitizer = getDefaultSanitizer();
  const out: {
    appName?: string;
    appVersion?: string;
    buildId?: string;
    environment?: string;
    userAgent?: string;
    platform?: string;
    viewport?: string;
    online?: boolean;
    visibilityState?: string;
  } = {};

  if (options.appName !== undefined) out.appName = sanitizer.text(options.appName, 200);
  if (options.appVersion !== undefined) out.appVersion = sanitizer.text(options.appVersion, 200);
  if (options.buildId !== undefined) out.buildId = sanitizer.text(options.buildId, 200);
  if (options.environment !== undefined) out.environment = sanitizer.text(options.environment, 200);

  const userAgent = getUserAgent();
  if (userAgent !== undefined) out.userAgent = sanitizer.text(userAgent, MAX_USER_AGENT_LENGTH);

  const platform = getPlatform();
  if (platform !== undefined) out.platform = sanitizer.text(platform, 200);

  const viewport = getViewport();
  if (viewport !== undefined) out.viewport = viewport;

  out.online = isOnline();

  const visibility = getVisibilityState();
  if (visibility !== undefined) out.visibilityState = visibility;

  return out;
}

/** Minimal application identity stamped onto log records. */
export interface LogEnvironmentInfo {
  readonly appName?: string;
  readonly appVersion?: string;
  readonly buildId?: string;
  readonly environment?: string;
}

/**
 * Build the narrower environment block used by log records.
 *
 * @param options - resolved options supplying the application identity
 * @returns application identity only, since logs are high-volume
 */
export function currentLogEnvironment(options: ResolvedTelemetryOptions): LogEnvironmentInfo {
  const out: {
    appName?: string;
    appVersion?: string;
    buildId?: string;
    environment?: string;
  } = {};
  if (options.appName !== undefined) out.appName = options.appName;
  if (options.appVersion !== undefined) out.appVersion = options.appVersion;
  if (options.buildId !== undefined) out.buildId = options.buildId;
  if (options.environment !== undefined) out.environment = options.environment;
  return out;
}
