/**
 * A tiny, throwing-proof event emitter for state observation.
 *
 * @remarks
 * The library deliberately does **not** ship a state container. Frameworks have
 * their own (Redux, Zustand, signals, `useSyncExternalStore`), and picking one
 * would make the package opinionated about something it has no business deciding.
 * What it ships instead is this: a way to observe what the library did, so a
 * consumer's own store can react to it.
 *
 * Three rules make it safe to hand to a host application:
 *
 * 1. **A listener can never break a capture.** Every listener runs inside its own
 *    guarded call, so a throwing subscriber cannot stop the error it was notified
 *    about from being persisted.
 * 2. **An async listener can never produce an unhandled rejection.** A returned
 *    promise is observed and its failure routed to
 *    {@link reportInternalFailure}, which is the whole reason `on` accepts a
 *    possibly-async listener at all.
 * 3. **A listener can unsubscribe during dispatch.** The subscriber set is
 *    snapshotted before iteration, so removing a listener from inside its own
 *    callback — or while an earlier listener is running — is well-defined.
 *
 * @packageDocumentation
 */

import { now } from './env.js';
import { reportInternalFailure, reportInternalNote } from './internal.js';

/** Every event the library can emit. */
export type TelemetryEventType =
  | 'error:captured'
  | 'log:written'
  | 'sync:started'
  | 'sync:completed'
  | 'sync:failed'
  | 'record:dropped';

/**
 * The members every event shares.
 *
 * @remarks
 * Deliberately **not** carrying an index signature. One would make each specific
 * payload below unassignable to this base — TypeScript requires every property of
 * a source type to satisfy a target's index signature — so the shared fields live
 * here and the payload-specific ones live on the interfaces that extend it.
 */
export interface TelemetryEvent {
  /** Which event this is. */
  readonly type: TelemetryEventType;
  /** Milliseconds since the Unix epoch, stamped by the emitter. */
  readonly timestamp: number;
}

/** An error record was accepted and persisted. */
export interface ErrorCapturedEvent extends TelemetryEvent {
  readonly type: 'error:captured';
  /** The record's id. */
  readonly recordId: string;
  /** Stable grouping key for the failure. */
  readonly fingerprint: string;
  readonly severity: string;
  readonly source: string;
  readonly category: string;
  /** Whether the application handled it before it reached the library. */
  readonly handled: boolean;
  /** Occurrences aggregated into this record so far. */
  readonly occurrenceCount: number;
}

/** A log record passed the persist level and reached the sinks. */
export interface LogWrittenEvent extends TelemetryEvent {
  readonly type: 'log:written';
  readonly recordId: string;
  readonly level: string;
  /** The already-sanitized message. */
  readonly message: string;
}

/** An upload pass began. */
export interface SyncStartedEvent extends TelemetryEvent {
  readonly type: 'sync:started';
  readonly kind: 'errors' | 'logs';
  readonly recordCount: number;
}

/** An upload pass finished. */
export interface SyncCompletedEvent extends TelemetryEvent {
  readonly type: 'sync:completed';
  readonly kind: 'errors' | 'logs';
  readonly uploaded: number;
  readonly retried: number;
  readonly failed: number;
}

/** An upload pass ended with records the server rejected terminally. */
export interface SyncFailedEvent extends TelemetryEvent {
  readonly type: 'sync:failed';
  readonly kind: 'errors' | 'logs';
  /**
   * HTTP status of the failing batch, or `0` when it was not captured.
   *
   * @remarks
   * `FlushSummary` is a per-kind aggregate over several batch attempts, which can
   * fail for different reasons, so it carries no single status. `0` therefore means
   * **"not captured"**, not "network failure" — do not read it as the transport
   * convention used by `HttpError.statusCode`. Use `recordCount` for the size and
   * `onTerminalFailure` on the REST options when you need the actual status.
   */
  readonly status: number;
  readonly recordCount: number;
}

/** A capture was discarded, with the reason, so a UI can explain the gap. */
export interface RecordDroppedEvent extends TelemetryEvent {
  readonly type: 'record:dropped';
  readonly kind: 'errors' | 'logs';
  /** `rate-limit`, `consent`, `payload-limit` or `before-hook`. */
  readonly reason: string;
  readonly count: number;
}

/**
 * Every event payload, keyed by its `type`.
 *
 * @remarks
 * The typed overloads on {@link EventEmitter.emit} are generated from this map, so
 * `emit` refuses a payload whose `type` and body disagree.
 */
export interface TelemetryEventMap {
  'error:captured': ErrorCapturedEvent;
  'log:written': LogWrittenEvent;
  'sync:started': SyncStartedEvent;
  'sync:completed': SyncCompletedEvent;
  'sync:failed': SyncFailedEvent;
  'record:dropped': RecordDroppedEvent;
}

/**
 * Any event payload the library can emit.
 *
 * @remarks
 * A discriminated union rather than `TelemetryEvent`, so `switch (event.type)`
 * narrows to the exact payload and a listener can read `event.fingerprint`
 * without a cast.
 */
export type TelemetryEventPayload =
  | ErrorCapturedEvent
  | LogWrittenEvent
  | SyncStartedEvent
  | SyncCompletedEvent
  | SyncFailedEvent
  | RecordDroppedEvent;

/**
 * A subscriber.
 *
 * @remarks
 * Returning a promise is allowed. The emitter observes it and routes a rejection
 * to the library's internal diagnostics rather than letting it surface as an
 * unhandled rejection.
 */
export type TelemetryEventListener = (event: TelemetryEventPayload) => void | Promise<void>;

/**
 * The observer handle exposed on `initTelemetry`'s return value.
 *
 * @example
 * ```ts
 * import { initTelemetry } from '@codewithrajat/rm-logvault';
 *
 * const telemetry = initTelemetry({ appName: 'checkout' });
 *
 * const off = telemetry.events.on('error:captured', (event) => {
 *   badge.textContent = String(Number(badge.textContent) + 1);
 *   void event.fingerprint;
 * });
 *
 * off(); // unsubscribe; safe to call more than once
 * ```
 */
export interface EventEmitter {
  /**
   * Subscribe to one event type.
   *
   * @param type - the event to observe
   * @param listener - called for every occurrence
   * @returns an unsubscribe function; calling it twice is safe
   */
  on<T extends TelemetryEventType>(
    type: T,
    listener: (event: TelemetryEventMap[T]) => void | Promise<void>,
  ): () => void;
  /**
   * Subscribe to every event type.
   *
   * @param listener - called for every occurrence, whatever its type
   * @returns an unsubscribe function; calling it twice is safe
   */
  onAny(listener: TelemetryEventListener): () => void;
  /**
   * Remove a previously registered listener.
   *
   * @param type - the event it was registered for
   * @param listener - the exact function reference passed to `on`
   */
  off<T extends TelemetryEventType>(
    type: T,
    listener: (event: TelemetryEventMap[T]) => void | Promise<void>,
  ): void;
  /**
   * Emit an event to every matching subscriber.
   *
   * @param event - the payload. Its `type` selects the subscribers; a payload
   * whose body does not match its `type` is a compile error.
   *
   * @remarks
   * Never throws. `timestamp` is stamped by the emitter when the caller did not
   * supply one.
   */
  emit(event: TelemetryEventPayload): void;
  /** Number of listeners for one type, or for all types when omitted. */
  listenerCount(type?: TelemetryEventType): number;
  /** Remove every listener. Called on `destroyTelemetry`. */
  clear(): void;
}

/** Whether a value looks like a promise. */
function isThenable(value: unknown): value is PromiseLike<unknown> {
  return (
    value !== null &&
    (typeof value === 'object' || typeof value === 'function') &&
    typeof (value as { then?: unknown }).then === 'function'
  );
}

/** Invoke one listener, containing both a synchronous throw and a rejection. */
function invoke(listener: TelemetryEventListener, event: TelemetryEventPayload): void {
  try {
    const result = listener(event);
    if (isThenable(result)) {
      // An async subscriber that fails is a bug in the subscriber, not in the
      // capture that notified it — so it is reported, never rethrown, and never
      // left to become an unhandled rejection.
      void Promise.resolve(result).catch((error: unknown) => {
        reportInternalFailure('event-listener', error);
      });
    }
  } catch (error) {
    reportInternalFailure('event-listener', error);
  }
}

/**
 * Create an {@link EventEmitter}.
 *
 * @returns a fresh emitter. Emitters are not shared: one belongs to one
 * `initTelemetry` installation and is replaced on re-initialization.
 *
 * @example
 * ```ts
 * import { createEventEmitter } from '@codewithrajat/rm-logvault';
 *
 * const events = createEventEmitter();
 * const off = events.on('error:captured', (event) => console.log(event.recordId));
 * off();
 * ```
 */
export function createEventEmitter(): EventEmitter {
  const listeners = new Map<TelemetryEventType, Set<TelemetryEventListener>>();
  const anyListeners = new Set<TelemetryEventListener>();
  /**
   * Guards against re-entrancy.
   *
   * @remarks
   * A listener that causes another event — the realistic cases are
   * `onAny(() => logger.warn(...))`, which writes a log record and so emits
   * `log:written`, and a listener that calls `captureError` — must not recurse.
   * The nested event is delivered **asynchronously, once**, and any further nesting
   * is dropped rather than queued.
   *
   * This is the same policy the logger already applies to its own re-entrancy, and
   * it is deliberate that the bound is *drop* rather than *queue*: a bounded queue
   * still lets a listener that emits on every event generate unbounded records and
   * memory, just more slowly. Dropping makes the failure mode finite, and the first
   * drop is reported so it is not silent.
   */
  let emitting = false;
  let deferred: TelemetryEventPayload | null = null;
  let nestingReported = false;
  /** `true` while the single permitted nested delivery is in flight. */
  let deliveringNested = false;

  /** Dispatch to a snapshot, so unsubscribe-during-dispatch is well-defined. */
  const dispatch = (event: TelemetryEventPayload): void => {
    const forType = listeners.get(event.type);
    if (forType !== undefined && forType.size > 0) {
      for (const listener of [...forType]) invoke(listener, event);
    }
    if (anyListeners.size > 0) {
      for (const listener of [...anyListeners]) invoke(listener, event);
    }
  };

  /**
   * Dispatch one event.
   *
   * @param isNested - whether this is the one permitted nested delivery, which
   * makes any emission it causes a drop rather than another round
   *
   * @remarks
   * The nesting budget is deliberately hard at one level. It has to be: the
   * realistic trigger is `onAny(() => logger.warn(...))`, where the listener causes
   * another `log:written`, whose listener causes another, and so on. Two levels of
   * allowance just moves the infinite loop one step later — which is exactly what
   * the first attempt at this fix did, and the scratch test caught it spinning.
   */
  const process = (event: TelemetryEventPayload, isNested: boolean): void => {
    emitting = true;
    try {
      dispatch(event);
    } catch (error) {
      reportInternalFailure('event-dispatch', error);
    } finally {
      emitting = false;
    }

    if (isNested) {
      // Budget exhausted: any emission from here on is dropped, not queued.
      deliveringNested = false;
      deferred = null;
      return;
    }

    const next = deferred;
    deferred = null;
    if (next === null) return;

    // Delivered on a fresh task. `deliveringNested` makes any emission caused by
    // that delivery a drop, so this cannot become an endless chain.
    deliveringNested = true;
    void Promise.resolve().then(() => {
      process(next, true);
    });
  };

  const add = (
    set: Set<TelemetryEventListener>,
    listener: TelemetryEventListener,
  ): (() => void) => {
    set.add(listener);
    return (): void => {
      set.delete(listener);
    };
  };

  return {
    on: (type, listener) => {
      if (typeof listener !== 'function') return (): void => undefined;
      let set = listeners.get(type);
      if (set === undefined) {
        set = new Set();
        listeners.set(type, set);
      }
      // The per-type overload narrows the payload, which makes the listener
      // contravariant with the stored union signature. This is the one place the
      // narrowing is erased; `on`'s public signature is what callers see.
      return add(set, listener as unknown as TelemetryEventListener);
    },

    onAny: (listener) => {
      if (typeof listener !== 'function') return (): void => undefined;
      return add(anyListeners, listener);
    },

    off: (type, listener) => {
      listeners.get(type)?.delete(listener as unknown as TelemetryEventListener);
    },

    emit: (event) => {
      try {
        if (event === null || typeof event !== 'object') return;
        if (listeners.size === 0 && anyListeners.size === 0) return;

        const stamped: TelemetryEventPayload =
          typeof event.timestamp === 'number' ? event : { ...event, timestamp: now() };

        if (emitting || deliveringNested) {
          // Re-entrant, or the nesting budget is already spent. Replaced rather
          // than appended, and reported once, so a listener that emits per event
          // cannot grow this without bound.
          deferred = stamped;
          if (!nestingReported) {
            nestingReported = true;
            reportInternalNote(
              'event-nesting',
              'a listener emitted during dispatch; one nested event is delivered asynchronously and further nesting is dropped',
            );
          }
          return;
        }

        process(stamped, false);
      } catch (error) {
        reportInternalFailure('event-emit', error);
      }
    },

    listenerCount: (type) => {
      if (type === undefined) {
        let total = anyListeners.size;
        for (const set of listeners.values()) total += set.size;
        return total;
      }
      return listeners.get(type)?.size ?? 0;
    },

    clear: (): void => {
      listeners.clear();
      anyListeners.clear();
      deferred = null;
    },
  };
}
