/**
 * Initialization, teardown and status.
 *
 * @remarks
 * `initTelemetry({ appName: 'x' })` is the whole integration. Everything the
 * library does — global handlers, persistence, the outbox, the export shortcut —
 * is wired here, and everything is registered with a {@link CleanupRegistry} so
 * `destroyTelemetry()` provably leaves no listener, timer or open database behind.
 *
 * Both entry points are **idempotent and never throw**. Calling `initTelemetry`
 * twice returns the same handle and installs nothing new (which is what makes HMR
 * and duplicate bundles safe); calling `destroyTelemetry` twice is a no-op.
 *
 * @packageDocumentation
 */

import type { ErrorTracker } from '../errors/captureError.js';
import {
  captureError,
  clearPreInitErrors,
  createErrorTracker,
  flushPreInitErrors,
  setCaptureSuppressed,
  setErrorTracker,
} from '../errors/captureError.js';
import { createSanitizer, resetDefaultSanitizer, setDefaultSanitizer } from '../errors/sanitize.js';
import { installDiagnosticsExportShortcut } from '../export/shortcut.js';
import { installGlobalErrorHandlers } from '../handlers/globalHandlers.js';
import { getLoggerController, logger } from '../logger/logger.js';
import type { LogTracker } from '../logger/logTracker.js';
import { createLogTracker } from '../logger/logTracker.js';
import { createErrorRepository } from '../storage/errorRepository.js';
import { createLogRepository } from '../storage/logRepository.js';
import type {
  StorageFailureReason,
  StorageState,
  TelemetryRepository,
} from '../storage/storage.types.js';
import { EMPTY_FLUSH_SUMMARY } from '../storage/storage.types.js';
import { resolveEndpoints } from '../sync/restSync.js';
import type { SyncStatus } from '../sync/sync.types.js';
import type { FlushResult, SyncManager } from '../sync/syncManager.js';
import { createSyncManager } from '../sync/syncManager.js';
import type { StorageMode, TelemetryOptions } from './config.js';
import { databaseNames, resolveOptions } from './config.js';
import { getDocument, getVisibilityState, getWindow, isOnline } from './env.js';
import type {
  ErrorCapturedEvent,
  EventEmitter,
  LogWrittenEvent,
  RecordDroppedEvent,
  SyncCompletedEvent,
  SyncFailedEvent,
  SyncStartedEvent,
} from './events.js';
import { createEventEmitter } from './events.js';
import { reportInternalFailure, reportInternalNote, resetInternalFailures } from './internal.js';
import type { CleanupRegistry } from './state.js';
import { createCleanupRegistry, getState, resetState } from './state.js';

/**
 * The object returned by `initTelemetry`.
 *
 * @remarks
 * A convenience bundle for code that holds a reference rather than importing the
 * module-level functions. Both are equivalent.
 */
export interface TelemetryHandle {
  /** The configured application name, if any. */
  readonly appName: string | undefined;
  /** The identifier shared by every record from this page load. */
  readonly pageLoadId: string;
  /** Whether capture is enabled. */
  readonly enabled: boolean;
  /** Persistence state at the moment `initTelemetry` returned. */
  readonly storage: StorageState;
  /**
   * Observe captures, writes and sync runs.
   *
   * @remarks
   * The same object is returned by every `initTelemetry` call, so a reference
   * captured once keeps working across a re-initialization.
   */
  readonly events: EventEmitter;
  /** Tear everything down. Equivalent to {@link destroyTelemetry}. */
  readonly destroy: () => void;
  /** Wait for every buffered write to settle. */
  readonly flush: () => Promise<void>;
  /** Force an upload pass. */
  readonly sync: () => Promise<FlushResult>;
}

/**
 * A synchronous snapshot of the library's state.
 *
 * @remarks
 * `pending` counts are a **snapshot**, refreshed at initialization, after every
 * flush, after a sync and after `clearTelemetryData()`. Reading them does not hit
 * IndexedDB, because this function is synchronous. Call
 * `flushTelemetry()` first if you need a fresh count.
 */
export interface TelemetryStatus {
  readonly initialized: boolean;
  /** Where records go: `'local'` (IndexedDB only) or `'remote'` (also uploaded). */
  readonly mode: StorageMode;
  readonly storage: StorageState;
  readonly online: boolean;
  readonly pending: { readonly errors: number; readonly logs: number };
  readonly droppedByRateLimit: number;
  readonly lastSync: number | undefined;
  readonly syncStatus: SyncStatus;
}

/**
 * The fields {@link setupTelemetry} accepts.
 *
 * @remarks
 * A focused subset of {@link TelemetryOptions}: the identity fields, the flat
 * endpoint aliases, the two log levels, the retention caps and the escape hatches.
 * Everything is optional, and anything omitted takes the same default the nested
 * option would.
 *
 * It is a `Pick` of `TelemetryOptions` rather than a separate shape, so the two
 * cannot drift: adding a field to the simple path is adding it to the real one.
 */
export type SimpleTelemetryOptions = Pick<
  TelemetryOptions,
  | 'app'
  | 'version'
  | 'build'
  | 'environment'
  | 'url'
  | 'errorUrl'
  | 'logUrl'
  | 'headers'
  | 'level'
  | 'consoleLevel'
  | 'captureConsole'
  | 'maxErrors'
  | 'maxLogs'
  | 'enabled'
  | 'consent'
  | 'onInternalError'
  | 'env'
>;

/**
 * The one-line front door to {@link initTelemetry}.
 *
 * @param options - see {@link SimpleTelemetryOptions}. Omitted entirely, this is
 * a complete configuration.
 * @returns the same {@link TelemetryHandle} `initTelemetry` returns. **Never
 * throws.**
 *
 * @remarks
 * This exists because the nested configuration is *precise* but not *short*: the
 * shortest real setup is `rest.errorsUrl`, `rest.logsUrl` and `logs.level`, which
 * is three levels of nesting to express two facts. `setupTelemetry` flattens it.
 *
 * It is deliberately **not** a second configuration system. It forwards to
 * `initTelemetry` unchanged, so:
 *
 * - The two are interchangeable, and can be mixed in one codebase.
 * - It is idempotent in exactly the same way — a second call returns the existing
 *   handle rather than reconfiguring.
 * - Anything it cannot express (adapters, `beforeCapture`, a custom `repository`)
 *   is still available by calling `initTelemetry` with the full options.
 *
 * @example
 * ```ts
 * import { setupTelemetry } from '@codewithrajat/rm-logvault';
 *
 * // Local only — no endpoint, nothing ever leaves the browser.
 * setupTelemetry({ app: 'checkout', version: '2.4.1' });
 *
 * // One collector for both kinds, persisted from `info` up.
 * setupTelemetry({
 *   app: 'checkout',
 *   url: '/telemetry',
 *   level: 'info',
 *   maxErrors: 1000,
 * });
 * ```
 */
export function setupTelemetry(options: SimpleTelemetryOptions = {}): TelemetryHandle {
  try {
    return initTelemetry(options);
  } catch (error) {
    // `initTelemetry` is already total; this is belt-and-braces so the guarantee
    // holds for this entry point independently of it.
    reportInternalFailure('setup', error);
    return disabledHandle();
  }
}

/** The live wiring for the current initialization. */
interface ActiveInstallation {
  readonly handle: TelemetryHandle;
  readonly errorTracker: ErrorTracker;
  readonly logTracker: LogTracker;
  readonly syncManager: SyncManager;
  readonly repository: TelemetryRepository;
  readonly cleanup: CleanupRegistry;
  readonly storageReady: () => boolean;
}

/** The current installation, or `null` before init / after destroy. */
let active: ActiveInstallation | null = null;
/** The emitter backing the current installation, or `null`. */
let currentEmitter: EventEmitter | null = null;

/**
 * Rate-limiter drop counts already reported through `record:dropped`.
 *
 * @remarks
 * `RateLimiter.dropped()` returns the **open** window's count and does not drain,
 * so emitting it raw would report the same drops on every sync. Tracking what has
 * already been reported turns it into a delta. Held per installation, because a
 * fresh `initTelemetry` builds fresh limiters.
 */
let reportedDrops = { errors: 0, logs: 0 };

/**
 * Emit one event, or drop it when nothing is listening.
 *
 * @remarks
 * The `null` guard is not an optimisation: it means a disabled or destroyed
 * installation pays nothing — not even a timestamp — on the error path.
 */
function emitEvent(event: Parameters<EventEmitter['emit']>[0]): void {
  currentEmitter?.emit(event);
}

/**
 * A stable emitter that always delegates to the installation's emitter.
 *
 * @remarks
 * `initTelemetry` returns this same object every time, so a consumer that captured
 * it from the first handle keeps observing after a re-initialization. Without the
 * indirection, teardown would leave that consumer holding an emitter that silently
 * stops receiving events.
 *
 * `on` and `onAny` deliberately **no-op** while there is no live installation
 * rather than buffering into a dormant emitter. An earlier draft buffered, and it
 * was worse in every respect: the buffered listeners were never migrated to the
 * real emitter, so they were silently never called, `listenerCount()` reported `0`
 * for a listener that `on()` had accepted, and nothing could ever remove them.
 * Pair it with `on()` inside an `initTelemetry` callback, or subscribe after init.
 */
const stableEmitter: EventEmitter = {
  on: (type, listener) => currentEmitter?.on(type, listener) ?? ((): void => undefined),
  onAny: (listener) => currentEmitter?.onAny(listener) ?? ((): void => undefined),
  off: (type, listener) => {
    currentEmitter?.off(type, listener);
  },
  emit: (event) => {
    currentEmitter?.emit(event);
  },
  listenerCount: (type) => currentEmitter?.listenerCount(type) ?? 0,
  clear: () => {
    currentEmitter?.clear();
  },
};

/** Emit `sync:started` for one kind when it has records to send. */
function emitSyncStarted(kind: 'errors' | 'logs', recordCount: number): void {
  if (recordCount <= 0) return;
  const event: SyncStartedEvent = {
    type: 'sync:started',
    timestamp: Date.now(),
    kind,
    recordCount,
  };
  emitEvent(event);
}

/** Emit the outcome of one kind's upload pass. */
function emitSyncOutcome(
  kind: 'errors' | 'logs',
  summary: {
    readonly claimed: number;
    readonly uploaded: number;
    readonly retried: number;
    readonly failed: number;
  },
): void {
  if (summary.claimed <= 0 && summary.uploaded <= 0 && summary.failed <= 0) return;
  const timestamp = Date.now();
  const completed: SyncCompletedEvent = {
    type: 'sync:completed',
    timestamp,
    kind,
    uploaded: summary.uploaded,
    retried: summary.retried,
    failed: summary.failed,
  };
  emitEvent(completed);

  if (summary.failed > 0) {
    const failed: SyncFailedEvent = {
      type: 'sync:failed',
      timestamp,
      kind,
      // `FlushSummary` carries no HTTP status, deliberately: it is a per-kind
      // aggregate over several batch attempts, which can fail for different
      // reasons. `0` therefore means "not captured", not "network failure" — see
      // the note on `SyncFailedEvent.status`.
      status: 0,
      recordCount: summary.failed,
    };
    emitEvent(failed);
  }
}

/**
 * Emit how many records the rate limiters discarded since the last report.
 *
 * @param errors - the error limiter's current window count
 * @param logs - the log limiter's current window count
 *
 * @remarks
 * One event **per kind**, carrying that kind's delta, so a dropped log is never
 * reported as a dropped error. The counters are cumulative within a window, so
 * only the increase is reported; a window that rolls before anyone calls
 * `syncTelemetry()` would otherwise be lost, which is accepted because the totals
 * are also reported at teardown.
 */
function emitDroppedByRateLimit(errors: number, logs: number): void {
  const timestamp = Date.now();
  const errorDelta = Math.max(0, Math.floor(errors) - reportedDrops.errors);
  const logDelta = Math.max(0, Math.floor(logs) - reportedDrops.logs);
  reportedDrops.errors = Math.max(reportedDrops.errors, Math.floor(errors));
  reportedDrops.logs = Math.max(reportedDrops.logs, Math.floor(logs));

  if (errorDelta > 0) {
    const event: RecordDroppedEvent = {
      type: 'record:dropped',
      timestamp,
      kind: 'errors',
      reason: 'rate-limit',
      count: errorDelta,
    };
    emitEvent(event);
  }
  if (logDelta > 0) {
    const event: RecordDroppedEvent = {
      type: 'record:dropped',
      timestamp,
      kind: 'logs',
      reason: 'rate-limit',
      count: logDelta,
    };
    emitEvent(event);
  }
}

/** Build the IndexedDB-backed repository pair from the database prefix. */
function createIdbRepository(
  dbPrefix: string,
  errorsPolicy: { retentionDays: number; maxRecords: number },
  logsPolicy: { retentionDays: number; maxRecords: number },
  openTimeoutMs: number,
  onFailure: (reason: StorageFailureReason, error: unknown) => void,
): TelemetryRepository {
  const names = databaseNames(dbPrefix);
  const errors = createErrorRepository({
    dbName: names.errors,
    cleanupPolicy: errorsPolicy,
    openTimeoutMs,
    onFailure,
  });
  const logs = createLogRepository({
    dbName: names.logs,
    cleanupPolicy: logsPolicy,
    openTimeoutMs,
    onFailure,
  });

  return {
    errors,
    logs,
    initialize: async () => {
      const errorResult = await errors.initialize();
      const logResult = await logs.initialize();
      // Only unusable if *both* databases failed: one working store is useful.
      if (!errorResult.ok && !logResult.ok) return errorResult;
      return { ok: true, value: undefined };
    },
    close: (): void => {
      errors.close();
      logs.close();
    },
  };
}

/** Refresh the cached pending counts from storage. */
async function refreshPendingCounts(): Promise<void> {
  const state = getState();
  const repository = state.repository;
  if (repository === null) {
    state.pendingErrors = 0;
    state.pendingLogs = 0;
    return;
  }
  try {
    const [errors, logs] = await Promise.all([
      repository.errors.pendingCount(),
      repository.logs.pendingCount(),
    ]);
    state.pendingErrors = errors.ok ? errors.value : 0;
    state.pendingLogs = logs.ok ? logs.value : 0;
  } catch {
    // Leave the previous snapshot in place.
  }
}

/**
 * A handle onto an installation that this copy of the library did not perform.
 *
 * @remarks
 * Returned when the shared state says the realm is already initialized but this
 * module has no `active` installation — that is, a second bundled copy called
 * `initTelemetry`. It reports the truth from the shared state and delegates flush
 * and sync to the same module-level functions the owning copy installed, so the
 * caller gets a working handle instead of a second installation.
 *
 * It deliberately does **not** construct a fresh handle from scratch: `appName`,
 * `pageLoadId` and `storage` come from the shared state, which is what the owning
 * copy wrote.
 */
function sharedHandle(state: ReturnType<typeof getState>): TelemetryHandle {
  return {
    appName: state.options?.appName,
    pageLoadId: state.pageLoadId,
    enabled: state.captureSuppressed !== true,
    storage: state.storageState,
    events: stableEmitter,
    destroy: (): void => {
      destroyTelemetry();
    },
    flush: flushTelemetry,
    sync: syncTelemetry,
  };
}

/** A handle that does nothing, used when the library is master-disabled. */
function disabledHandle(): TelemetryHandle {
  const state = getState();
  return {
    appName: state.options?.appName,
    pageLoadId: state.pageLoadId,
    enabled: false,
    storage: 'disabled',
    events: stableEmitter,
    destroy: (): void => {
      destroyTelemetry();
    },
    flush: async (): Promise<void> => undefined,
    sync: async (): Promise<FlushResult> => ({
      errors: { ...EMPTY_FLUSH_SUMMARY },
      logs: { ...EMPTY_FLUSH_SUMMARY },
    }),
  };
}

/**
 * Initialize telemetry.
 *
 * @param options - see {@link TelemetryOptions}. Every field is optional; zero
 * config gives IndexedDB persistence, global handlers and the export shortcut.
 * @returns a {@link TelemetryHandle}. **Never throws.**
 *
 * @remarks
 * Idempotent: calling it again returns the existing handle without installing a
 * second set of listeners. Call `destroyTelemetry()` first to reconfigure.
 *
 * @example
 * ```ts
 * import { initTelemetry } from '@codewithrajat/rm-logvault';
 *
 * // Zero config
 * initTelemetry({ appName: 'checkout' });
 *
 * // With uploads and a gated shortcut
 * initTelemetry({
 *   appName: 'checkout',
 *   appVersion: '2.4.1',
 *   errors: { captureCsp: true, captureResources: true },
 *   logs: { level: 'info', captureConsole: true },
 *   rest: { errorsUrl: '/telemetry/errors', logsUrl: '/telemetry/logs' },
 *   shortcut: { allow: () => isInternalUser() },
 * });
 * ```
 */
export function initTelemetry(options: TelemetryOptions = {}): TelemetryHandle {
  try {
    const state = getState();

    // Idempotent: a second call — from HMR, a duplicate bundle, or a careless
    // component — must not install anything twice, and must hand back the **same**
    // handle object the first call produced.
    //
    // The check is on the **shared** state, not on this module's `active`. A second
    // bundled copy of the library has its own `active === null` while the shared
    // state says the realm is already initialized; testing `active` alone would let
    // that copy install a second set of global handlers, a second log sink and its
    // own emitter — the duplicate capture the shared singleton exists to prevent.
    if (state.initialized) {
      // The owning copy returns the handle it built, so object identity holds.
      if (active !== null) return active.handle;
      // Another copy owns the installation (or this one was master-disabled).
      // Report the truth from the shared state instead of installing anything.
      return sharedHandle(state);
    }

    resetInternalFailures();
    const resolved = resolveOptions(options);
    state.options = resolved;
    reportedDrops = { errors: 0, logs: 0 };

    // A fresh emitter per installation, so a listener registered for one run does
    // not silently receive events from the next.
    const emitter = createEventEmitter();
    currentEmitter = emitter;
    state.eventEmitter = emitter;

    // Configure redaction before anything can capture.
    setDefaultSanitizer(
      createSanitizer({
        extraSensitiveKeys: resolved.redaction.extraSensitiveKeys,
        extraPatterns: resolved.redaction.extraPatterns,
        allowedQueryParams: resolved.redaction.allowedQueryParams,
      }),
    );

    const cleanup = createCleanupRegistry();
    state.cleanup = cleanup;

    // ---- master switch ----------------------------------------------------
    if (!resolved.enabled) {
      state.initialized = true;
      state.storageState = 'disabled';
      state.repository = null;
      setErrorTracker(null);
      setCaptureSuppressed(true);
      const handle = disabledHandle();
      active = null;
      return handle;
    }

    setCaptureSuppressed(false);

    // ---- persistence ------------------------------------------------------
    const onFailure = (reason: StorageFailureReason, error: unknown): void => {
      reportInternalFailure(`storage (${reason})`, error);
    };

    const repository =
      resolved.repository ??
      createIdbRepository(
        resolved.dbPrefix,
        { retentionDays: resolved.errors.retentionDays, maxRecords: resolved.errors.maxRecords },
        { retentionDays: resolved.logs.retentionDays, maxRecords: resolved.logs.maxRecords },
        resolved.openTimeoutMs,
        onFailure,
      );

    state.repository = repository;
    // IndexedDB opens asynchronously, so the window between this synchronous
    // function returning and the readiness promise settling is reported honestly
    // as `initializing` rather than as `disabled`.
    state.storageState = 'initializing';

    let storageReady = false;
    const readyPromise = repository
      .initialize()
      .then((result) => {
        storageReady = result.ok;
        state.storageState = result.ok ? 'ready' : 'unavailable';
        return result.ok;
      })
      .catch((error: unknown) => {
        reportInternalFailure('storage-init', error);
        state.storageState = 'unavailable';
        return false;
      });

    // ---- trackers ---------------------------------------------------------
    const syncManagerRef: { current: SyncManager | null } = { current: null };

    const errorTracker = createErrorTracker({
      repository: repository.errors,
      options: resolved,
      onRecord: (record): void => {
        state.pendingErrors += 1;
        syncManagerRef.current?.notifyNewRecords();
        const event: ErrorCapturedEvent = {
          type: 'error:captured',
          timestamp: record.timestamp,
          recordId: record.id,
          fingerprint: record.fingerprint,
          severity: record.severity,
          source: record.source,
          category: record.category,
          handled: record.handled,
          occurrenceCount: record.occurrenceCount,
        };
        emitter.emit(event);
      },
    });
    setErrorTracker(errorTracker);

    const logTracker = createLogTracker({
      repository: repository.logs,
      options: resolved,
      onRecord: (record): void => {
        state.pendingLogs += 1;
        syncManagerRef.current?.notifyNewRecords();
        const event: LogWrittenEvent = {
          type: 'log:written',
          timestamp: record.timestamp,
          recordId: record.id,
          level: record.level,
          message: record.message,
        };
        emitter.emit(event);
      },
    });

    const removeSink = logger.addSink(logTracker.sink);
    cleanup.add(removeSink);

    // Console verbosity is applied only when the caller asked for it. There is no
    // default, so initialising telemetry never changes console output on its own —
    // `logger.setLevel(...)` remains the runtime control.
    if (resolved.logs.consoleLevel !== undefined) {
      logger.setLevel(resolved.logs.consoleLevel);
    }

    // Attaching to an existing application logger is opt-in and additive.
    if (resolved.logSource !== undefined) {
      try {
        const detach = resolved.logSource.addSink(logTracker.sink);
        if (typeof detach === 'function') cleanup.add(detach);
      } catch (error) {
        reportInternalFailure('log-source', error);
      }
    }

    // ---- global handlers --------------------------------------------------
    if (resolved.errors.enabled) {
      const removeHandlers = installGlobalErrorHandlers({
        preventDefaultUnhandledRejection: resolved.errors.preventDefaultUnhandledRejection,
        captureResources: resolved.errors.captureResources,
        captureCsp: resolved.errors.captureCsp,
        captureChunkErrors: resolved.errors.captureChunkErrors,
        onError: (error, ctx): void => {
          captureError(error, ctx);
        },
      });
      cleanup.add(removeHandlers);
    }

    // ---- console capture --------------------------------------------------
    if (resolved.logs.enabled && resolved.logs.captureConsole) {
      getLoggerController().setConsoleCapture(true);
      cleanup.add(() => {
        getLoggerController().setConsoleCapture(false);
      });
    }

    // ---- diagnostics shortcut --------------------------------------------
    if (resolved.shortcut !== false) {
      const shortcut = resolved.shortcut;
      const removeShortcut = installDiagnosticsExportShortcut({
        key: shortcut.key,
        ctrl: shortcut.ctrl,
        shift: shortcut.shift,
        alt: shortcut.alt,
        meta: shortcut.meta,
        target: shortcut.target,
        allow: shortcut.allow,
        filenamePrefix: shortcut.filenamePrefix,
        onExported: shortcut.onExported,
      });
      cleanup.add(removeShortcut);
    }

    // ---- sync -------------------------------------------------------------
    const syncManager = createSyncManager({
      errors: resolved.errors.enabled ? repository.errors : null,
      logs: resolved.logs.enabled ? repository.logs : null,
      options: resolved,
      isStorageReady: () => storageReady,
    });
    syncManagerRef.current = syncManager;

    // `mode: 'remote'` is a statement of intent: the caller expects records to be
    // uploaded. If nothing is configured to receive them, say so once rather than
    // letting them discover it by finding an empty dashboard. Records are still
    // being kept safely in IndexedDB, so this is a note, not a failure.
    //
    // The check is for a *missing endpoint*, not for a disabled sync manager: a
    // deployment that configures URLs and then sets `rest.enabled: false` has
    // deliberately switched uploads off, and telling it that no endpoint is
    // configured would be false.
    const configured = resolveEndpoints(resolved);
    const hasEndpoint =
      configured.errorsUrl !== undefined ||
      configured.logsUrl !== undefined ||
      resolved.rest.transport !== undefined;

    if (resolved.mode === 'remote' && !syncManager.isEnabled() && !hasEndpoint) {
      reportInternalNote(
        'mode-remote-without-endpoint',
        'mode is "remote" but no valid REST endpoint is configured, so records are being kept in IndexedDB only',
      );
    }

    // Uploads must not begin before storage can actually read the outbox.
    void readyPromise.then((ok) => {
      if (ok) syncManager.start();
    });

    // ---- flush triggers ---------------------------------------------------
    const flushBuffered = async (keepalive = false): Promise<void> => {
      await errorTracker.flush();
      await logTracker.flush();
      if (keepalive && syncManager.isEnabled()) {
        // Best-effort drain at the last reliable write moment.
        try {
          await syncManager.flush(true);
        } catch {
          // ignore
        }
      }
      await refreshPendingCounts();
    };

    const windowObject = getWindow();
    if (windowObject !== null && windowObject !== undefined) {
      const onPageHide = (): void => {
        void flushBuffered(true);
      };
      cleanup.addListener(windowObject, 'pagehide', onPageHide);
    }

    const documentObject = getDocument();
    if (documentObject !== undefined && documentObject !== null) {
      const onVisibilityChange = (): void => {
        if (getVisibilityState() === 'hidden') void flushBuffered(true);
      };
      cleanup.addListener(documentObject, 'visibilitychange', onVisibilityChange);
    }

    // ---- replay anything captured before init -----------------------------
    // `initialized` must be set before replay, or the logger would buffer again.
    state.initialized = true;
    flushPreInitErrors(errorTracker);
    getLoggerController().replayPreInit();

    const handle: TelemetryHandle = {
      appName: resolved.appName,
      pageLoadId: state.pageLoadId,
      enabled: true,
      storage: state.storageState,
      events: stableEmitter,
      destroy: (): void => {
        destroyTelemetry();
      },
      flush: async (): Promise<void> => {
        await flushBuffered(false);
      },
      sync: (): Promise<FlushResult> => syncTelemetry(),
    };

    active = {
      handle,
      errorTracker,
      logTracker,
      syncManager,
      repository,
      cleanup,
      storageReady: () => storageReady,
    };

    // Establish the first snapshot of pending counts.
    void refreshPendingCounts();

    return handle;
  } catch (error) {
    reportInternalFailure('init', error);
    try {
      const state = getState();
      state.initialized = true;
      state.storageState = 'unavailable';
    } catch {
      // ignore
    }
    return disabledHandle();
  }
}

/**
 * Tear down everything `initTelemetry` installed.
 *
 * @remarks
 * Idempotent and **never throws**. It stops dispatch, removes every listener and
 * timer, flushes buffered records, closes both databases, restores any wrapped
 * `console` methods and restores the default sanitizer. The flush and close are
 * asynchronous; the synchronous part (listener removal, dispatch stop) completes
 * before this function returns, so no further capture can occur.
 *
 * @example
 * ```ts
 * import { initTelemetry, destroyTelemetry } from '@codewithrajat/rm-logvault';
 *
 * const handle = initTelemetry({ appName: 'checkout' });
 * // …later, e.g. on unmount of a test harness or a microfrontend teardown
 * destroyTelemetry();
 * ```
 */
export function destroyTelemetry(): void {
  try {
    const state = getState();
    const installation = active;
    if (installation === null && !state.initialized) return;

    active = null;

    // 1. Stop accepting new work.
    state.initialized = false;
    setErrorTracker(null);
    setCaptureSuppressed(false);

    // Report what the rate limiters discarded before the emitter goes away, then
    // retire it. Listeners are cleared so a destroyed installation holds no
    // references to the application's callbacks.
    if (installation !== null) {
      emitDroppedByRateLimit(
        installation.errorTracker.droppedByRateLimit(),
        installation.logTracker.droppedByRateLimit(),
      );
    }
    currentEmitter?.clear();
    currentEmitter = null;
    state.eventEmitter = null;

    // 2. Remove listeners and timers synchronously.
    installation?.cleanup.run();
    installation?.syncManager.dispose();

    // 3. Persist and close. Deferred because this function is synchronous.
    if (installation !== null) {
      void (async (): Promise<void> => {
        try {
          await installation.errorTracker.flush();
        } catch {
          // ignore
        }
        try {
          await installation.logTracker.destroy();
        } catch {
          // ignore
        }
        try {
          installation.repository.close();
        } catch {
          // ignore
        }
      })();
    }

    // 4. Restore global defaults so a later re-init starts clean.
    try {
      getLoggerController().reset();
    } catch {
      // ignore
    }
    resetDefaultSanitizer();
    clearPreInitErrors();
    resetState();
  } catch (error) {
    reportInternalFailure('destroy', error);
  }
}

/**
 * Wait until every buffered write has settled.
 *
 * @returns a promise that resolves once the log batch, the error queue and the
 * pending-count snapshot are up to date. **Never rejects.**
 *
 * @example
 * ```ts
 * import { logger, flushTelemetry } from '@codewithrajat/rm-logvault';
 *
 * logger.error('[Checkout] payment failed', error);
 * await flushTelemetry();     // the record is now in IndexedDB
 * ```
 */
export async function flushTelemetry(): Promise<void> {
  try {
    const installation = active;
    if (installation === null) return;
    await installation.errorTracker.flush();
    await installation.logTracker.flush();
    await refreshPendingCounts();
  } catch (error) {
    reportInternalFailure('flush', error);
  }
}

/**
 * Force an upload pass.
 *
 * @returns one {@link FlushSummary} per record kind. **Never rejects.**
 *
 * @remarks
 * Buffered records are flushed to IndexedDB first, so everything eligible is
 * included in the upload. Concurrent calls share a single run.
 *
 * @example
 * ```ts
 * import { syncTelemetry } from '@codewithrajat/rm-logvault';
 *
 * const { errors, logs } = await syncTelemetry();
 * console.log(`uploaded ${errors.uploaded} errors and ${logs.uploaded} logs`);
 * ```
 */
export async function syncTelemetry(): Promise<FlushResult> {
  try {
    const installation = active;
    if (installation === null) {
      return { errors: { ...EMPTY_FLUSH_SUMMARY }, logs: { ...EMPTY_FLUSH_SUMMARY } };
    }
    await installation.errorTracker.flush();
    await installation.logTracker.flush();

    // Refresh the pending snapshot *before* reporting it, so `sync:started` carries
    // the count the pass is actually about to claim. Reading the incrementing
    // capture counters instead would over-report: `errorRepository.save`
    // aggregates identical fingerprints into one row, so several captures can be
    // one claimable record.
    const state = getState();
    await refreshPendingCounts();
    emitSyncStarted('errors', state.pendingErrors);
    emitSyncStarted('logs', state.pendingLogs);

    const result = await installation.syncManager.flush(false);
    emitSyncOutcome('errors', result.errors);
    emitSyncOutcome('logs', result.logs);

    await refreshPendingCounts();
    emitDroppedByRateLimit(
      installation.errorTracker.droppedByRateLimit(),
      installation.logTracker.droppedByRateLimit(),
    );
    return result;
  } catch (error) {
    reportInternalFailure('sync', error);
    return { errors: { ...EMPTY_FLUSH_SUMMARY }, logs: { ...EMPTY_FLUSH_SUMMARY } };
  }
}

/**
 * Move terminally-failed records back to `pending` and retry immediately.
 *
 * @returns how many records were re-queued. **Never rejects.**
 *
 * @remarks
 * This exists because a `401` marks a batch `failed` permanently — otherwise a
 * single expired token would silently discard every record captured during the
 * outage. After re-authenticating, call this to re-queue them.
 *
 * @example
 * ```ts
 * import { retryFailedTelemetry } from '@codewithrajat/rm-logvault';
 *
 * await refreshSession();
 * const requeued = await retryFailedTelemetry();
 * ```
 */
export async function retryFailedTelemetry(): Promise<number> {
  try {
    const installation = active;
    if (installation === null) return 0;
    const moved = await installation.syncManager.retryFailed();
    await refreshPendingCounts();
    return moved;
  } catch (error) {
    reportInternalFailure('retry-failed', error);
    return 0;
  }
}

/**
 * Delete every stored record from both databases.
 *
 * @returns `true` when both databases were cleared. **Never rejects.**
 *
 * @remarks
 * This is the GDPR "right to erasure" primitive. It clears the vault, not the
 * configuration: capture continues afterwards.
 *
 * @example
 * ```ts
 * import { clearTelemetryData } from '@codewithrajat/rm-logvault';
 *
 * await clearTelemetryData();   // user revoked consent
 * ```
 */
export async function clearTelemetryData(): Promise<boolean> {
  try {
    const state = getState();
    const repository = state.repository;
    if (repository === null) return false;

    const errors = await repository.errors.clear();
    const logs = await repository.logs.clear();
    clearPreInitErrors();
    await refreshPendingCounts();
    return errors.ok && logs.ok;
  } catch (error) {
    reportInternalFailure('clear', error);
    return false;
  }
}

/**
 * Read a synchronous snapshot of the library's state.
 *
 * @returns a {@link TelemetryStatus}. **Never throws.**
 *
 * @remarks
 * `pending` is a snapshot refreshed at init, after each flush and after a sync —
 * reading it does not touch IndexedDB, which is why this function is synchronous.
 * Call `flushTelemetry()` first when you need current numbers.
 *
 * @example
 * ```ts
 * import { getTelemetryStatus } from '@codewithrajat/rm-logvault';
 *
 * const status = getTelemetryStatus();
 * if (status.storage === 'unavailable') showStorageWarning();
 * console.log(status.pending.errors, 'errors queued');
 * ```
 */
export function getTelemetryStatus(): TelemetryStatus {
  try {
    const state = getState();
    const installation = active;
    return {
      initialized: state.initialized,
      mode: state.options?.mode ?? 'local',
      storage: state.storageState,
      online: isOnline(),
      pending: { errors: state.pendingErrors, logs: state.pendingLogs },
      droppedByRateLimit:
        (installation?.errorTracker.droppedByRateLimit() ?? 0) +
        (installation?.logTracker.droppedByRateLimit() ?? 0),
      lastSync: installation?.syncManager.lastSync(),
      syncStatus: installation?.syncManager.status() ?? 'idle',
    };
  } catch {
    return {
      initialized: false,
      mode: 'local',
      storage: 'unavailable',
      online: true,
      pending: { errors: 0, logs: 0 },
      droppedByRateLimit: 0,
      lastSync: undefined,
      syncStatus: 'idle',
    };
  }
}

/** Whether `initTelemetry` has completed and not been destroyed. */
export function isTelemetryInitialized(): boolean {
  return getState().initialized;
}
