/**
 * The logging facade, sink dispatch and pre-init buffering.
 *
 * @remarks
 * Three design decisions in this module are load-bearing:
 *
 * 1. **Sinks run before the console filter.** Persistence must keep working in
 *    production, where nobody is watching the console. `setLevel('off')` silences
 *    output without touching what gets stored.
 * 2. **Reserved prefixes are never persisted.** Messages beginning with
 *    `[ErrorTracking]`, `[LogTracking]`, `[Telemetry]` or `[DiagnosticsExport]`
 *    are the library's own diagnostics. Persisting them would create a feedback
 *    loop where each storage warning produces another record.
 * 3. **Re-entrancy is blocked, not just discouraged.** A sink that logs, or a
 *    wrapped `console.warn` called from inside our own writer, is dropped rather
 *    than recursed into.
 *
 * @packageDocumentation
 */

import { now } from '../core/env.js';
import { newId } from '../core/ids.js';
import { reportInternalFailure } from '../core/internal.js';
import { currentLogEnvironment, currentRoute } from '../core/page.js';
import { getState } from '../core/state.js';
import { MAX_LOG_ARGS, MAX_LOG_MESSAGE_LENGTH } from '../errors/constants.js';
import { getDefaultSanitizer } from '../errors/sanitize.js';
import { installConsoleCapture } from './consoleCapture.js';
import { createConsoleWriter } from './consoleWriter.js';
import type { LogLevel, LogLevelSetting } from './logger.constants.js';
import { INTERNAL_PREFIXES, meetsLevel, PRE_INIT_LOG_BUFFER_SIZE } from './logger.constants.js';
import type { Logger, LogRecord, LogSink } from './logger.types.js';
import type { SinkRegistry } from './sinkRegistry.js';
import { createSinkRegistry } from './sinkRegistry.js';

/** One logged call captured before `initTelemetry` ran. */
interface BufferedCall {
  readonly level: LogLevel;
  readonly message: string;
  readonly args: readonly unknown[];
}

/** Internal controller around the public {@link Logger}. */
export interface LoggerController {
  /** The public facade. */
  readonly logger: Logger;
  /** Re-dispatch anything captured before initialization. Idempotent. */
  replayPreInit(): void;
  /** How many pre-init calls are currently held. */
  bufferedCount(): number;
  /** Install or remove the opt-in `console.warn`/`console.error` wrapper. */
  setConsoleCapture(enabled: boolean): void;
  /** Emit through the reserved internal prefix, skipping all sinks. */
  emitInternal(level: LogLevel, message: string, args: readonly unknown[]): void;
  /** The sinks attached to this logger, for inspection and keyed removal. */
  readonly sinks: SinkRegistry;
  /** Restore console wrapping and drop buffered calls. Used by `destroyTelemetry`. */
  reset(): void;
}

/** Whether a message is one of the library's own diagnostics. */
export function isInternalMessage(message: string): boolean {
  for (const prefix of INTERNAL_PREFIXES) {
    if (message.startsWith(prefix)) return true;
  }
  return false;
}

/**
 * Create the logger controller.
 *
 * @returns a {@link LoggerController}; the public facade is `controller.logger`
 *
 * @example
 * ```ts
 * import { createLogger } from '@codewithrajat/rm-logvault';
 *
 * const controller = createLogger();
 * controller.logger.addSink({ write: (record) => ship(record) });
 * controller.logger.warn('[Checkout] retrying payment');
 * ```
 */
export function createLogger(): LoggerController {
  // Sinks live in a registry rather than an array so `getSinkRegistry()` can
  // report and detach them by key. `addSink` remains the only way to install one.
  const registry = createSinkRegistry();
  const writer = createConsoleWriter();

  let consoleLevel: LogLevelSetting = 'warn';
  let enabled = true;
  let busy = false;
  let replaying = false;
  let seq = 0;
  let sinkSeq = 0;
  let restoreConsole: (() => void) | undefined;
  const buffer: BufferedCall[] = [];

  /** Build a fully-populated, sanitized log record. */
  const buildRecord = (level: LogLevel, message: string, args: readonly unknown[]): LogRecord => {
    const state = getState();
    const options = state.options;
    const sanitizer = getDefaultSanitizer();

    seq += 1;

    const record: {
      schemaVersion: 1;
      id: string;
      uploadStatus: 'pending';
      uploadAttempts: number;
      level: LogLevel;
      message: string;
      data?: readonly unknown[];
      route?: string;
      pageLoadId: string;
      environment: ReturnType<typeof currentLogEnvironment>;
      timestamp: number;
      seq: number;
    } = {
      schemaVersion: 1,
      id: newId(),
      uploadStatus: 'pending',
      uploadAttempts: 0,
      level,
      message: sanitizer.text(message, MAX_LOG_MESSAGE_LENGTH),
      pageLoadId: state.pageLoadId,
      environment: options === null ? {} : currentLogEnvironment(options),
      timestamp: now(),
      seq,
    };

    if (args.length > 0) {
      // At most `MAX_LOG_ARGS` arguments, each deep-scrubbed.
      record.data = args.slice(0, MAX_LOG_ARGS).map((arg) => sanitizer.value(arg));
    }

    // The route is a per-record grouping key; omitted outside a browser.
    const route = currentRoute();
    if (route !== 'unknown') record.route = sanitizer.text(route, 300);

    return record;
  };

  /** Dispatch one call to sinks and the console. */
  const emit = (level: LogLevel, rawMessage: string, args: readonly unknown[]): void => {
    try {
      if (!enabled) return;
      if (busy) return;

      const message = typeof rawMessage === 'string' ? rawMessage : String(rawMessage);
      const internal = isInternalMessage(message);
      const state = getState();

      // Before initialization the sinks do not exist yet; hold the call so the
      // record can be built later with full application metadata.
      if (!replaying && !state.initialized && registry.size() === 0) {
        if (buffer.length < PRE_INIT_LOG_BUFFER_SIZE) {
          buffer.push({ level, message, args: args.slice(0, MAX_LOG_ARGS) });
        }
        // Older entries are kept; the newest overflow is dropped.
      }

      busy = true;
      try {
        if (!internal) {
          const record = buildRecord(level, message, args);
          // The registry snapshots internally, so a sink that unsubscribes
          // mid-dispatch is safe.
          registry.write(record);
        }

        if (meetsLevel(level, consoleLevel)) {
          writer.write(level, message, args);
        }
      } finally {
        busy = false;
      }
    } catch (error) {
      // Logging must never throw into the host application — but a throw here is
      // still a lost record (a hostile argument, a sanitizer internal failure), so
      // it is reported rather than swallowed silently.
      reportInternalFailure('log-emit', error);
    }
  };

  const logger: Logger = {
    trace: (message: string, ...args: readonly unknown[]): void => {
      emit('trace', message, args);
    },
    debug: (message: string, ...args: readonly unknown[]): void => {
      emit('debug', message, args);
    },
    info: (message: string, ...args: readonly unknown[]): void => {
      emit('info', message, args);
    },
    warn: (message: string, ...args: readonly unknown[]): void => {
      emit('warn', message, args);
    },
    error: (message: string, ...args: readonly unknown[]): void => {
      emit('error', message, args);
    },

    addSink: (sink: LogSink): (() => void) => {
      if (sink === null || typeof sink !== 'object' || typeof sink.write !== 'function') {
        return (): void => undefined;
      }
      sinkSeq += 1;
      // A declared `name` makes the registry readable; the sequence keeps two
      // sinks that declare the same name from replacing each other.
      const declared = typeof sink.name === 'string' && sink.name.length > 0 ? sink.name : 'sink';
      const remove = registry.register(`${declared}#${String(sinkSeq)}`, sink);
      // The first sink typically arrives with `initTelemetry`; replay then, so
      // pre-init records carry the application metadata.
      if (registry.size() === 1 && buffer.length > 0) controller.replayPreInit();
      return remove;
    },

    setLevel: (level: LogLevelSetting): void => {
      consoleLevel = level;
    },

    setEnabled: (value: boolean): void => {
      enabled = value === true;
    },

    getConfig: (): { readonly level: LogLevelSetting; readonly enabled: boolean } => ({
      level: consoleLevel,
      enabled,
    }),
  };

  const controller: LoggerController = {
    logger,

    replayPreInit: (): void => {
      if (buffer.length === 0) return;
      const calls = buffer.splice(0, buffer.length);
      replaying = true;
      try {
        for (const call of calls) emit(call.level, call.message, call.args);
      } finally {
        replaying = false;
      }
    },

    bufferedCount: (): number => buffer.length,

    setConsoleCapture: (value: boolean): void => {
      if (value) {
        if (restoreConsole !== undefined) return;
        restoreConsole = installConsoleCapture({
          levels: ['warn', 'error'],
          onCall: (level, args): void => {
            const first = args[0];
            const message = typeof first === 'string' ? first : '[console]';
            const rest = typeof first === 'string' ? args.slice(1) : args;
            emit(level, message, rest);
          },
        });
        return;
      }
      restoreConsole?.();
      restoreConsole = undefined;
    },

    emitInternal: (level: LogLevel, message: string, args: readonly unknown[]): void => {
      // Internal messages are console-only by construction (reserved prefix).
      emit(level, message, args);
    },

    sinks: registry,

    reset: (): void => {
      restoreConsole?.();
      restoreConsole = undefined;
      registry.clear();
      buffer.length = 0;
      consoleLevel = 'warn';
      enabled = true;
      busy = false;
      replaying = false;
      seq = 0;
      sinkSeq = 0;
    },
  };

  return controller;
}

/** Module-level logger instance backing the exported `logger` facade. */
const instance: LoggerController = createLogger();

/**
 * The logging facade.
 *
 * @example
 * ```ts
 * import { logger } from '@codewithrajat/rm-logvault';
 *
 * logger.info('[Checkout] cart loaded', { items: 3 });
 * logger.error('[Checkout] payment failed', error);
 * ```
 */
export const logger: Logger = instance.logger;

/** Access the controller behind {@link logger}. Intended for the library itself. */
export function getLoggerController(): LoggerController {
  return instance;
}

/**
 * The sink registry behind the module-level {@link logger}.
 *
 * @returns the {@link SinkRegistry} holding every sink attached to the shared
 * logger — including the library's own IndexedDB persistence sink
 *
 * @remarks
 * Read-only introspection and keyed removal. Install a sink with
 * `logger.addSink()`, which is what keeps pre-init replay and the re-entrancy
 * guard working; registering directly in the registry would bypass both.
 *
 * @example
 * ```ts
 * import { getSinkRegistry, logger } from '@codewithrajat/rm-logvault';
 *
 * logger.addSink({ name: 'overlay', write: (record) => render(record) });
 * getSinkRegistry().keys();   // ['@codewithrajat/rm-logvault-indexeddb#1', 'overlay#2']
 *
 * // Detach the overlay later, from anywhere.
 * const entry = getSinkRegistry().list().find((item) => item.name === 'overlay');
 * if (entry !== undefined) getSinkRegistry().unregister(entry.key);
 * ```
 */
export function getSinkRegistry(): SinkRegistry {
  return instance.sinks;
}
