/**
 * Request-failure classification shared by the axios, fetch and TanStack Query
 * adapters.
 *
 * @remarks
 * Two rules govern this module and both are security requirements:
 *
 * 1. **Read an allow-list, nothing else.** Only `method`, `url`, `status`,
 *    `statusText`, `code`, `timeout`, `duration` and the first present correlation
 *    header are ever touched. Request/response **bodies**, `params`, `data`,
 *    cookies and arbitrary headers are never read, so nothing sensitive can reach
 *    the vault through this path.
 * 2. **Never swallow.** Adapters classify the error and rethrow the *original*
 *    rejection unchanged.
 *
 * @packageDocumentation
 */

import { now, safeGet } from '../core/env.js';
import { getDefaultSanitizer } from './sanitize.js';
import type { ApiErrorContext, ApiErrorKind, ErrorCategory, ErrorSeverity } from './types.js';

/** Correlation headers probed in priority order. Never enumerated beyond these. */
export const CORRELATION_HEADERS: readonly string[] = [
  'x-request-id',
  'x-correlation-id',
  'x-trace-id',
  'traceparent',
];

/**
 * Property name an application sets on a rejection to mark it as an auth failure.
 *
 * @remarks
 * Auth cannot be inferred reliably from a status code alone (a 401 from a
 * refresh-token endpoint is not an auth *failure*, it is the refresh flow working).
 * The application's interceptor is the only place that knows, so it tags the error.
 */
export const AUTH_ERROR_FLAG = '_isTokenFetchError';

/**
 * Tag an error as an authentication failure so `captureApiError` classifies it as
 * `auth` with `warning` severity.
 *
 * @param error - the rejection to tag; returned unchanged for chaining
 * @returns the same object, so it can be used inline in an interceptor
 *
 * @example
 * ```ts
 * import { markAuthError } from '@codewithrajat/rm-logvault';
 *
 * axios.interceptors.response.use(undefined, (error) => {
 *   if (error.response?.status === 401) markAuthError(error);
 *   return Promise.reject(error);
 * });
 * ```
 */
export function markAuthError<T>(error: T): T {
  if (error !== null && typeof error === 'object') {
    try {
      Object.defineProperty(error, AUTH_ERROR_FLAG, {
        value: true,
        enumerable: false,
        configurable: true,
        writable: true,
      });
    } catch {
      // Frozen or exotic object: classification falls back to http/network.
    }
  }
  return error;
}

/** Whether an error was tagged by {@link markAuthError}. */
export function isAuthError(error: unknown): boolean {
  return safeGet(error, AUTH_ERROR_FLAG) === true;
}

/** Minimal description of an outgoing request. */
export interface FetchRequestInfo {
  /** HTTP method, e.g. `GET`. */
  readonly method?: string | undefined;
  /** Absolute or relative request URL. */
  readonly url?: string | undefined;
  /** `performance.now()`/`Date.now()` captured before the request was issued. */
  readonly startedAt?: number | undefined;
}

/** What went wrong with a `fetch` call. */
export interface FetchFailure {
  /** The rejection reason, when the call rejected (network error, abort, timeout). */
  readonly error?: unknown;
  /** The response, when the call resolved with a non-2xx status. */
  readonly response?: unknown;
  /** Marker set by an abort-on-timeout wrapper. */
  readonly timedOut?: boolean | undefined;
}

/** Classification result shared by both builders. */
export interface ApiClassification {
  readonly api: ApiErrorContext;
  readonly category: ErrorCategory;
  readonly severity: ErrorSeverity;
}

/** Map an {@link ApiErrorKind} onto a record category. */
export function categoryForKind(kind: ApiErrorKind): ErrorCategory {
  switch (kind) {
    case 'http':
      return 'http';
    case 'network':
      return 'network';
    case 'timeout':
      return 'timeout';
    case 'abort':
      return 'abort';
    case 'parse':
      return 'parse';
    case 'auth':
      return 'auth';
    default:
      return 'runtime';
  }
}

/**
 * Severity for a classified request failure.
 *
 * @remarks
 * `abort` is `info` because navigating away or typing in a search box aborts
 * requests constantly and is not a defect. `auth` is `warning`. A 4xx `http`
 * failure is `warning`; 5xx and everything else is `error`.
 */
export function severityForKind(kind: ApiErrorKind, status: number | undefined): ErrorSeverity {
  if (kind === 'abort') return 'info';
  if (kind === 'auth') return 'warning';
  if (kind === 'http') return status !== undefined && status < 500 ? 'warning' : 'error';
  return 'error';
}

/** Read a numeric property without triggering hostile getters. */
function readNumber(target: unknown, key: string): number | undefined {
  const value = safeGet(target, key);
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

/** Read a string property. */
function readString(target: unknown, key: string): string | undefined {
  const value = safeGet(target, key);
  return typeof value === 'string' && value.length > 0 ? value : undefined;
}

/** Read the HTTP status from an axios-shaped or fetch-shaped failure. */
function readStatus(error: unknown): number | undefined {
  const response = safeGet(error, 'response');
  const fromResponse = readNumber(response, 'status');
  if (fromResponse !== undefined) return fromResponse;
  return readNumber(error, 'status');
}

/**
 * Read one header by name, tolerating `AxiosHeaders` (`get()`), `Headers` and
 * plain objects. Only the requested names are probed; nothing is enumerated.
 */
function readHeader(headers: unknown, name: string): string | undefined {
  if (headers === null || headers === undefined) return undefined;
  try {
    const get = safeGet(headers, 'get');
    if (typeof get === 'function') {
      const value: unknown = Reflect.apply(get, headers, [name]);
      return typeof value === 'string' && value.length > 0 ? value : undefined;
    }
  } catch {
    return undefined;
  }

  if (typeof headers !== 'object') return undefined;
  try {
    for (const [key, value] of Object.entries(headers as Record<string, unknown>)) {
      if (key.toLowerCase() === name && typeof value === 'string' && value.length > 0) {
        return value;
      }
    }
  } catch {
    return undefined;
  }
  return undefined;
}

/** First present correlation header value. */
function readCorrelationId(error: unknown): string | undefined {
  const headers = safeGet(safeGet(error, 'response'), 'headers');
  const fallbackHeaders = headers ?? safeGet(error, 'headers');
  for (const name of CORRELATION_HEADERS) {
    const value = readHeader(fallbackHeaders, name);
    if (value !== undefined) return value;
  }
  return undefined;
}

/** Elapsed milliseconds since `startedAt`, clamped to `>= 0` for clock skew. */
function readDuration(startedAt: number | undefined): number | undefined {
  if (startedAt === undefined || !Number.isFinite(startedAt)) return undefined;
  const elapsed = now() - startedAt;
  return elapsed >= 0 ? elapsed : 0;
}

/** Build the shared, allow-listed API context. */
function buildContext(parts: {
  kind: ApiErrorKind;
  method?: string | undefined;
  url?: string | undefined;
  status?: number | undefined;
  statusText?: string | undefined;
  code?: string | undefined;
  timeout?: number | undefined;
  requestId?: string | undefined;
}): ApiErrorContext {
  const sanitizer = getDefaultSanitizer();
  const out: {
    kind: ApiErrorKind;
    method?: string;
    url?: string;
    status?: number;
    statusText?: string;
    code?: string;
    timeout?: number;
    requestId?: string;
  } = { kind: parts.kind };

  if (parts.method !== undefined) out.method = parts.method.toUpperCase();
  // The URL is scrubbed here so credentials, fragments and non-allow-listed query
  // values can never reach storage even if a caller passes a raw URL.
  if (parts.url !== undefined) {
    const url = sanitizer.url(parts.url);
    if (url !== undefined) out.url = url;
  }
  if (parts.status !== undefined) out.status = parts.status;
  if (parts.statusText !== undefined) out.statusText = sanitizer.text(parts.statusText, 200);
  if (parts.code !== undefined) out.code = parts.code;
  if (parts.timeout !== undefined) out.timeout = parts.timeout;
  if (parts.requestId !== undefined) out.requestId = sanitizer.text(parts.requestId, 200);
  return out;
}

/**
 * Classify an axios-style rejection.
 *
 * @param error - the rejection reason (axios error, fetch error, or anything else)
 * @param startedAt - timestamp captured before the request was issued
 * @returns the API context plus derived `category` and `severity`
 *
 * @remarks
 * Kind resolution order is: `auth` → `abort` → `timeout` → `parse` → `http` →
 * `network` → `unknown`.
 *
 * | Signal | Kind |
 * | --- | --- |
 * | {@link markAuthError} tag | `auth` |
 * | `ERR_CANCELED`, `CanceledError`, `AbortError` | `abort` |
 * | `ECONNABORTED`, `ETIMEDOUT`, `TimeoutError`, aborted-with-`timedOut` | `timeout` |
 * | `SyntaxError`, or `ERR_BAD_RESPONSE` with a 2xx/absent status | `parse` |
 * | any non-2xx status | `http` |
 * | `ERR_NETWORK`, or an axios error with no `response` | `network` |
 * | anything else | `unknown` |
 *
 * @example
 * ```ts
 * import { captureApiError, markAuthError } from '@codewithrajat/rm-logvault';
 *
 * axios.interceptors.response.use(undefined, (error) => {
 *   const startedAt = Date.now() - (error.config?.timeout ?? 0);
 *   captureApiError(error, startedAt);
 *   return Promise.reject(error);        // always rethrow unchanged
 * });
 * ```
 */
export function buildApiErrorContext(error: unknown, startedAt?: number): ApiClassification {
  try {
    const name = readString(error, 'name') ?? '';
    const code = readString(error, 'code');
    const status = readStatus(error);
    const response = safeGet(error, 'response');
    const statusText = readString(response, 'statusText') ?? readString(error, 'statusText');
    const config = safeGet(error, 'config');
    const method =
      readString(config, 'method') ??
      readString(error, 'method') ??
      readString(safeGet(error, 'request'), 'method');
    const url =
      readString(config, 'url') ??
      readString(error, 'url') ??
      readString(safeGet(error, 'request'), 'url');
    const timeout = readNumber(config, 'timeout') ?? readNumber(error, 'timeout');
    const duration = readDuration(startedAt);
    const requestId = readCorrelationId(error);

    let kind: ApiErrorKind;

    if (isAuthError(error)) {
      kind = 'auth';
    } else if (code === 'ERR_CANCELED' || name === 'CanceledError' || name === 'AbortError') {
      kind = safeGet(error, 'timedOut') === true ? 'timeout' : 'abort';
    } else if (code === 'ECONNABORTED' || code === 'ETIMEDOUT' || name === 'TimeoutError') {
      kind = 'timeout';
    } else if (
      name === 'SyntaxError' ||
      (code === 'ERR_BAD_RESPONSE' && (status === undefined || (status >= 200 && status < 300)))
    ) {
      kind = 'parse';
    } else if (status !== undefined) {
      kind = 'http';
    } else if (code === 'ERR_NETWORK' || response !== undefined) {
      kind = 'network';
    } else {
      kind = 'unknown';
    }

    const api = buildContext({
      kind,
      method,
      url,
      status,
      statusText,
      code,
      timeout,
      requestId,
    });
    if (duration !== undefined) {
      return {
        api: { ...api, duration },
        category: categoryForKind(kind),
        severity: severityForKind(kind, status),
      };
    }
    return { api, category: categoryForKind(kind), severity: severityForKind(kind, status) };
  } catch {
    return {
      api: { kind: 'unknown' },
      category: 'runtime',
      severity: 'error',
    };
  }
}

/**
 * Classify a failed `fetch` call.
 *
 * @param request - the request that was issued (method, url, start timestamp)
 * @param failure - the rejection reason and/or the non-2xx response
 * @returns the API context plus derived `category` and `severity`
 *
 * @remarks
 * Unlike axios, `fetch` rejects only on transport failure; a 500 resolves normally.
 * The fetch adapter therefore reports both shapes through this one builder, and
 * `status === 0` (or an absent response) is classified as `network`.
 *
 * @example
 * ```ts
 * import { captureFetchError } from '@codewithrajat/rm-logvault';
 *
 * const startedAt = Date.now();
 * const response = await fetch('/api/orders');
 * if (!response.ok) {
 *   captureFetchError({ method: 'GET', url: '/api/orders', startedAt }, { response });
 * }
 * ```
 */
export function buildFetchErrorContext(
  request: FetchRequestInfo,
  failure: FetchFailure,
): ApiClassification {
  try {
    const response = failure.response;
    const status = readNumber(response, 'status');
    const statusText = readString(response, 'statusText');
    const error = failure.error;
    const name = readString(error, 'name') ?? '';
    const code = readString(error, 'code');
    const timedOut = failure.timedOut === true || safeGet(error, 'timedOut') === true;
    const requestId = readCorrelationId(error) ?? readCorrelationId(response);
    const duration = readDuration(request.startedAt);

    const hasResponse = response !== undefined && response !== null;
    const effectiveStatus = hasResponse ? (status ?? 0) : undefined;

    let kind: ApiErrorKind;

    if (isAuthError(error)) {
      kind = 'auth';
    } else if (timedOut) {
      kind = 'timeout';
    } else if (name === 'AbortError' || code === 'ERR_CANCELED') {
      kind = 'abort';
    } else if (name === 'TimeoutError' || code === 'ETIMEDOUT') {
      kind = 'timeout';
    } else if (name === 'SyntaxError') {
      kind = 'parse';
    } else if (effectiveStatus !== undefined && effectiveStatus !== 0) {
      kind = 'http';
    } else if (error !== undefined || hasResponse) {
      kind = 'network';
    } else {
      kind = 'unknown';
    }

    const api = buildContext({
      kind,
      method: request.method,
      url: request.url,
      status: effectiveStatus,
      statusText,
      code,
      requestId,
    });
    if (duration !== undefined) {
      return {
        api: { ...api, duration },
        category: categoryForKind(kind),
        severity: severityForKind(kind, effectiveStatus),
      };
    }
    return {
      api,
      category: categoryForKind(kind),
      severity: severityForKind(kind, effectiveStatus),
    };
  } catch {
    return {
      api: { kind: 'unknown' },
      category: 'runtime',
      severity: 'error',
    };
  }
}
