/**
 * A dependency-free, self-healing IndexedDB connection wrapper.
 *
 * @remarks
 * IndexedDB is hostile in the real world: it is missing in Safari private mode,
 * throws from `open()` inside sandboxed iframes, hangs forever when another tab
 * holds an upgrade open, and disappears mid-session when a user clears site data.
 * This module therefore has one hard rule: **never throw**. Every fallible
 * operation returns a {@link StorageResult} so the rest of the library can degrade
 * to console-only instead of breaking the host application.
 *
 * @packageDocumentation
 */

import type { Maybe, Result } from '../core/types.js';
import type { StorageFailureReason } from './storage.types.js';

/** Default time to wait for `indexedDB.open()` before declaring it unavailable. */
export const DEFAULT_OPEN_TIMEOUT_MS = 5_000;

/** IndexedDB `DOMException` names that mean "the origin is out of space". */
const QUOTA_ERROR_NAMES: ReadonlySet<string> = new Set([
  'QuotaExceededError',
  'NS_ERROR_DOM_QUOTA_REACHED',
]);

/** IndexedDB `DOMException` names that mean "the value cannot be cloned". */
const SERIALIZATION_ERROR_NAMES: ReadonlySet<string> = new Set(['DataCloneError']);

/** IndexedDB `DOMException` names that mean "the connection is gone; reopen next call". */
const STALE_CONNECTION_ERROR_NAMES: ReadonlySet<string> = new Set([
  'InvalidStateError',
  'DatabaseClosedError',
  'AbortError',
  'TransactionInactiveError',
]);

/** Read the `name` of a thrown value without triggering hostile getters. */
function errorName(error: unknown): string {
  if (error === null || typeof error !== 'object') return '';
  try {
    const name: unknown = (error as { name?: unknown }).name;
    return typeof name === 'string' ? name : '';
  } catch {
    return '';
  }
}

/** Read a numeric `code` (legacy IndexedDB uses `22` for quota). */
function errorCode(error: unknown): number | undefined {
  if (error === null || typeof error !== 'object') return undefined;
  try {
    const code: unknown = (error as { code?: unknown }).code;
    return typeof code === 'number' ? code : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Map any thrown value onto a {@link StorageFailureReason}.
 *
 * @param error - the thrown value
 * @returns the failure class; defaults to `'transaction'`
 */
export function classifyStorageError(error: unknown): StorageFailureReason {
  const name = errorName(error);
  if (QUOTA_ERROR_NAMES.has(name) || errorCode(error) === 22) return 'quota';
  if (SERIALIZATION_ERROR_NAMES.has(name)) return 'serialization';
  return 'transaction';
}

/** Whether the failure means the cached connection must be discarded. */
function isStaleConnectionError(error: unknown): boolean {
  return STALE_CONNECTION_ERROR_NAMES.has(errorName(error));
}

/**
 * Resolve the `IDBFactory` to use.
 *
 * @param factory - an explicit factory (used by tests with `fake-indexeddb`)
 * @returns the factory, `undefined` when IndexedDB is unusable, or `'blocked'`
 * when accessing it threw (Safari private mode throws on property access)
 */
function resolveFactory(factory: Maybe<IDBFactory>): IDBFactory | 'blocked' | undefined {
  if (factory !== undefined) return factory;
  try {
    const candidate: unknown = Reflect.get(globalThis, 'indexedDB');
    if (candidate === null || typeof candidate !== 'object') return undefined;
    if (typeof (candidate as IDBFactory).open !== 'function') return undefined;
    return candidate as IDBFactory;
  } catch {
    return 'blocked';
  }
}

/**
 * Promisify an `IDBRequest`.
 *
 * @param request - the request to await
 * @returns a promise resolving with the request result, rejecting with `request.error`
 */
export function promisifyRequest<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    request.onsuccess = (): void => {
      resolve(request.result);
    };
    request.onerror = (): void => {
      reject(request.error ?? new Error('IDBRequest failed'));
    };
  });
}

/** Await a transaction's `oncomplete` (readwrite durability) or `onabort`/`onerror`. */
function promisifyTransaction(transaction: IDBTransaction): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    transaction.oncomplete = (): void => {
      resolve();
    };
    transaction.onabort = (): void => {
      reject(transaction.error ?? new Error('Transaction aborted'));
    };
    transaction.onerror = (): void => {
      reject(transaction.error ?? new Error('Transaction failed'));
    };
  });
}

/** Options accepted by {@link createDbConnection}. */
export interface IdbCoreOptions {
  /** Physical database name, e.g. `rm-logvault-errors`. */
  readonly dbName: string;
  /** Schema version. Bump only additively; never edit a shipped version. */
  readonly version: number;
  /** The single object store this connection exposes. */
  readonly storeName: string;
  /**
   * Schema creation/migration hook. Must be idempotent: it can be invoked again
   * after the user manually deletes the database mid-session.
   */
  readonly upgrade: (db: IDBDatabase, oldVersion: number, transaction: IDBTransaction) => void;
  /** Milliseconds to wait for `open()` before giving up. Default `5000`. */
  readonly openTimeoutMs?: Maybe<number>;
  /** Explicit `IDBFactory`; defaults to `globalThis.indexedDB`. */
  readonly indexedDB?: Maybe<IDBFactory>;
  /** Called once per distinct failure class so the host can observe degradation. */
  readonly onFailure?: Maybe<(reason: StorageFailureReason, error: unknown) => void>;
}

/**
 * A lazily-opened, self-healing database handle.
 *
 * @remarks
 * Transactions are only safe while awaiting IDB requests. Awaiting a macrotask
 * (`setTimeout`, `fetch`) inside {@link DbConnection.transaction} lets the
 * transaction auto-commit, after which further requests throw
 * `TransactionInactiveError`.
 */
export interface DbConnection {
  readonly dbName: string;
  readonly storeName: string;
  readonly version: number;
  /** Whether a live connection is currently cached. */
  isOpen(): boolean;
  /** Open (or reuse) the connection, re-running `upgrade` if the DB was deleted. */
  ensureOpen(): Promise<Result<IDBDatabase, StorageFailureReason>>;
  /**
   * Run `work` inside a transaction.
   *
   * @remarks
   * For `readwrite`, the promise resolves only on `oncomplete`, so callers know
   * the data is durable. If `work` rejects, the transaction is aborted and the
   * rejection reason is classified.
   */
  transaction<T>(
    mode: IDBTransactionMode,
    work: (store: IDBObjectStore, transaction: IDBTransaction) => Promise<T> | T,
  ): Promise<Result<T, StorageFailureReason>>;
  /**
   * Delete the whole database, including its schema.
   *
   * @remarks
   * This is *not* what `clearTelemetryData()` uses — that empties the stores with
   * `store.clear()` and keeps the schema, so capture can continue without a
   * re-upgrade. Use this only to remove the database entirely.
   */
  deleteDatabase(): Promise<Result<void, StorageFailureReason>>;
  /** Drop the cached connection. The next call reopens. */
  close(): void;
}

/**
 * Create a resilient connection to one IndexedDB object store.
 *
 * @param options - see {@link IdbCoreOptions}
 * @returns a {@link DbConnection}; constructing it never opens the database
 *
 * @example
 * ```ts
 * const connection = createDbConnection({
 *   dbName: 'rm-logvault-errors',
 *   version: 1,
 *   storeName: 'errors',
 *   upgrade(db, _old, tx) {
 *     if (!db.objectStoreNames.contains('errors')) {
 *       const store = db.createObjectStore('errors', { keyPath: 'id' });
 *       store.createIndex('by_fingerprint_status', ['fingerprint', 'uploadStatus']);
 *     }
 *   },
 * });
 *
 * const result = await connection.transaction('readonly', (store) =>
 *   promisifyRequest(store.count()),
 * );
 * if (result.ok) console.log(result.value);
 * ```
 */
export function createDbConnection(options: IdbCoreOptions): DbConnection {
  const dbName = options.dbName;
  const storeName = options.storeName;
  const version = options.version;
  const timeoutMs =
    typeof options.openTimeoutMs === 'number' &&
    Number.isFinite(options.openTimeoutMs) &&
    options.openTimeoutMs > 0
      ? options.openTimeoutMs
      : DEFAULT_OPEN_TIMEOUT_MS;

  /** Cached open connection, or `null` when closed/never opened. */
  let connection: IDBDatabase | null = null;
  /** In-flight open, so concurrent callers share one `open()` request. */
  let opening: Promise<Result<IDBDatabase, StorageFailureReason>> | null = null;
  /** Set once IndexedDB proves unusable, to avoid retrying a hopeless open. */
  let permanentlyUnavailable = false;

  const report = (reason: StorageFailureReason, error: unknown): void => {
    try {
      options.onFailure?.(reason, error);
    } catch {
      // Observers must never break storage.
    }
  };

  const detach = (db: IDBDatabase): void => {
    try {
      db.onclose = null;
      db.onversionchange = null;
    } catch {
      // ignore
    }
  };

  const drop = (db: IDBDatabase | null): void => {
    if (connection === db) connection = null;
    if (db !== null) detach(db);
  };

  /** Attach lifecycle handlers that keep the cache honest. */
  const attach = (db: IDBDatabase): void => {
    try {
      db.onversionchange = (): void => {
        // Another tab is upgrading: release our handle so it is not blocked.
        db.close();
        drop(db);
      };
      db.onclose = (): void => {
        // The browser closed the connection (storage cleared, crash recovery).
        drop(db);
      };
    } catch {
      // Older engines may not allow assigning these; harmless.
    }
  };

  const open = (): Promise<Result<IDBDatabase, StorageFailureReason>> => {
    const factory = resolveFactory(options.indexedDB);
    if (factory === undefined || factory === 'blocked') {
      permanentlyUnavailable = true;
      report('unavailable', new Error('IndexedDB is not available'));
      return Promise.resolve({ ok: false, reason: 'unavailable' });
    }

    return new Promise<Result<IDBDatabase, StorageFailureReason>>((resolve) => {
      let settled = false;
      let timedOut = false;
      let request: IDBOpenDBRequest | undefined;
      // `let` is required: `finish` may run synchronously (the `open()` throw path
      // below) before the timeout is created, so a `const` would be in its TDZ.
      // eslint-disable-next-line prefer-const
      let timer: ReturnType<typeof setTimeout> | undefined;

      const finish = (result: Result<IDBDatabase, StorageFailureReason>): void => {
        if (settled) return;
        settled = true;
        if (timer !== undefined) clearTimeout(timer);
        resolve(result);
      };

      try {
        request = factory.open(dbName, version);
      } catch (error) {
        report('unavailable', error);
        finish({ ok: false, reason: 'unavailable' });
        return;
      }

      timer = setTimeout(() => {
        timedOut = true;
        // The request may still succeed later; `onsuccess` closes that handle.
        report('transaction', new Error(`IndexedDB open timed out after ${String(timeoutMs)}ms`));
        finish({ ok: false, reason: 'transaction' });
      }, timeoutMs);

      request.onupgradeneeded = (event): void => {
        try {
          const db = request?.result;
          const tx = request?.transaction;
          if (db === undefined || db === null || tx === undefined || tx === null) return;
          const oldVersion = (event as IDBVersionChangeEvent).oldVersion ?? 0;
          options.upgrade(db, oldVersion, tx);
        } catch (error) {
          // Let the upgrade fail the open rather than corrupting the schema.
          report('transaction', error);
          try {
            request?.transaction?.abort();
          } catch {
            // ignore
          }
        }
      };

      request.onsuccess = (): void => {
        const db = request?.result;
        if (db === undefined || db === null) {
          finish({ ok: false, reason: 'unavailable' });
          return;
        }
        if (timedOut) {
          // We already reported failure: close the late arrival so it does not leak.
          try {
            db.close();
          } catch {
            // ignore
          }
          return;
        }
        connection = db;
        attach(db);
        finish({ ok: true, value: db });
      };

      request.onerror = (): void => {
        const error = request?.error;
        const reason = classifyStorageError(error);
        if (reason === 'unavailable' || reason === 'transaction') {
          // A repeated hard failure means the origin genuinely cannot use IDB.
          if (errorName(error) === 'SecurityError') permanentlyUnavailable = true;
        }
        report(reason, error);
        finish({ ok: false, reason });
      };

      request.onblocked = (): void => {
        // Another tab holds an upgrade open. The timeout above bounds the wait.
      };
    });
  };

  const ensureOpen = (): Promise<Result<IDBDatabase, StorageFailureReason>> => {
    if (connection !== null) {
      try {
        // Touching `objectStoreNames` throws `InvalidStateError` once closed.
        void connection.objectStoreNames.length;
        return Promise.resolve({ ok: true, value: connection });
      } catch {
        drop(connection);
      }
    }
    if (permanentlyUnavailable) {
      return Promise.resolve({ ok: false, reason: 'unavailable' });
    }
    opening ??= open().finally(() => {
      opening = null;
    });
    return opening;
  };

  const transaction = async <T>(
    mode: IDBTransactionMode,
    work: (store: IDBObjectStore, transaction: IDBTransaction) => Promise<T> | T,
  ): Promise<Result<T, StorageFailureReason>> => {
    const opened = await ensureOpen();
    if (!opened.ok) return { ok: false, reason: opened.reason };

    const db = opened.value;
    let tx: IDBTransaction;
    try {
      tx = db.transaction(storeName, mode);
    } catch (error) {
      // The store vanished (DB deleted or downgraded by another tab).
      drop(db);
      const reason = isStaleConnectionError(error) ? 'transaction' : classifyStorageError(error);
      report(reason, error);
      return { ok: false, reason };
    }

    const done = promisifyTransaction(tx);

    try {
      const store = tx.objectStore(storeName);
      const result = await work(store, tx);
      if (mode === 'readwrite') await done;
      else await done.catch(() => undefined);
      return { ok: true, value: result };
    } catch (error) {
      try {
        tx.abort();
      } catch {
        // Already aborted or completed.
      }
      // Swallow the abort rejection; the original error is what matters.
      await done.catch(() => undefined);
      if (isStaleConnectionError(error)) drop(db);
      const reason = classifyStorageError(error);
      report(reason, error);
      return { ok: false, reason };
    }
  };

  const deleteDatabase = async (): Promise<Result<void, StorageFailureReason>> => {
    const factory = resolveFactory(options.indexedDB);
    if (factory === undefined || factory === 'blocked') {
      return { ok: false, reason: 'unavailable' };
    }
    close();
    return new Promise<Result<void, StorageFailureReason>>((resolve) => {
      let request: IDBOpenDBRequest;
      try {
        request = factory.deleteDatabase(dbName);
      } catch (error) {
        report('unavailable', error);
        resolve({ ok: false, reason: 'unavailable' });
        return;
      }
      request.onsuccess = (): void => {
        resolve({ ok: true, value: undefined });
      };
      request.onerror = (): void => {
        const reason = classifyStorageError(request.error);
        report(reason, request.error);
        resolve({ ok: false, reason });
      };
      request.onblocked = (): void => {
        // Our own handle is closed above, so this only waits on other tabs.
      };
    });
  };

  function close(): void {
    const db = connection;
    connection = null;
    if (db !== null) {
      detach(db);
      try {
        db.close();
      } catch {
        // ignore
      }
    }
  }

  return {
    dbName,
    storeName,
    version,
    isOpen: (): boolean => connection !== null,
    ensureOpen,
    transaction,
    deleteDatabase,
    close,
  };
}
