/**
 * Structural validation of persisted rows.
 *
 * @remarks
 * IndexedDB is not a trusted store. A row can be malformed because an older build
 * wrote it, because a user edited it in DevTools, because a schema migration was
 * interrupted, or because a different library used the same database name. Every
 * read therefore validates, and malformed rows are **deleted** rather than
 * returned — a poison row must not be able to break the diagnostics export forever.
 *
 * Validation is deliberately shallow: it checks the fields the library and its
 * consumers actually read, not every optional member.
 *
 * @packageDocumentation
 */

import { SCHEMA_VERSION } from '../errors/constants.js';
import type { ErrorRecord } from '../errors/types.js';
import type { LogRecord } from '../logger/logger.types.js';

/** Recognised upload states. */
const UPLOAD_STATUSES: ReadonlySet<string> = new Set([
  'pending',
  'uploading',
  'uploaded',
  'failed',
]);

/** Recognised log levels. */
const LOG_LEVELS: ReadonlySet<string> = new Set(['trace', 'debug', 'info', 'warn', 'error']);

/** Read a property without triggering hostile getters. */
function prop(value: unknown, key: string): unknown {
  if (value === null || typeof value !== 'object') return undefined;
  try {
    return (value as Record<string, unknown>)[key];
  } catch {
    return undefined;
  }
}

/** Whether `value` is a non-empty string. */
function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0;
}

/** Whether `value` is a finite number. */
function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

/**
 * Validate an `ErrorRecord` read from storage.
 *
 * @param value - the raw stored value
 * @returns `true` when the row is usable
 *
 * @example
 * ```ts
 * import { isErrorRecord } from '@codewithrajat/rm-logvault';
 *
 * isErrorRecord(JSON.parse(row)); // false for legacy / hand-edited rows
 * ```
 */
export function isErrorRecord(value: unknown): value is ErrorRecord {
  if (value === null || typeof value !== 'object') return false;
  if (prop(value, 'schemaVersion') !== SCHEMA_VERSION) return false;
  if (!isNonEmptyString(prop(value, 'id'))) return false;
  if (!isNonEmptyString(prop(value, 'fingerprint'))) return false;

  const status = prop(value, 'uploadStatus');
  if (typeof status !== 'string' || !UPLOAD_STATUSES.has(status)) return false;

  if (!isFiniteNumber(prop(value, 'uploadAttempts'))) return false;
  if (!isNonEmptyString(prop(value, 'name'))) return false;
  if (!isNonEmptyString(prop(value, 'source'))) return false;
  if (!isNonEmptyString(prop(value, 'severity'))) return false;
  if (!isNonEmptyString(prop(value, 'category'))) return false;
  if (typeof prop(value, 'handled') !== 'boolean') return false;

  if (!isFiniteNumber(prop(value, 'timestamp'))) return false;
  if (!isFiniteNumber(prop(value, 'firstSeen'))) return false;
  if (!isFiniteNumber(prop(value, 'lastSeen'))) return false;
  if (!isFiniteNumber(prop(value, 'occurrenceCount'))) return false;

  const page = prop(value, 'page');
  if (!isNonEmptyString(prop(page, 'pageLoadId'))) return false;

  return true;
}

/**
 * Validate a `LogRecord` read from storage.
 *
 * @param value - the raw stored value
 * @returns `true` when the row is usable
 *
 * @example
 * ```ts
 * import { isLogRecord } from '@codewithrajat/rm-logvault';
 *
 * isLogRecord({ schemaVersion: 1, id: 'a', uploadStatus: 'pending', uploadAttempts: 0,
 *   level: 'warn', message: 'hi', pageLoadId: 'p', timestamp: 1, seq: 1 });
 * // true
 * ```
 */
export function isLogRecord(value: unknown): value is LogRecord {
  if (value === null || typeof value !== 'object') return false;
  if (prop(value, 'schemaVersion') !== SCHEMA_VERSION) return false;
  if (!isNonEmptyString(prop(value, 'id'))) return false;

  const status = prop(value, 'uploadStatus');
  if (typeof status !== 'string' || !UPLOAD_STATUSES.has(status)) return false;

  if (!isFiniteNumber(prop(value, 'uploadAttempts'))) return false;

  const level = prop(value, 'level');
  if (typeof level !== 'string' || !LOG_LEVELS.has(level)) return false;

  if (typeof prop(value, 'message') !== 'string') return false;
  if (!isNonEmptyString(prop(value, 'pageLoadId'))) return false;
  if (!isFiniteNumber(prop(value, 'timestamp'))) return false;
  if (!isFiniteNumber(prop(value, 'seq'))) return false;

  return true;
}
