/**
 * The upload outbox.
 *
 * @remarks
 * Records are written to IndexedDB first and uploaded second, so an offline user
 * loses nothing and a failing endpoint never costs data. This module owns the
 * "second" half:
 *
 * - **Claim, then send.** `claimPending` flips rows to `uploading` atomically, so
 *   two tabs cannot upload the same record. A claim that is never completed (tab
 *   closed mid-upload) is returned to `pending` by the stale-lease sweep.
 * - **One run at a time.** Concurrent `flush()` calls share a single in-flight run
 *   instead of racing.
 * - **Backoff, not busy-waiting.** Failures schedule the next attempt
 *   exponentially further out, honouring `Retry-After` when the server sends one.
 * - **Never self-inflicted.** Uploads go through the configured transport, not the
 *   application's HTTP client, so an upload failure cannot create a new error.
 *
 * @packageDocumentation
 */

import type { ResolvedTelemetryOptions } from '../core/config.js';
import { isOnline, now } from '../core/env.js';
import { reportInternalFailure } from '../core/internal.js';
import type { RecordKind, Timestamp } from '../core/types.js';
import type { ErrorRepository, FlushSummary, LogRepository } from '../storage/storage.types.js';
import { EMPTY_FLUSH_SUMMARY } from '../storage/storage.types.js';
import { createFetchTransport } from './remoteTransport.js';
import { buildRestBody, classifyResponse, resolveEndpoints } from './restSync.js';
import type { RemoteTransport, SyncStatus, TransportResponse } from './sync.types.js';
import {
  BACKOFF_MAX_MS,
  backoffDelay,
  CLAIM_LEASE_MS,
  FIRST_FLUSH_DELAY_MS,
  KEEPALIVE_MAX_BYTES,
  MAX_BATCHES_PER_FLUSH,
  NOTIFY_DEBOUNCE_MS,
  REQUEST_TIMEOUT_MS,
} from './sync.types.js';

/** Result of one flush run. */
export interface FlushResult {
  readonly errors: FlushSummary;
  readonly logs: FlushSummary;
}

/** Options for {@link createSyncManager}. */
export interface SyncManagerOptions {
  /** Error repository, or `null` when error capture is disabled. */
  readonly errors: ErrorRepository | null;
  /** Log repository, or `null` when log capture is disabled. */
  readonly logs: LogRepository | null;
  /** Resolved configuration. */
  readonly options: ResolvedTelemetryOptions;
  /** Storage readiness gate. Uploads never start before this returns `true`. */
  readonly isStorageReady: () => boolean;
}

/**
 * The uploader.
 *
 * @remarks
 * Exposed for advanced wiring and tests. Applications normally only observe it
 * through `syncTelemetry()`, `getTelemetryStatus()` and `retryFailedTelemetry()`.
 */
export interface SyncManager {
  /** Requeue stale claims, attach the `online` listener and schedule the first run. */
  start(): void;
  /** Clear timers and the `online` listener. In-flight work still settles. */
  stop(): void;
  /** Force a flush. Concurrent calls share one run. */
  flush(keepalive?: boolean): Promise<FlushResult>;
  /** Pull the next scheduled flush forward after new records arrive. */
  notifyNewRecords(): void;
  /** Current uploader state. */
  status(): SyncStatus;
  /** Timestamp of the last fully successful run. */
  lastSync(): Timestamp | undefined;
  /** Move terminally-failed records back to `pending`. Returns how many moved. */
  retryFailed(): Promise<number>;
  /** Whether uploads are configured and valid. */
  isEnabled(): boolean;
  /** Permanently stop the manager: clear timers, listeners and any pending schedule. */
  dispose(): void;
}

/** One batch attempt. */
interface BatchOutcome {
  readonly summary: FlushSummary;
  /** Stop flushing this kind for the rest of the run. */
  readonly stop: boolean;
  /** Whether the batch failed (as opposed to simply having nothing to send). */
  readonly failed: boolean;
  /** Whether the failure was terminal (a 4xx), so records are now `failed`. */
  readonly terminal: boolean;
  /** `Retry-After` hint from the server, in milliseconds. */
  readonly retryAfterMs: number;
}

/** Empty outcome helper. */
function noBatch(): BatchOutcome {
  return {
    summary: { ...EMPTY_FLUSH_SUMMARY },
    stop: false,
    failed: false,
    terminal: false,
    retryAfterMs: 0,
  };
}

/**
 * Create the sync manager.
 *
 * @param syncOptions - see {@link SyncManagerOptions}
 * @returns a {@link SyncManager}
 *
 * @example
 * ```ts
 * import { createSyncManager, createErrorRepository, createLogRepository, resolveOptions } from '@codewithrajat/rm-logvault';
 *
 * const errors = createErrorRepository({ dbName: 'rm-logvault-errors' });
 * const logs = createLogRepository({ dbName: 'rm-logvault-logs' });
 * const manager = createSyncManager({
 *   errors,
 *   logs,
 *   options: resolveOptions({ rest: { errorsUrl: '/telemetry/errors' } }),
 *   isStorageReady: () => true,
 * });
 * manager.start();
 * ```
 */
export function createSyncManager(syncOptions: SyncManagerOptions): SyncManager {
  const config = syncOptions.options;
  const rest = config.rest;
  const endpoints = resolveEndpoints(config);
  const transport: RemoteTransport = rest.transport ?? createFetchTransport();

  // Uploads need all three: the caller must not have forced local mode, `rest` must
  // be enabled, and at least one endpoint must have survived validation.
  const enabled =
    config.mode === 'remote' &&
    rest.enabled &&
    (endpoints.errorsUrl !== undefined || endpoints.logsUrl !== undefined);

  let disposed = false;
  let timer: ReturnType<typeof setTimeout> | null = null;
  let notifyTimer: ReturnType<typeof setTimeout> | null = null;
  let onlineHandler: (() => void) | null = null;
  let onlineTarget: EventTarget | undefined;
  let running: Promise<FlushResult> | null = null;
  let failures = 0;
  let retryAfterMs = 0;
  let lastSyncAt: Timestamp | undefined;
  let currentStatus: SyncStatus = 'idle';
  let nextRunAt = 0;

  const clearScheduled = (): void => {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    if (notifyTimer !== null) {
      clearTimeout(notifyTimer);
      notifyTimer = null;
    }
  };

  const runScheduled = (): void => {
    timer = null;
    void flush(false);
  };

  /** Schedule the next run, replacing any pending schedule. */
  const schedule = (delay: number): void => {
    if (disposed || !enabled) return;
    if (timer !== null) clearTimeout(timer);
    nextRunAt = now() + delay;
    timer = setTimeout(runScheduled, Math.max(0, delay));
  };

  /** Repository and endpoint for one record kind. */
  const target = (
    kind: RecordKind,
  ): { repo: ErrorRepository | LogRepository | null; url: string | undefined } =>
    kind === 'errors'
      ? { repo: syncOptions.errors, url: endpoints.errorsUrl }
      : { repo: syncOptions.logs, url: endpoints.logsUrl };

  /**
   * Whether the caller's consent gate currently permits network egress.
   *
   * @remarks
   * Consent is re-evaluated before **every** flush, not only at storage time. A
   * user who withdraws consent must see uploads stop immediately, even for records
   * that were captured while consent was still granted — otherwise withdrawing
   * consent would only affect future captures and the already-queued outbox would
   * keep draining.
   */
  const consentGranted = (): boolean => {
    const consent = config.consent;
    if (consent === undefined) return true;
    try {
      return consent() === true;
    } catch {
      // A throwing consent gate fails closed: do not upload.
      return false;
    }
  };

  /** Claim one batch of one kind and attempt to upload it. */
  const flushBatch = async (kind: RecordKind, keepalive: boolean): Promise<BatchOutcome> => {
    const { repo, url } = target(kind);
    if (repo === null || url === undefined) return noBatch();

    const claimedAt = now();
    const claimed = await repo.claimPending(rest.batchSize, claimedAt);
    if (!claimed.ok) {
      reportInternalFailure('claim', claimed.reason);
      return {
        summary: { ...EMPTY_FLUSH_SUMMARY },
        stop: true,
        failed: false,
        terminal: false,
        retryAfterMs: 0,
      };
    }

    const records = claimed.value;
    if (records.length === 0) {
      // Nothing left in this kind: treat as "done" without counting a failure.
      return {
        summary: { ...EMPTY_FLUSH_SUMMARY, stopped: true },
        stop: true,
        failed: false,
        terminal: false,
        retryAfterMs: 0,
      };
    }

    const ids = records.map((record) => record.id);

    // Headers are resolved per request so tokens can be refreshed.
    let provided: Record<string, string> = {};
    if (rest.getHeaders !== undefined) {
      try {
        const resolved = await rest.getHeaders();
        if (resolved !== null && typeof resolved === 'object') provided = resolved;
      } catch (error) {
        // A throwing header provider is a retryable failure, not a terminal one.
        await repo.updateUploadStatus(ids, 'pending');
        reportInternalFailure('headers', error);
        return {
          summary: {
            claimed: ids.length,
            uploaded: 0,
            retried: ids.length,
            failed: 0,
            stopped: true,
          },
          stop: true,
          failed: true,
          terminal: false,
          retryAfterMs: 0,
        };
      }
    }

    const body = JSON.stringify(buildRestBody(kind, records, config, claimedAt));
    const useKeepalive = keepalive && body.length < KEEPALIVE_MAX_BYTES;

    let response: TransportResponse;
    try {
      response = await transport.send({
        url,
        headers: provided,
        credentials: rest.credentials,
        body,
        timeoutMs: REQUEST_TIMEOUT_MS,
        keepalive: useKeepalive,
        kind,
      });
    } catch (error) {
      // Transport rejection: retryable. Records go back to `pending`.
      const restored = await repo.updateUploadStatus(ids, 'pending');
      if (!restored.ok) reportInternalFailure('requeue', restored.reason);
      reportInternalFailure('flush', error);
      return {
        summary: {
          claimed: ids.length,
          uploaded: 0,
          retried: ids.length,
          failed: 0,
          stopped: true,
        },
        stop: true,
        failed: true,
        terminal: false,
        retryAfterMs: 0,
      };
    }

    const outcome = classifyResponse(response.status);

    if (outcome === 'ok') {
      // Delete only after the server has acknowledged durably.
      const deleted = await repo.delete(ids);
      if (!deleted.ok) reportInternalFailure('delete-after-upload', deleted.reason);
      return {
        summary: {
          claimed: ids.length,
          uploaded: ids.length,
          retried: 0,
          failed: 0,
          stopped: false,
        },
        stop: false,
        failed: false,
        terminal: false,
        retryAfterMs: 0,
      };
    }

    if (outcome === 'terminal') {
      const marked = await repo.updateUploadStatus(ids, 'failed');
      if (!marked.ok) reportInternalFailure('mark-failed', marked.reason);
      rest.onTerminalFailure?.(
        response.status,
        records.map((record) => ({ id: record.id })),
      );
      return {
        summary: {
          claimed: ids.length,
          uploaded: 0,
          retried: 0,
          failed: ids.length,
          stopped: true,
        },
        stop: true,
        failed: true,
        terminal: true,
        retryAfterMs: 0,
      };
    }

    // Retryable: put the batch back and stop this run.
    const restored = await repo.updateUploadStatus(ids, 'pending');
    if (!restored.ok) reportInternalFailure('requeue', restored.reason);
    return {
      summary: { claimed: ids.length, uploaded: 0, retried: ids.length, failed: 0, stopped: true },
      stop: true,
      failed: true,
      terminal: false,
      retryAfterMs: Math.min(response.retryAfterMs ?? 0, BACKOFF_MAX_MS),
    };
  };

  /** Add one batch outcome into a running summary. */
  const merge = (total: FlushSummary, part: FlushSummary): FlushSummary => ({
    claimed: total.claimed + part.claimed,
    uploaded: total.uploaded + part.uploaded,
    retried: total.retried + part.retried,
    failed: total.failed + part.failed,
    stopped: total.stopped || part.stopped,
  });

  /** The whole run: up to {@link MAX_BATCHES_PER_FLUSH} batches per kind. */
  const runFlush = async (keepalive: boolean): Promise<FlushResult> => {
    let errorSummary: FlushSummary = { ...EMPTY_FLUSH_SUMMARY };
    let logSummary: FlushSummary = { ...EMPTY_FLUSH_SUMMARY };

    if (!enabled || disposed || !syncOptions.isStorageReady()) {
      currentStatus = 'idle';
      return { errors: errorSummary, logs: logSummary };
    }

    // Consent is checked before every upload, not only before storage.
    if (!consentGranted()) {
      currentStatus = 'idle';
      errorSummary = { ...EMPTY_FLUSH_SUMMARY, stopped: true };
      logSummary = { ...EMPTY_FLUSH_SUMMARY, stopped: true };
      return { errors: errorSummary, logs: logSummary };
    }

    if (!isOnline()) {
      currentStatus = 'offline';
      errorSummary = { ...EMPTY_FLUSH_SUMMARY, stopped: true };
      logSummary = { ...EMPTY_FLUSH_SUMMARY, stopped: true };
      return { errors: errorSummary, logs: logSummary };
    }

    currentStatus = 'running';

    let errorsDone = syncOptions.errors === null || endpoints.errorsUrl === undefined;
    let logsDone = syncOptions.logs === null || endpoints.logsUrl === undefined;
    let failedThisRun = false;
    let terminalThisRun = false;
    let hint = 0;

    for (let index = 0; index < MAX_BATCHES_PER_FLUSH; index += 1) {
      if (disposed || (errorsDone && logsDone)) break;
      if (!isOnline()) break;

      if (!errorsDone) {
        const outcome = await flushBatch('errors', keepalive);
        errorSummary = merge(errorSummary, outcome.summary);
        errorsDone = outcome.stop;
        failedThisRun = failedThisRun || outcome.failed;
        terminalThisRun = terminalThisRun || outcome.terminal;
        hint = Math.max(hint, outcome.retryAfterMs);
      }

      if (!logsDone) {
        const outcome = await flushBatch('logs', keepalive);
        logSummary = merge(logSummary, outcome.summary);
        logsDone = outcome.stop;
        failedThisRun = failedThisRun || outcome.failed;
        terminalThisRun = terminalThisRun || outcome.terminal;
        hint = Math.max(hint, outcome.retryAfterMs);
      }
    }

    if (failedThisRun) {
      failures += 1;
      retryAfterMs = hint;
      currentStatus = terminalThisRun ? 'error' : 'retry';
    } else {
      failures = 0;
      retryAfterMs = 0;
      currentStatus = 'ok';
      lastSyncAt = now();
    }

    // Schedule the next run: backoff while failing, steady interval otherwise.
    if (!disposed) {
      if (failures > 0) schedule(Math.max(backoffDelay(failures), retryAfterMs));
      else schedule(rest.intervalMs);
    }

    return { errors: errorSummary, logs: logSummary };
  };

  const flush = (keepalive = false): Promise<FlushResult> => {
    if (running !== null) return running;
    if (!enabled || disposed) {
      return Promise.resolve({
        errors: { ...EMPTY_FLUSH_SUMMARY },
        logs: { ...EMPTY_FLUSH_SUMMARY },
      });
    }
    const run = runFlush(keepalive);
    running = run;
    void run.then(
      () => {
        if (running === run) running = null;
      },
      () => {
        if (running === run) running = null;
      },
    );
    return run;
  };

  const requeueStale = async (): Promise<void> => {
    const at = now();
    for (const repo of [syncOptions.errors, syncOptions.logs]) {
      if (repo === null) continue;
      const result = await repo.requeueStale(CLAIM_LEASE_MS, at);
      if (!result.ok) reportInternalFailure('requeue-stale', result.reason);
    }
  };

  return {
    start: (): void => {
      if (disposed || !enabled) return;

      // Recover anything a previous page load left mid-upload before we schedule.
      void requeueStale().then(() => {
        if (!disposed) schedule(FIRST_FLUSH_DELAY_MS);
      });

      if (onlineHandler === null) {
        const candidate = ((): EventTarget | undefined => {
          try {
            const win: unknown = Reflect.get(globalThis, 'window');
            return win !== null && typeof win === 'object' ? (win as EventTarget) : undefined;
          } catch {
            return undefined;
          }
        })();

        if (candidate !== undefined) {
          onlineTarget = candidate;
          onlineHandler = (): void => {
            // Coming back online is the moment the outbox is worth draining.
            if (!disposed) schedule(5_000);
          };
          try {
            candidate.addEventListener('online', onlineHandler);
          } catch {
            onlineHandler = null;
            onlineTarget = undefined;
          }
        }
      }
    },

    stop: (): void => {
      clearScheduled();
      if (onlineTarget !== undefined && onlineHandler !== null) {
        try {
          onlineTarget.removeEventListener('online', onlineHandler);
        } catch {
          // ignore
        }
      }
      onlineHandler = null;
      onlineTarget = undefined;
    },

    flush,

    notifyNewRecords: (): void => {
      if (disposed || !enabled) return;
      // Never while a run is in flight, and never while backing off: hammering a
      // failing endpoint with a fresh request per error is exactly what the
      // backoff exists to prevent.
      if (running !== null || failures > 0) return;
      if (notifyTimer !== null) return;

      notifyTimer = setTimeout(() => {
        notifyTimer = null;
        if (disposed || running !== null || failures > 0) return;
        // Only pull a *farther* timer forward; a nearer one is already better.
        if (timer === null) return;
        if (nextRunAt - now() <= NOTIFY_DEBOUNCE_MS) return;
        schedule(0);
      }, NOTIFY_DEBOUNCE_MS);
    },

    status: (): SyncStatus => currentStatus,

    lastSync: (): Timestamp | undefined => lastSyncAt,

    retryFailed: async (): Promise<number> => {
      let moved = 0;
      for (const [repo, kind] of [
        [syncOptions.errors, 'errors'],
        [syncOptions.logs, 'logs'],
      ] as const) {
        if (repo === null) continue;
        const failed = await repo.getFailed();
        if (!failed.ok) {
          reportInternalFailure(`retry-failed-read (${kind})`, failed.reason);
          continue;
        }
        if (failed.value.length === 0) continue;
        const ids = failed.value.map((record) => record.id);
        const updated = await repo.updateUploadStatus(ids, 'pending');
        if (!updated.ok) {
          reportInternalFailure(`retry-failed-write (${kind})`, updated.reason);
          continue;
        }
        moved += updated.value;
      }
      if (moved > 0) {
        // A manual retry is a fresh start: clear the backoff so it runs now.
        failures = 0;
        retryAfterMs = 0;
        schedule(0);
      }
      return moved;
    },

    isEnabled: (): boolean => enabled,

    dispose: (): void => {
      disposed = true;
      clearScheduled();
      if (onlineTarget !== undefined && onlineHandler !== null) {
        try {
          onlineTarget.removeEventListener('online', onlineHandler);
        } catch {
          // ignore
        }
      }
      onlineHandler = null;
      onlineTarget = undefined;
    },
  };
}
