/**
 * Fixed-window rate limiting.
 *
 * @remarks
 * A render loop that throws every frame, or a websocket reconnect storm, can
 * produce thousands of errors per second. Unbounded capture would fill the quota,
 * freeze the tab and drown the report. The limiter therefore drops excess events
 * and reports **one** summary line when the window rolls, instead of one warning
 * per dropped event.
 *
 * @packageDocumentation
 */

import { now } from './env.js';

/** Length of one rate-limit window. */
export const RATE_LIMIT_WINDOW_MS = 60_000;

/** A fixed-window counter. */
export interface RateLimiter {
  /** Whether the current call may proceed. Registers the attempt either way. */
  allow(): boolean;
  /** Events dropped in the current window. */
  dropped(): number;
  /** Events admitted in the current window. */
  admitted(): number;
  /** Drop in-flight window state. */
  reset(): void;
}

/**
 * Create a fixed-window rate limiter.
 *
 * @param maxPerWindow - maximum admitted events per 60-second window. A
 * non-positive or non-finite value disables limiting entirely.
 * @param onWindowRoll - called with the dropped count when a window rolls over;
 * only invoked when at least one event was dropped
 * @returns a {@link RateLimiter}
 *
 * @example
 * ```ts
 * import { createRateLimiter } from '@codewithrajat/rm-logvault';
 *
 * const limiter = createRateLimiter(120, (dropped) => {
 *   console.warn(`rate-limit (${dropped} dropped)`);
 * });
 *
 * if (limiter.allow()) capture();
 * ```
 */
export function createRateLimiter(
  maxPerWindow: number,
  onWindowRoll?: (dropped: number) => void,
): RateLimiter {
  const limit =
    typeof maxPerWindow === 'number' && Number.isFinite(maxPerWindow) && maxPerWindow > 0
      ? maxPerWindow
      : 0;

  let windowStart = now();
  let count = 0;
  let droppedCount = 0;

  /** Roll the window and emit the one-shot summary. */
  const roll = (current: number): void => {
    if (current - windowStart < RATE_LIMIT_WINDOW_MS) return;
    if (droppedCount > 0 && onWindowRoll !== undefined) {
      try {
        onWindowRoll(droppedCount);
      } catch {
        // An observer that throws must not stop the limiter.
      }
    }
    windowStart = current;
    count = 0;
    droppedCount = 0;
  };

  return {
    allow: (): boolean => {
      try {
        if (limit <= 0) return true;
        const current = now();
        roll(current);
        if (count >= limit) {
          droppedCount += 1;
          return false;
        }
        count += 1;
        return true;
      } catch {
        // Failing open is correct here: losing telemetry is worse than a burst.
        return true;
      }
    },
    dropped: (): number => droppedCount,
    admitted: (): number => count,
    reset: (): void => {
      windowStart = now();
      count = 0;
      droppedCount = 0;
    },
  };
}
