/**
 * Helpers shared by the two IndexedDB repositories.
 *
 * @packageDocumentation
 */

import type { UploadStatus } from '../core/types.js';
import { promisifyRequest } from './idbCore.js';
import type { CleanupPolicy } from './storage.types.js';

/**
 * Delete every primary key returned by a cursor-based scan.
 *
 * @param store - the object store to scan
 * @param match - predicate deciding whether a row is deleted
 * @param onMalformed - called for rows that fail validation, which are deleted too
 * @returns the number of deleted rows
 */
export async function deleteMatching<T>(
  store: IDBObjectStore,
  match: (value: T) => boolean,
  onMalformed?: (value: unknown) => boolean,
): Promise<number> {
  let deleted = 0;
  await new Promise<void>((resolve, reject) => {
    const request = store.openCursor();
    request.onerror = (): void => {
      reject(request.error ?? new Error('cursor failed'));
    };
    request.onsuccess = (): void => {
      const cursor = request.result;
      if (cursor === null) {
        resolve();
        return;
      }
      const value = cursor.value as unknown;
      const malformed = onMalformed?.(value) ?? false;
      if (malformed || match(value as T)) {
        cursor.delete();
        deleted += 1;
      }
      cursor.continue();
    };
  });
  return deleted;
}

/**
 * Apply a retention policy to a store.
 *
 * @param store - the object store to clean
 * @param policy - retention days and hard record cap
 * @param timestampOf - reads the timestamp used for age comparison
 * @param now - current time
 * @param isValid - row validator; failing rows are deleted
 * @returns the number of rows removed
 *
 * @remarks
 * Two passes, in this order:
 * 1. Age: delete anything older than `retentionDays`.
 * 2. Overflow: if more than `maxRecords` remain, delete the oldest surplus.
 *
 * Malformed rows are removed during both passes.
 */
export async function cleanupStore<T>(
  store: IDBObjectStore,
  policy: CleanupPolicy,
  timestampOf: (value: T) => number,
  now: number,
  isValid: (value: unknown) => boolean,
): Promise<number> {
  let removed = 0;

  const cutoff =
    policy.retentionDays > 0 ? now - policy.retentionDays * 86_400_000 : Number.NEGATIVE_INFINITY;

  // Pass 1: age and malformed rows.
  removed += await deleteMatching<T>(
    store,
    (value) => {
      const timestamp = timestampOf(value);
      return !Number.isFinite(timestamp) || timestamp < cutoff;
    },
    (value) => !isValid(value),
  );

  if (!Number.isFinite(policy.maxRecords) || policy.maxRecords <= 0) {
    return removed;
  }

  // Pass 2: collect survivors, then delete the oldest surplus.
  const survivors: { key: IDBValidKey; timestamp: number }[] = [];
  await new Promise<void>((resolve, reject) => {
    const request = store.openCursor();
    request.onerror = (): void => {
      reject(request.error ?? new Error('cursor failed'));
    };
    request.onsuccess = (): void => {
      const cursor = request.result;
      if (cursor === null) {
        resolve();
        return;
      }
      const value = cursor.value as unknown;
      if (isValid(value)) {
        survivors.push({ key: cursor.primaryKey, timestamp: timestampOf(value as T) });
      }
      cursor.continue();
    };
  });

  if (survivors.length <= policy.maxRecords) return removed;

  survivors.sort((a, b) => a.timestamp - b.timestamp);
  const surplus = survivors.slice(0, survivors.length - policy.maxRecords);
  for (const entry of surplus) {
    await promisifyRequest(store.delete(entry.key));
    removed += 1;
  }
  return removed;
}

/**
 * Move rows between upload states.
 *
 * @param store - the object store to mutate
 * @param ids - primary keys to update
 * @param status - the new state
 * @param now - current time, recorded when the new state is `uploading`
 * @returns the number of rows actually updated
 */
export async function updateStatuses(
  store: IDBObjectStore,
  ids: readonly string[],
  status: UploadStatus,
  now: number,
): Promise<number> {
  let updated = 0;
  for (const id of ids) {
    const raw = await promisifyRequest<unknown>(store.get(id));
    if (raw === null || raw === undefined || typeof raw !== 'object') continue;
    const record = { ...(raw as Record<string, unknown>) };
    record['uploadStatus'] = status;
    if (status === 'uploading') record['claimedAt'] = now;
    else delete record['claimedAt'];
    await promisifyRequest(store.put(record));
    updated += 1;
  }
  return updated;
}

/**
 * Delete rows by primary key.
 *
 * @param store - the object store to mutate
 * @param ids - primary keys to delete
 * @returns the number of `delete` requests issued
 */
export async function deleteByIds(store: IDBObjectStore, ids: readonly string[]): Promise<number> {
  let deleted = 0;
  for (const id of ids) {
    await promisifyRequest(store.delete(id));
    deleted += 1;
  }
  return deleted;
}

/** Halve a cleanup policy's record cap, for the quota-recovery retry. */
export function halvedPolicy(policy: CleanupPolicy): CleanupPolicy {
  return {
    retentionDays: policy.retentionDays,
    maxRecords: Math.max(1, Math.floor(policy.maxRecords / 2)),
  };
}

/** Sort a list of records newest-first by a timestamp accessor. */
export function sortNewestFirst<T>(items: T[], timestampOf: (value: T) => number): T[] {
  return items.sort((a, b) => timestampOf(b) - timestampOf(a));
}
