/**
 * The hidden keyboard shortcut that produces a diagnostics report.
 *
 * @remarks
 * The shortcut exists so a support engineer can say "press Ctrl+Shift+Alt+D and
 * send me the file" without shipping a debug menu, a query-string flag or a
 * customer-specific build.
 *
 * Two things are worth being explicit about:
 *
 * - **It is obscurity, not access control.** The report contains only data
 *   already stored locally on that machine, and that data is already sanitized.
 *   Anyone who knows the shortcut can produce a report; if that is unacceptable,
 *   gate it with `allow()` — for example on an internal-users flag.
 * - **It must survive hostile layouts and hostile pages.** Matching is done on
 *   `KeyboardEvent.code` (the *physical* key) with `event.key` as a fallback,
 *   because `Alt`+letter mangles `event.key` on AZERTY, Dvorak, AltGr and macOS
 *   Option layouts. The listener is attached in the **capture** phase on
 *   `document`, so a `stopPropagation()` elsewhere in the page cannot swallow it.
 *
 * @packageDocumentation
 */

import { getDocument, getEventTarget } from '../core/env.js';
import type { DiagnosticsExportOptions } from './diagnosticsExport.js';
import { exportDiagnosticsReport } from './diagnosticsExport.js';

/** Resolved shortcut configuration. */
export interface ShortcutConfig {
  /** The key to require. A single letter or digit. */
  readonly key: string;
  readonly ctrl: boolean;
  readonly shift: boolean;
  readonly alt: boolean;
  readonly meta: boolean;
  /** Event target. Defaults to `document`. */
  readonly target?: EventTarget | undefined;
  /** Gate evaluated on every match; `false` suppresses the trigger. */
  readonly allow?: (() => boolean) | undefined;
}

/** Default key. Combined with the default modifiers this is Ctrl+Shift+Alt+D. */
export const DEFAULT_KEY = 'd';

/** Default configuration: Ctrl + Shift + Alt + D. */
export const DEFAULT_SHORTCUT_CONFIG: ShortcutConfig = {
  key: DEFAULT_KEY,
  ctrl: true,
  shift: true,
  alt: true,
  meta: false,
};

/** Editable contexts in which the shortcut must stay silent. */
const EDITABLE_SELECTOR = [
  'input',
  'textarea',
  'select',
  '[contenteditable=""]',
  '[contenteditable="true"]',
  '[contenteditable="plaintext-only"]',
].join(',');

/**
 * Expected `KeyboardEvent.code` for a configured key.
 *
 * @param key - a single letter or digit
 * @returns `Key<X>` / `Digit<N>`, or `undefined` for anything else
 *
 * @example
 * ```ts
 * import { expectedCode } from '@codewithrajat/rm-logvault';
 *
 * expectedCode('d'); // 'KeyD'
 * expectedCode('7'); // 'Digit7'
 * ```
 */
export function expectedCode(key: string): string | undefined {
  if (/^[a-z]$/i.test(key)) return `Key${key.toUpperCase()}`;
  if (/^[0-9]$/.test(key)) return `Digit${key}`;
  return undefined;
}

/**
 * Whether a keyboard event matches the configuration.
 *
 * @param event - the keyboard event
 * @param config - the resolved configuration
 * @returns `true` on an exact match of key **and** every modifier
 *
 * @remarks
 * Modifier matching is **exact**: pressing Ctrl+Shift+Alt+D with an extra Meta held
 * does not match, which prevents accidental triggers on OS-level shortcuts.
 *
 * @example
 * ```ts
 * import { matchesShortcut, DEFAULT_SHORTCUT_CONFIG } from '@codewithrajat/rm-logvault';
 *
 * document.addEventListener('keydown', (event) => {
 *   if (matchesShortcut(event, DEFAULT_SHORTCUT_CONFIG)) console.log('hit');
 * }, true);
 * ```
 */
export function matchesShortcut(event: KeyboardEvent, config: ShortcutConfig): boolean {
  try {
    if (event.ctrlKey !== config.ctrl) return false;
    if (event.shiftKey !== config.shift) return false;
    if (event.altKey !== config.alt) return false;
    if (event.metaKey !== config.meta) return false;

    const code = expectedCode(config.key);
    const eventCode = typeof event.code === 'string' ? event.code : '';

    // Physical key first — `event.key` is unreliable under Alt/AltGr.
    if (code !== undefined && eventCode === code) return true;

    // Fallback for environments that do not populate `code`.
    const eventKey = typeof event.key === 'string' ? event.key : '';
    return eventKey.toLowerCase() === config.key.toLowerCase();
  } catch {
    return false;
  }
}

/**
 * Whether the event target is a text-entry context.
 *
 * @param target - the event target
 * @returns `true` for an `<input>`, `<textarea>`, `<select>` or editable host
 *
 * @remarks
 * Without this check the shortcut would fire — and `preventDefault()` the key —
 * while someone is typing "d" into a form, which is a data-loss bug.
 */
export function isEditableTarget(target: EventTarget | null | undefined): boolean {
  if (target === null || target === undefined) return false;
  try {
    const closest: unknown = Reflect.get(target as object, 'closest');
    if (typeof closest === 'function') {
      const match = Reflect.apply(closest, target, [EDITABLE_SELECTOR]) as unknown;
      if (match !== null && match !== undefined) return true;
    }
  } catch {
    // A detached or exotic node: fall through to the tag-name check.
  }

  try {
    const tagName: unknown = Reflect.get(target as object, 'tagName');
    if (typeof tagName === 'string') {
      const tag = tagName.toLowerCase();
      if (tag === 'input' || tag === 'textarea' || tag === 'select') return true;
    }
  } catch {
    // ignore
  }
  return false;
}

/** Resolve a partial configuration into a complete one. */
function resolveConfig(config: Partial<ShortcutConfig> | undefined): ShortcutConfig {
  const key =
    typeof config?.key === 'string' && config.key.trim().length > 0
      ? config.key.trim()
      : DEFAULT_SHORTCUT_CONFIG.key;
  return {
    key,
    ctrl: config?.ctrl ?? DEFAULT_SHORTCUT_CONFIG.ctrl,
    shift: config?.shift ?? DEFAULT_SHORTCUT_CONFIG.shift,
    alt: config?.alt ?? DEFAULT_SHORTCUT_CONFIG.alt,
    meta: config?.meta ?? DEFAULT_SHORTCUT_CONFIG.meta,
    target: config?.target,
    allow: config?.allow,
  };
}

/**
 * Install a keyboard shortcut.
 *
 * @param config - partial configuration; omitted members take their default
 * @param onTrigger - called when the shortcut fires
 * @returns a cleanup function. Calling it twice is safe.
 *
 * @example
 * ```ts
 * import { installShortcut } from '@codewithrajat/rm-logvault';
 *
 * const cleanup = installShortcut({ key: 'k', ctrl: true, shift: false, alt: false },
 *   () => console.log('fired'));
 * cleanup();
 * ```
 */
export function installShortcut(
  config: Partial<ShortcutConfig> | undefined,
  onTrigger: () => void,
): () => void {
  const resolved = resolveConfig(config);
  // `document` by default so the capture-phase listener is as close to the top of
  // the DOM as possible without racing other window-level listeners.
  const target = resolved.target ?? getDocument() ?? getEventTarget();
  if (target === undefined) {
    // SSR or a worker: install nothing and hand back a no-op cleanup.
    return (): void => undefined;
  }

  const handler = (event: Event): void => {
    try {
      const keyboard = event as KeyboardEvent;
      if (!matchesShortcut(keyboard, resolved)) return;
      if (isEditableTarget(keyboard.target)) return;
      if (resolved.allow !== undefined) {
        try {
          if (resolved.allow() !== true) return;
        } catch {
          return;
        }
      }
      event.preventDefault();
    } catch {
      // A malformed event must not stop the page from working.
      return;
    }

    try {
      onTrigger();
    } catch {
      // The trigger is the caller's code; its failures are not ours to surface.
    }
  };

  try {
    target.addEventListener('keydown', handler, true);
  } catch {
    return (): void => undefined;
  }

  return (): void => {
    try {
      target.removeEventListener('keydown', handler, true);
    } catch {
      // ignore
    }
  };
}

/** Options for {@link installDiagnosticsExportShortcut}. */
export interface DiagnosticsShortcutOptions extends Partial<ShortcutConfig> {
  /** Filename prefix passed to the export. */
  readonly filenamePrefix?: string | undefined;
  /** Forwarded to `exportDiagnosticsReport`. */
  readonly exportOptions?: DiagnosticsExportOptions | undefined;
  /** Called with the export outcome. */
  readonly onExported?: ((ok: boolean) => void) | undefined;
}

/**
 * Install the default diagnostics-export shortcut (Ctrl+Shift+Alt+D).
 *
 * @param options - configuration. Pass `false` to install nothing.
 * @returns a cleanup function that removes the listener.
 *
 * @remarks
 * The listener is attached in the **capture** phase, so `stopPropagation()` in
 * application code cannot prevent the report. Events whose target is an editable
 * element are ignored, and `preventDefault()` is called only on a real match.
 *
 * @example
 * ```ts
 * import { installDiagnosticsExportShortcut } from '@codewithrajat/rm-logvault';
 *
 * // Attached automatically by initTelemetry; install manually if you disabled it.
 * const cleanup = installDiagnosticsExportShortcut({
 *   key: 'd',
 *   allow: () => window.__IS_INTERNAL__ === true,
 *   onExported: (ok) => console.log(ok ? 'report downloaded' : 'report failed'),
 * });
 *
 * cleanup();
 * ```
 */
export function installDiagnosticsExportShortcut(
  options?: DiagnosticsShortcutOptions | false,
): () => void {
  if (options === false) return (): void => undefined;

  const { filenamePrefix, exportOptions, onExported, ...shortcut } = options ?? {};

  return installShortcut(shortcut, (): void => {
    // The export reports its own outcome through `onExported` on every path it
    // handles, so the result is deliberately discarded here.
    void exportDiagnosticsReport({
      ...exportOptions,
      ...(filenamePrefix !== undefined ? { filenamePrefix } : {}),
      ...(onExported !== undefined ? { onExported } : {}),
    });
  });
}
