/**
 * Storage schema constants.
 *
 * @remarks
 * `VERSION` values are a compatibility contract. Bumping a version is a MAJOR
 * change to the library's semver, because it changes the on-disk format that a
 * previously installed version already wrote. Migrations are strictly additive:
 * a shipped version number is never edited, and `upgrade` is idempotent so it can
 * re-run after a user deletes the database mid-session.
 *
 * @packageDocumentation
 */

/** Schema version of the errors database. */
export const ERRORS_DB_VERSION = 1;

/** Schema version of the logs database. */
export const LOGS_DB_VERSION = 1;

/** Object store holding error records. */
export const ERRORS_STORE = 'errors';

/** Object store holding log records. */
export const LOGS_STORE = 'logs';

/** Errors index on `['fingerprint', 'uploadStatus']`, used for pending-only aggregation. */
export const ERRORS_INDEX_FINGERPRINT_STATUS = 'by_fingerprint_status';

/** Errors index on `uploadStatus`. */
export const ERRORS_INDEX_STATUS = 'by_status';

/** Logs index on `['uploadStatus', 'timestamp']`. */
export const LOGS_INDEX_STATUS_TIMESTAMP = 'by_status_timestamp';

/** Logs index on `timestamp`. */
export const LOGS_INDEX_TIMESTAMP = 'by_timestamp';

/** Run error retention every N writes. */
export const ERROR_CLEANUP_EVERY_WRITES = 25;

/** Run log retention every N writes. */
export const LOG_CLEANUP_EVERY_WRITES = 200;

/** Default number of rows returned by `getPending` / `claimPending`. */
export const DEFAULT_PENDING_LIMIT = 100;
