/**
 * The log persistence tracker.
 *
 * @remarks
 * Registered as a sink on the logger, so it sees every call that reaches the
 * logger regardless of the console level. It then applies the *persist* level —
 * which is deliberately independent, so `logger.setLevel('off')` silences output
 * without silencing storage.
 *
 * Writes are batched: a log storm produces one IndexedDB transaction per
 * `logs.writeBatchSize` entries (default 50), with `logs.writeFlushMs` (default
 * 1000 ms) as the upper bound on how long a record can sit in memory. Both are
 * options; `DEFAULT_OPTIONS` sources them from the constants that were previously
 * hardcoded here, so the defaults cannot drift. The tracker also flushes on
 * `pagehide` and on `visibilitychange -> hidden`, because those are the last
 * moments a browser reliably lets a page write.
 *
 * @packageDocumentation
 */

import type { ResolvedTelemetryOptions } from '../core/config.js';
import { reportInternalFailure, reportInternalNote } from '../core/internal.js';
import { createSerialQueue } from '../core/queue.js';
import { createRateLimiter } from '../core/rateLimit.js';
import { reduceLogPayload } from '../errors/payload.js';
import type { LogRepository } from '../storage/storage.types.js';
import { meetsLevel } from './logger.constants.js';
import type { LogRecord, LogSink } from './logger.types.js';

/** Options for {@link createLogTracker}. */
export interface LogTrackerOptions {
  /** Where records are persisted. */
  readonly repository: LogRepository;
  /** Resolved configuration. */
  readonly options: ResolvedTelemetryOptions;
  /** Called for every accepted record, so the sync manager can pull a timer forward. */
  readonly onRecord?: ((record: LogRecord) => void) | undefined;
}

/** The log pipeline for one initialization. */
export interface LogTracker {
  /** The sink to register with the logger. */
  readonly sink: LogSink;
  /** Persist everything currently buffered and wait for the queue to settle. */
  flush(): Promise<void>;
  /** Number of records dropped by the rate limiter in the current window. */
  droppedByRateLimit(): number;
  /** Stop accepting records and persist what is buffered. */
  destroy(): Promise<void>;
}

/**
 * Create the log tracker.
 *
 * @param trackerOptions - see {@link LogTrackerOptions}
 * @returns a {@link LogTracker}
 *
 * @example
 * ```ts
 * import { createLogTracker, createLogRepository, resolveOptions, logger } from '@codewithrajat/rm-logvault';
 *
 * const tracker = createLogTracker({
 *   repository: createLogRepository({ dbName: 'rm-logvault-logs' }),
 *   options: resolveOptions({ logs: { level: 'info' } }),
 * });
 * logger.addSink(tracker.sink);
 * ```
 */
export function createLogTracker(trackerOptions: LogTrackerOptions): LogTracker {
  const { repository, options: config } = trackerOptions;
  const queue = createSerialQueue();

  /** Records accepted but not yet handed to IndexedDB. */
  let pending: LogRecord[] = [];
  let timer: ReturnType<typeof setTimeout> | null = null;
  let destroyed = false;

  const limiter = createRateLimiter(config.logs.maxLogsPerMinute, (dropped) => {
    reportInternalNote('rate-limit', `${String(dropped)} dropped`);
  });

  /** Whether the caller's consent gate currently permits storage. */
  const consentGranted = (): boolean => {
    const consent = config.consent;
    if (consent === undefined) return true;
    try {
      return consent() === true;
    } catch {
      // Fail closed: no consent, no storage.
      return false;
    }
  };

  const clearTimer = (): void => {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  };

  /** Persist the current buffer immediately. */
  const flushNow = async (): Promise<void> => {
    clearTimer();
    if (pending.length === 0) return;
    const batch = pending;
    pending = [];

    const result = await queue.push(() => repository.saveBatch(batch));
    if (result !== undefined && !result.ok) {
      reportInternalFailure('persist', result.reason);
    }
  };

  const sink: LogSink = {
    name: '@codewithrajat/rm-logvault-indexeddb',
    write: (record: LogRecord): void => {
      try {
        if (destroyed) return;
        if (!config.logs.enabled) return;
        // Persist level is independent of the console level.
        if (!meetsLevel(record.level, config.logs.level)) return;
        if (!consentGranted()) return;
        if (!limiter.allow()) return;

        let candidate = record;

        const beforeStore = config.logs.beforeStore;
        if (beforeStore !== undefined) {
          try {
            const replacement = beforeStore(candidate);
            if (replacement === null) return;
            candidate = replacement;
          } catch (error) {
            reportInternalFailure('beforeStore', error);
          }
        }

        const fitted = reduceLogPayload(candidate, config.logs.maxPayloadBytes);
        if (fitted === null) {
          reportInternalFailure(
            'payload-limit',
            new Error('log record exceeded its payload budget at every reduction tier'),
          );
          return;
        }

        pending.push(fitted);
        try {
          trackerOptions.onRecord?.(fitted);
        } catch {
          // Observers must not break logging.
        }

        if (pending.length >= config.logs.writeBatchSize) {
          void flushNow();
        } else if (timer === null) {
          timer = setTimeout(() => {
            timer = null;
            void flushNow();
          }, config.logs.writeFlushMs);
        }
      } catch (error) {
        reportInternalFailure('log-tracker', error);
      }
    },
  };

  return {
    sink,

    flush: async (): Promise<void> => {
      await flushNow();
      await queue.drain();
    },

    droppedByRateLimit: (): number => limiter.dropped(),

    destroy: async (): Promise<void> => {
      if (destroyed) return;
      // Persist what is buffered before shutting the door.
      try {
        await flushNow();
      } catch {
        // ignore
      }
      destroyed = true;
      clearTimer();
      pending = [];
      queue.clear();
    },
  };
}
