/**
 * Redaction and serialisation of untrusted values.
 *
 * @remarks
 * This module is the library's security boundary. Every record passes through it
 * **before** it is written to IndexedDB and again **before** it is exported or
 * uploaded, so a value that slips through here leaks to disk and to the network.
 *
 * Three invariants hold under all inputs, including hostile ones:
 *
 * 1. **Never throws.** Any internal exception degrades to `[REDACTED]` (text) or
 *    `[Unserializable]` (values). The library fails closed, not open.
 * 2. **Bounded work.** Input is hard-truncated before any regular expression runs,
 *    depth/keys/array-length are capped, so a 5 MB message cannot hang a tab and
 *    no pattern can be driven into catastrophic backtracking.
 * 3. **Bounded, JSON-safe output.** The result of `sanitizeValue` is always
 *    structured-cloneable and `JSON.stringify`-safe.
 *
 * @packageDocumentation
 */

import { safeGet } from '../core/env.js';
import {
  AUTH_SCHEME_PATTERN,
  DEFAULT_ALLOWED_QUERY_PARAMS,
  EMAIL_PATTERN,
  HARD_TEXT_CAP,
  JWT_PATTERN,
  KV_SECRET_PATTERNS,
  LONG_SECRET_PATTERN,
  LONG_SECRET_TEXT_PATTERN,
  MAX_ALLOWED_QUERY_VALUE_LENGTH,
  MAX_ARRAY_ITEMS,
  MAX_DEPTH,
  MAX_KEYS,
  MAX_MESSAGE_LENGTH,
  MAX_STACK_LENGTH,
  MAX_STRING_LENGTH,
  MAX_URL_LENGTH,
  REDACTED,
  SENSITIVE_KEY_PATTERN,
  STACK_QUERY_PATTERN,
  truncationSuffix,
} from './constants.js';

/** Keys that are never copied, to keep prototype pollution impossible. */
const FORBIDDEN_KEYS: ReadonlySet<string> = new Set(['__proto__', 'constructor', 'prototype']);

/** Marker used when an object or array was cut short. */
const OVERFLOW_KEY = '…';

/** Caller-supplied extensions to the default redaction rules. */
export interface SanitizerConfig {
  /**
   * Extra key names or patterns treated as sensitive. A string matches the
   * separator-stripped, lowercased key exactly; a `RegExp` is tested against both
   * the raw key and its normalised form.
   */
  readonly extraSensitiveKeys?: readonly (string | RegExp)[] | undefined;
  /** Extra patterns applied to free text after the built-in rules. */
  readonly extraPatterns?: readonly RegExp[] | undefined;
  /** Query parameter names whose values survive redaction. */
  readonly allowedQueryParams?: readonly string[] | undefined;
}

/** The sanitizer surface. Obtain one from {@link createSanitizer}. */
export interface Sanitizer {
  /** Scrub one line of free text. Never throws. */
  readonly text: (input: unknown, maxLength?: number) => string;
  /** Scrub an error stack, dropping query-string cache busters. Never throws. */
  readonly stack: (input: unknown, maxLength?: number) => string;
  /** Scrub a URL. Returns `undefined` for non-strings and empty input. */
  readonly url: (input: unknown, maxLength?: number) => string | undefined;
  /** Deep-scrub any value into a bounded, JSON-safe structure. Never throws. */
  readonly value: (input: unknown, key?: string) => unknown;
  /** Whether a key name is treated as sensitive. */
  readonly isSensitiveKey: (key: string) => boolean;
}

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

/** Run `RegExp.test` without leaving `lastIndex` state behind on `/g` patterns. */
function testRe(re: RegExp, value: string): boolean {
  if (re.global || re.sticky) {
    re.lastIndex = 0;
    const result = re.test(value);
    re.lastIndex = 0;
    return result;
  }
  return re.test(value);
}

/** Replace using a `/g` pattern, resetting `lastIndex` before and after. */
function replaceAll(value: string, re: RegExp, replacement: string): string {
  re.lastIndex = 0;
  const result = value.replace(re, replacement);
  re.lastIndex = 0;
  return result;
}

/**
 * Truncate to at most `max` characters, appending `…[truncated N]`.
 *
 * @remarks
 * The suffix is counted inside the budget so the returned length never exceeds
 * `max`, which keeps downstream UTF-8 byte accounting predictable.
 */
function truncate(value: string, max: number): string {
  if (value.length <= max) return value;
  if (max <= 0) return '';
  const suffix = truncationSuffix(value.length);
  if (suffix.length >= max) return value.slice(0, max);
  const keep = max - suffix.length;
  const dropped = value.length - keep;
  return value.slice(0, keep) + truncationSuffix(dropped);
}

/** Coerce an arbitrary value to text without ever throwing. */
function toText(input: unknown): string {
  if (typeof input === 'string') return input;
  if (input === null || input === undefined) return '';
  if (typeof input === 'object') {
    const message = safeGet(input, 'message');
    if (typeof message === 'string') return message;
  }
  try {
    return String(input);
  } catch {
    return REDACTED;
  }
}

/** Strip `[-_\s]` and lowercase, so `access-token` and `access token` agree. */
function normalizeKeyName(key: string): string {
  return key.toLowerCase().replace(/[-_\s]/g, '');
}

/** Decode a percent-encoded path segment, falling back to the raw text. */
function safeDecode(segment: string): string {
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
}

/** Read DOM facts without importing DOM globals at module scope. */
function domKind(value: object): string | undefined {
  const nodeType = safeGet(value, 'nodeType');
  const tagName = safeGet(value, 'tagName');
  if (nodeType === 1 && typeof tagName === 'string') {
    return `[Element ${tagName.toLowerCase()}]`;
  }
  const type = safeGet(value, 'type');
  const hasTarget = safeGet(value, 'target') !== undefined;
  const hasPreventDefault = typeof safeGet(value, 'preventDefault') === 'function';
  if (typeof type === 'string' && hasTarget && hasPreventDefault) {
    return `[Event ${type}]`;
  }
  return undefined;
}

/** Duck-typed Error check that works across realms and with exotic Error subclasses. */
function isErrorLike(value: object): boolean {
  const name = safeGet(value, 'name');
  const message = safeGet(value, 'message');
  if (typeof message !== 'string') return false;
  return typeof name === 'string' || typeof safeGet(value, 'stack') === 'string';
}

// ---------------------------------------------------------------------------
// Factory
// ---------------------------------------------------------------------------

/**
 * Build a sanitizer with optional caller-supplied extensions.
 *
 * @param config - extra sensitive keys, extra text patterns and the query
 * parameter allow-list. Invalid entries are ignored rather than throwing.
 * @returns a {@link Sanitizer}
 *
 * @example
 * ```ts
 * import { createSanitizer } from '@codewithrajat/rm-logvault';
 *
 * const sanitize = createSanitizer({
 *   extraSensitiveKeys: ['x-tenant-id', /^internal/i],
 *   extraPatterns: [/\b\d{16}\b/g],           // credit-card-ish
 *   allowedQueryParams: ['page', 'locale'],
 * });
 *
 * sanitize.text('token=abc123 page=2');
 * // 'token=[REDACTED] page=2'
 * ```
 */
export function createSanitizer(config: SanitizerConfig = {}): Sanitizer {
  /** Normalised extra string keys, for exact matching. */
  const extraKeys: readonly (string | RegExp)[] = Array.isArray(config.extraSensitiveKeys)
    ? config.extraSensitiveKeys.filter(
        (entry): entry is string | RegExp => typeof entry === 'string' || entry instanceof RegExp,
      )
    : [];

  const extraPatterns: readonly RegExp[] = Array.isArray(config.extraPatterns)
    ? config.extraPatterns.filter((entry): entry is RegExp => entry instanceof RegExp)
    : [];

  const allowedQueryParams: ReadonlySet<string> = new Set(
    (Array.isArray(config.allowedQueryParams)
      ? config.allowedQueryParams
      : DEFAULT_ALLOWED_QUERY_PARAMS
    )
      .filter((entry): entry is string => typeof entry === 'string')
      .map((entry) => entry.toLowerCase()),
  );

  /** Sensitive key test used both for object keys and for query parameters. */
  const isSensitiveKey = (key: string): boolean => {
    try {
      const normalized = normalizeKeyName(key);
      if (testRe(SENSITIVE_KEY_PATTERN, normalized)) return true;
      for (const extra of extraKeys) {
        if (typeof extra === 'string') {
          if (normalizeKeyName(extra) === normalized) return true;
        } else if (testRe(extra, key) || testRe(extra, normalized)) {
          return true;
        }
      }
      return false;
    } catch {
      // Unknown extension behaviour: fail closed.
      return true;
    }
  };

  /** Whether a query parameter's value may be kept. */
  const isAllowedQueryKey = (key: string): boolean => {
    const lower = key.toLowerCase();
    return allowedQueryParams.has(lower) && !isSensitiveKey(key);
  };

  /**
   * Scrub free text: URLs, JWTs, authorisation schemes, `key=value` secrets and
   * e-mail addresses, in that order.
   */
  const scrub = (input: string, maxLength: number): string => {
    // Bound the work before any regex runs.
    let text = input.length > HARD_TEXT_CAP ? input.slice(0, HARD_TEXT_CAP) : input;

    // 1. URLs embedded in the text.
    text = text.replace(/\b(?:https?|blob):\/\/[^\s"'<>()[\]]+/gi, (match) => {
      const sanitized = sanitizeUrlValue(match, MAX_URL_LENGTH);
      return sanitized ?? REDACTED;
    });
    text = text.replace(/\bdata:[^\s"'<>]+/gi, 'data:[REDACTED]');

    // 2. JWTs.
    text = replaceAll(text, JWT_PATTERN, REDACTED);

    // 3. `Bearer <secret>` / `Basic <secret>` / `Token <secret>`.
    text = replaceAll(text, AUTH_SCHEME_PATTERN, '$1 [REDACTED]');

    // 4. `token=...`, `password=...`, `api_key=...` groups, separators preserved.
    for (const pattern of KV_SECRET_PATTERNS) {
      text = replaceAll(text, pattern, '$1[REDACTED]');
    }

    // 5. Long opaque tokens with no key=value context (API keys, session ids).
    text = replaceAll(text, LONG_SECRET_TEXT_PATTERN, `$1${REDACTED}`);

    // 6. E-mail addresses.
    text = replaceAll(text, EMAIL_PATTERN, REDACTED);

    // 7. Caller-supplied patterns last, so they win over everything above.
    for (const pattern of extraPatterns) {
      text = replaceAll(text, pattern, REDACTED);
    }

    return truncate(text, maxLength);
  };

  /** Scrub a single URL path segment. */
  const sanitizeSegment = (segment: string): string => {
    if (segment.length === 0) return segment;
    try {
      const decoded = safeDecode(segment);
      if (testRe(EMAIL_PATTERN, decoded)) return REDACTED;
      if (decoded.startsWith('eyJ')) return REDACTED;
      if (LONG_SECRET_PATTERN.test(decoded)) return REDACTED;
      return segment;
    } catch {
      return REDACTED;
    }
  };

  /** Scrub every segment of a path while preserving its shape. */
  const sanitizePath = (pathname: string): string => {
    if (pathname.length === 0) return pathname;
    return pathname.split('/').map(sanitizeSegment).join('/');
  };

  /** Rebuild a query string, redacting every non-allow-listed value. */
  const buildQuery = (pairs: readonly (readonly [string, string])[], prefix: string): string => {
    if (pairs.length === 0) return '';
    const parts: string[] = [];
    for (const [key, value] of pairs) {
      if (isAllowedQueryKey(key)) {
        const kept = truncate(value, MAX_ALLOWED_QUERY_VALUE_LENGTH);
        parts.push(`${encodeURIComponent(key)}=${encodeURIComponent(kept)}`);
      } else {
        parts.push(`${encodeURIComponent(key)}=${REDACTED}`);
      }
    }
    return parts.length > 0 ? `${prefix}${parts.join('&')}` : '';
  };

  /** Read all `[key, value]` pairs out of a `URLSearchParams`. */
  const readPairs = (params: URLSearchParams): [string, string][] => {
    const pairs: [string, string][] = [];
    try {
      params.forEach((value, key) => {
        pairs.push([key, value]);
      });
    } catch {
      // Malformed params: ignore.
    }
    return pairs;
  };

  /** Core URL scrubber, shared by `text` and `url`. */
  const sanitizeUrlValue = (input: string, maxLength: number): string | undefined => {
    const raw = input.trim();
    if (raw.length === 0) return undefined;

    try {
      const absolute = /^[a-z][a-z0-9+.-]*:/i.test(raw);

      if (absolute) {
        let parsed: URL;
        try {
          parsed = new URL(raw);
        } catch {
          return truncate(raw.split(/[?#]/)[0] ?? raw, maxLength);
        }
        const scheme = parsed.protocol.toLowerCase();
        if (scheme === 'data:') return 'data:[REDACTED]';
        // Anything that is not normal web navigation is opaque to us.
        if (scheme !== 'http:' && scheme !== 'https:') return `${scheme}${REDACTED}`;

        // Rebuilding from protocol//host inherently drops `user:pass@`.
        const origin = `${parsed.protocol}//${parsed.host}`;
        const path = sanitizePath(parsed.pathname);
        const query = buildQuery(readPairs(parsed.searchParams), '?');
        return truncate(`${origin}${path}${query}`, maxLength);
      }

      // Relative input stays relative. A raw whitespace character cannot appear in
      // a URL, so input containing one is prose that merely looks URL-ish: keep the
      // text before the query/fragment rather than pretending to parse it.
      if (/\s/.test(raw)) {
        const cut = raw.search(/[?#]/);
        return truncate(cut >= 0 ? raw.slice(0, cut) : raw, maxLength);
      }

      let rest = raw;
      const hashIndex = rest.indexOf('#');
      if (hashIndex >= 0) rest = rest.slice(0, hashIndex);
      const queryIndex = rest.indexOf('?');
      const pathPart = queryIndex >= 0 ? rest.slice(0, queryIndex) : rest;
      const queryPart = queryIndex >= 0 ? rest.slice(queryIndex + 1) : '';
      const query =
        queryPart.length > 0 ? buildQuery(readPairs(new URLSearchParams(queryPart)), '?') : '';
      return truncate(`${sanitizePath(pathPart)}${query}`, maxLength);
    } catch {
      // Unparsable: keep only the part before the query/fragment.
      const cut = raw.search(/[?#]/);
      return truncate(cut >= 0 ? raw.slice(0, cut) : raw, maxLength);
    }
  };

  /** Depth-limited, cycle-safe walker behind `sanitizeValue`. */
  const walk = (
    value: unknown,
    key: string | undefined,
    depth: number,
    seen: WeakSet<object>,
  ): unknown => {
    try {
      // A sensitive KEY wins over whatever the value happens to be.
      if (key !== undefined && isSensitiveKey(key)) return REDACTED;

      if (value === null) return null;

      // The depth cap applies to every value, primitives included, so a deeply
      // nested structure is bounded uniformly rather than only where it branches.
      if (depth > MAX_DEPTH) return '[MaxDepth]';

      switch (typeof value) {
        case 'string':
          return scrub(value, MAX_STRING_LENGTH);
        case 'number':
          return Number.isFinite(value) ? value : String(value);
        case 'boolean':
          return value;
        case 'bigint':
          return String(value);
        case 'symbol':
          return String(value);
        case 'undefined':
          return null;
        case 'function':
          return '[Function]';
        default:
          break;
      }

      // From here `value` is a non-null object.
      const object = value as object;

      if (seen.has(object)) return '[Circular]';

      if (typeof globalThis.Event !== 'undefined' && object instanceof Event) {
        return `[Event ${String(safeGet(object, 'type'))}]`;
      }
      if (typeof globalThis.Element !== 'undefined' && object instanceof Element) {
        const tagName = safeGet(object, 'tagName');
        return `[Element ${typeof tagName === 'string' ? tagName.toLowerCase() : 'unknown'}]`;
      }
      const dom = domKind(object);
      if (dom !== undefined) return dom;

      if (object instanceof Date) {
        const time = object.getTime();
        return Number.isFinite(time) ? object.toISOString() : 'Invalid Date';
      }

      if (object instanceof Error || isErrorLike(object)) {
        return {
          name: scrub(toText(safeGet(object, 'name')), MAX_MESSAGE_LENGTH),
          message: scrub(toText(safeGet(object, 'message')), MAX_MESSAGE_LENGTH),
        };
      }

      seen.add(object);

      if (Array.isArray(object)) {
        const output: unknown[] = [];
        const length = Math.min(object.length, MAX_ARRAY_ITEMS);
        for (let index = 0; index < length; index += 1) {
          output.push(walk(object[index], undefined, depth + 1, seen));
        }
        if (object.length > MAX_ARRAY_ITEMS) {
          output.push(`[+${String(object.length - MAX_ARRAY_ITEMS)}]`);
        }
        seen.delete(object);
        return output;
      }

      if (object instanceof Set) {
        const output: unknown[] = [];
        let index = 0;
        for (const entry of object) {
          if (index >= MAX_ARRAY_ITEMS) break;
          output.push(walk(entry, undefined, depth + 1, seen));
          index += 1;
        }
        if (object.size > MAX_ARRAY_ITEMS) {
          output.push(`[+${String(object.size - MAX_ARRAY_ITEMS)}]`);
        }
        seen.delete(object);
        return output;
      }

      if (object instanceof Map) {
        const entries: [string, unknown][] = [];
        let index = 0;
        for (const [entryKey, entryValue] of object) {
          if (index >= MAX_KEYS) break;
          const name = typeof entryKey === 'string' ? entryKey : toText(entryKey);
          entries.push([name, walk(entryValue, name, depth + 1, seen)]);
          index += 1;
        }
        if (object.size > MAX_KEYS) {
          entries.push([OVERFLOW_KEY, `[+${String(object.size - MAX_KEYS)} keys]`]);
        }
        seen.delete(object);
        return Object.fromEntries(entries);
      }

      let names: string[];
      try {
        names = Object.keys(object);
      } catch {
        return '[Unserializable]';
      }

      const entries: [string, unknown][] = [];
      const limit = Math.min(names.length, MAX_KEYS);
      for (let index = 0; index < limit; index += 1) {
        const name = names[index];
        if (name === undefined || FORBIDDEN_KEYS.has(name)) continue;
        // A getter that throws must be recorded as unreadable, not silently
        // reported as `null` — the difference matters when triaging a report.
        let child: unknown;
        try {
          child = (object as Record<string, unknown>)[name];
        } catch {
          entries.push([name, '[Unserializable]']);
          continue;
        }
        entries.push([name, walk(child, name, depth + 1, seen)]);
      }
      if (names.length > MAX_KEYS) {
        entries.push([OVERFLOW_KEY, `[+${String(names.length - MAX_KEYS)} keys]`]);
      }
      seen.delete(object);
      // `Object.fromEntries` defines own data properties, so copying a literal
      // `__proto__` key cannot mutate any prototype.
      return Object.fromEntries(entries);
    } catch {
      return '[Unserializable]';
    }
  };

  return {
    text: (input: unknown, maxLength: number = MAX_STRING_LENGTH): string => {
      try {
        return scrub(toText(input), maxLength);
      } catch {
        return REDACTED;
      }
    },
    stack: (input: unknown, maxLength: number = MAX_STACK_LENGTH): string => {
      try {
        const raw = toText(input);
        const bounded = raw.length > HARD_TEXT_CAP ? raw.slice(0, HARD_TEXT_CAP) : raw;
        return scrub(replaceAll(bounded, STACK_QUERY_PATTERN, ''), maxLength);
      } catch {
        return REDACTED;
      }
    },
    url: (input: unknown, maxLength: number = MAX_URL_LENGTH): string | undefined => {
      try {
        if (typeof input !== 'string') return undefined;
        return sanitizeUrlValue(input, maxLength);
      } catch {
        return REDACTED;
      }
    },
    value: (input: unknown, key?: string): unknown => {
      try {
        return walk(input, key, 0, new WeakSet<object>());
      } catch {
        return '[Unserializable]';
      }
    },
    isSensitiveKey,
  };
}

/**
 * The sanitizer used when no custom redaction options are configured.
 */
const builtInSanitizer: Sanitizer = createSanitizer();

/**
 * The sanitizer every module reaches for.
 *
 * @remarks
 * `initTelemetry` swaps this for one built from `options.redaction`, so
 * configuration applies to *all* sanitization — record building, the logger, URL
 * classification and the diagnostics export — rather than only to the paths that
 * happen to receive the options object.
 */
let activeSanitizer: Sanitizer = builtInSanitizer;

/**
 * Install a configuration-derived sanitizer.
 *
 * @param sanitizer - the sanitizer to use process-wide
 *
 * @example
 * ```ts
 * import { createSanitizer, setDefaultSanitizer } from '@codewithrajat/rm-logvault';
 *
 * setDefaultSanitizer(createSanitizer({ extraSensitiveKeys: ['x-tenant-id'] }));
 * ```
 */
export function setDefaultSanitizer(sanitizer: Sanitizer): void {
  activeSanitizer = sanitizer;
}

/** Restore the built-in sanitizer. Called by `destroyTelemetry`. */
export function resetDefaultSanitizer(): void {
  activeSanitizer = builtInSanitizer;
}

/**
 * Scrub one line of free text.
 *
 * @param input - any value; non-strings are coerced via `.message` or `String()`
 * @param maxLength - character budget, default `2000`
 * @returns the scrubbed text. Never throws; returns `[REDACTED]` on failure.
 *
 * @example
 * ```ts
 * import { sanitizeText } from '@codewithrajat/rm-logvault';
 *
 * sanitizeText('GET /me failed with Authorization: Bearer eyJhbGciOi...');
 * // 'GET /me failed with Authorization: Bearer [REDACTED]'
 *
 * sanitizeText('mail me at dev@example.com');
 * // 'mail me at [REDACTED]'
 * ```
 */
export function sanitizeText(input: unknown, maxLength?: number): string {
  return activeSanitizer.text(input, maxLength);
}

/**
 * Scrub a URL, redacting credentials, fragments and every non-allow-listed query value.
 *
 * @param input - the candidate URL
 * @param maxLength - character budget, default `2000`
 * @returns the scrubbed URL, or `undefined` when the input is not a non-empty string
 *
 * @example
 * ```ts
 * import { sanitizeUrl } from '@codewithrajat/rm-logvault';
 *
 * sanitizeUrl('https://u:p@api.test/v1/users/42?token=abc&page=2#top');
 * // 'https://api.test/v1/users/42?token=[REDACTED]&page=2'
 *
 * sanitizeUrl('/orders/103?email=a@b.co');
 * // '/orders/103?email=[REDACTED]'
 * ```
 */
export function sanitizeUrl(input: unknown, maxLength?: number): string | undefined {
  return activeSanitizer.url(input, maxLength);
}

/**
 * Scrub an error stack, dropping Vite-style `?t=` cache busters first.
 *
 * @param input - the stack text
 * @param maxLength - character budget, default `8000`
 *
 * @example
 * ```ts
 * import { sanitizeStack } from '@codewithrajat/rm-logvault';
 *
 * sanitizeStack('at App (/src/App.tsx?t=1712345:12:3)');
 * // 'at App (/src/App.tsx:12:3)'
 * ```
 */
export function sanitizeStack(input: unknown, maxLength?: number): string {
  return activeSanitizer.stack(input, maxLength);
}

/**
 * Deep-scrub any value into a bounded, JSON-safe structure.
 *
 * @param input - the value to scrub
 * @param key - optional property name; a sensitive name forces `[REDACTED]`
 *
 * @example
 * ```ts
 * import { sanitizeValue } from '@codewithrajat/rm-logvault';
 *
 * sanitizeValue({ user: 'ada', accessToken: 'abc', deep: { a: { b: { c: 1 } } } });
 * // { user: 'ada', accessToken: '[REDACTED]', deep: { a: { b: '[MaxDepth]' } } }
 *
 * const circular: Record<string, unknown> = {};
 * circular.self = circular;
 * sanitizeValue(circular); // { self: '[Circular]' }
 * ```
 */
export function sanitizeValue(input: unknown, key?: string): unknown {
  return activeSanitizer.value(input, key);
}

/** Whether a key name is treated as sensitive by the active rules. */
export function isSensitiveKey(key: string): boolean {
  return activeSanitizer.isSensitiveKey(key);
}

/** Access the sanitizer currently in force. */
export function getDefaultSanitizer(): Sanitizer {
  return activeSanitizer;
}

/** Access the built-in sanitizer, ignoring any configured override. */
export function getBuiltInSanitizer(): Sanitizer {
  return builtInSanitizer;
}
