/**
 * Error fingerprinting and deduplication keys.
 *
 * @remarks
 * A fingerprint answers "is this the same bug?" for two failures that are not
 * object-identical: the same handler throwing from the same frame with the same
 * message, across two tabs or two page loads. It is computed from **already
 * sanitized** fields only, so a fingerprint can never leak a secret into an index.
 *
 * @packageDocumentation
 */

import { unfingerprintedId } from '../core/ids.js';
import {
  DIGITS_ONLY_PATTERN,
  FINGERPRINT_SEPARATOR,
  LONG_HEX_PATTERN,
  UUID_PATTERN,
} from './constants.js';
import type {
  ApiErrorContext,
  ErrorCategory,
  ErrorEventInfo,
  ErrorLocation,
  ErrorSource,
} from './types.js';

/** Path segments that look like identifiers, replaced with `:id` for grouping. */
const ID_SEGMENT = ':id';

/** How many stack frames participate in a fingerprint. */
export const FINGERPRINT_STACK_FRAMES = 5;

/** How many component-stack frames participate in a fingerprint. */
export const FINGERPRINT_COMPONENT_FRAMES = 3;

/**
 * `cyrb53` — a fast, well-distributed 53-bit string hash.
 *
 * @param input - the string to hash
 * @param seed - hash seed
 * @returns an integer in `[0, 2^53)`
 *
 * @remarks
 * Chosen over a cryptographic digest because fingerprints are computed on the hot
 * error path and are not a security boundary — they are a grouping key. Two
 * independent seeds are combined into a 28-hex-character fingerprint, giving ~106
 * bits and making accidental collisions negligible for realistic error volumes.
 */
export function cyrb53(input: string, seed = 0): number {
  let h1 = 0xdeadbeef ^ seed;
  let h2 = 0x41c6ce57 ^ seed;

  for (let index = 0; index < input.length; index += 1) {
    const ch = input.charCodeAt(index);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }

  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);

  return 4294967296 * (2097151 & h2) + (h1 >>> 0);
}

/** Render a 53-bit hash as a fixed-width 14-character hex string. */
function hex14(value: number): string {
  return value.toString(16).padStart(14, '0');
}

/**
 * Normalise a path for fingerprinting so that instance identifiers do not split
 * one logical route into thousands of groups.
 *
 * @param input - a route, a full URL, or `undefined`
 * @returns the path with the query and fragment dropped, and numeric / UUID /
 * long-hex segments collapsed to `:id`
 *
 * @example
 * ```ts
 * import { normalizePathForFingerprint } from '@codewithrajat/rm-logvault';
 *
 * normalizePathForFingerprint('/asset/103?tab=1');       // '/asset/:id'
 * normalizePathForFingerprint('/asset/104');             // '/asset/:id'
 * normalizePathForFingerprint('/o/8f3c…-…-…');           // '/o/:id'
 * ```
 */
export function normalizePathForFingerprint(input: string | undefined): string {
  if (input === undefined || input.length === 0) return '';
  try {
    let path = input;
    const hashIndex = path.indexOf('#');
    if (hashIndex >= 0) path = path.slice(0, hashIndex);
    const queryIndex = path.indexOf('?');
    if (queryIndex >= 0) path = path.slice(0, queryIndex);

    return path
      .split('/')
      .map((segment) => {
        if (segment.length === 0) return segment;
        if (DIGITS_ONLY_PATTERN.test(segment)) return ID_SEGMENT;
        if (UUID_PATTERN.test(segment)) return ID_SEGMENT;
        if (LONG_HEX_PATTERN.test(segment)) return ID_SEGMENT;
        return segment;
      })
      .join('/');
  } catch {
    return '';
  }
}

/**
 * Pick the most identifying stack frames.
 *
 * @param stack - raw or sanitized stack text
 * @param count - maximum frames to keep
 * @returns the frames joined with `|`, or `''`
 */
export function topStackFrames(stack: string | undefined, count: number): string {
  if (stack === undefined || stack.length === 0) return '';
  const frames: string[] = [];
  try {
    for (const line of stack.split('\n')) {
      const trimmed = line.trim();
      if (trimmed.startsWith('at ') || trimmed.includes('@')) {
        frames.push(trimmed);
        if (frames.length >= count) break;
      }
    }
  } catch {
    return '';
  }
  return frames.join('|');
}

/** Everything that contributes to a fingerprint. All fields must be pre-sanitized. */
export interface FingerprintInput {
  readonly source: ErrorSource | string;
  readonly category: ErrorCategory | string;
  readonly name: string;
  readonly message: string;
  readonly stack?: string | undefined;
  readonly componentStack?: string | undefined;
  /** Already-normalised route, or a raw path that will be normalised here. */
  readonly route?: string | undefined;
  readonly api?: Pick<ApiErrorContext, 'kind' | 'method' | 'url' | 'status'> | undefined;
  readonly event?: Pick<ErrorEventInfo, 'type' | 'resourceUrl' | 'directive'> | undefined;
  readonly location?: ErrorLocation | undefined;
}

/**
 * Build the ordered list of parts hashed into a fingerprint.
 *
 * @param input - see {@link FingerprintInput}
 * @returns the parts, in the documented order
 */
export function fingerprintParts(input: FingerprintInput): string[] {
  const parts: string[] = [
    String(input.source),
    String(input.category),
    input.name,
    input.message,
    topStackFrames(input.stack, FINGERPRINT_STACK_FRAMES),
    topStackFrames(input.componentStack, FINGERPRINT_COMPONENT_FRAMES),
    normalizePathForFingerprint(input.route),
  ];

  const api = input.api;
  if (api !== undefined) {
    parts.push(
      String(api.kind ?? ''),
      String(api.method ?? '').toUpperCase(),
      normalizePathForFingerprint(api.url),
    );
    parts.push(api.status === undefined ? '' : String(api.status));
  } else {
    parts.push('', '', '', '');
  }

  const event = input.event;
  if (event !== undefined) {
    parts.push(
      String(event.type ?? ''),
      normalizePathForFingerprint(event.resourceUrl),
      String(event.directive ?? ''),
    );
  } else {
    parts.push('', '', '');
  }

  // Location is a last resort: only consulted when there is no stack to identify
  // the failure by, otherwise the same throw site would split into many groups.
  const hasStack = topStackFrames(input.stack, 1).length > 0;
  if (!hasStack) {
    const location = input.location;
    parts.push(
      location === undefined
        ? ''
        : `${String(location.source ?? '')}:${String(location.line ?? '')}:${String(location.column ?? '')}`,
    );
  } else {
    parts.push('');
  }

  return parts;
}

/** Monotonic counter backing the unfingerprinted fallback. */
let fallbackAttempt = 0;

/**
 * Compute a stable, collision-resistant deduplication fingerprint.
 *
 * @param input - the sanitized record fields that identify the failure
 * @returns a 28-character lowercase hex fingerprint, or an
 * `unfingerprinted-…` token if hashing somehow fails
 *
 * @example
 * ```ts
 * import { fingerprint } from '@codewithrajat/rm-logvault';
 *
 * fingerprint({ source: 'window', category: 'runtime', name: 'TypeError', message: 'x is not a function' });
 * // '3f9a1c2b7d4e01f5b6c7d8e9a0b1'
 * ```
 */
export function fingerprint(input: FingerprintInput): string {
  try {
    const joined = fingerprintParts(input).join(FINGERPRINT_SEPARATOR);
    const first = hex14(cyrb53(joined, 1));
    const second = hex14(cyrb53(joined, 2));
    return `${first}${second}`;
  } catch {
    fallbackAttempt += 1;
    return unfingerprintedId(fallbackAttempt);
  }
}
